window.__CHRONICLE_CHUNK["cn-18"] = [
  {"id": "cn--b86--p01", "track": "cn", "year": -86, "yearApprox": false, "dim": "politics", "weight": 4, "title": "霍光等受遗诏辅幼主", "summary": "大司马大将军光秉政，四人同拜卧内受诏。", "detail": {"background": "武帝将立幼子弗陵，以「主少母壮」为忧，责钩弋夫人死，以防后妃临朝；又以为霍光「出入禁闼二十余年，小心谨慎，未尝有过」，使画工图周公负成王朝诸侯之象以赐之。", "process": "前86年六月昭帝立，年八岁；以光为大司马大将军，金日磾为车骑将军，太仆上官桀为左将军，搜粟都尉桑弘羊为御史大夫，「皆拜卧内床下，受遗诏辅少主」；光让金日磾，日磾辞曰「臣外国人，且使匈奴轻汉」，于是遂为光副；光领尚书事，天下事壹关决焉，帝委而听之。", "impact": "权力重心由丞相府移入禁中，「内朝官领尚书事」自此定形：宰相不专机要，而大司马大将军录尚书事成为两千年权臣的标准头衔。这一年同时确立了以宗庙礼制约束外戚、以禁军与尚书控制朝廷的辅政模式。", "figures": ["霍光", "金日磾", "上官桀", "桑弘羊", "弗陵"], "place": "长安未央宫", "state": "西汉", "sources": ["《汉书·霍光金日磾传》", "《汉书·昭帝纪》", "《汉书·车千秋传》"], "tags": ["霍光辅政", "领尚书事", "内朝"]}, "related": ["cn--b87--p01", "cn--b91--p01"]},
  {"id": "cn--b85--s01", "track": "cn", "year": -85, "yearApprox": false, "dim": "science", "weight": 4, "title": "赵过行代田法与耦犁", "summary": "一亩三甽岁代处，作耦犁耧车，用力少而得多。", "detail": {"background": "轮台诏后以「力本农」为国是，而郡国民惰于耕、器用苦恶、牛马不足；搜粟都尉赵过能为代田，先试之于公田，令边卒习耕，乃推于民。", "process": "其法「一亩三甽，岁代处」：亩中开三沟，播种于沟内，苗长则拔垄上之草附根而培之，来年沟垄互易，以垄为休耕、以沟为集雨抗旱；用耦犁二牛三人以深耕，又作三脚耧车，一过三垄，开沟、下种、覆土同时而毕，可日种一顷；令田官与工徒自铸铁器，教边郡及民。", "impact": "代田把休耕、集雨抗旱与畜力深耕制度化，史称「用力少而得谷多」，收常过缦田一斛以上；推广及于边郡、居延、云中、河东、太常与三辅。三脚耧是世界最早的畜力条播机，欧洲到十八世纪才有同类播种器具。", "figures": ["赵过", "田千秋", "弗陵"], "place": "三辅及边郡居延、云中、河东", "state": "西汉", "sources": ["《汉书·食货志》", "《氾胜之书》辑本", "居延汉简"], "tags": ["代田法", "耦犁", "三脚耧车"]}, "related": ["cn--b89--p01"]},
  {"id": "cn--b82--i01", "track": "cn", "year": -82, "yearApprox": false, "dim": "institution", "weight": 3, "title": "罢临屯真番二郡", "summary": "省四郡为二，玄菟东迁，乐浪以南入汉郡。", "detail": {"background": "朝鲜四郡地广民寡，北界秽、貊，东阻大海，越三千里而守一城，吏卒廪食皆仰海运与辽东转运，实控之力不逮。", "process": "前82年（始元五年）汉罢临屯郡，以其民并入乐浪；又省真番郡入玄菟，玄菟郡治遂东北徙于上殷县一带，高句丽、沃沮诸部改隶焉。", "impact": "这是汉帝国第一次主动收缩东方郡县，标示以郡县直接统治辽东以东的限界；此后以乐浪、玄菟为支点，属国、候、三老与册封并用，成为中原王朝经营朝鲜半岛与东北亚的长期模式。", "figures": ["弗陵", "霍光"], "place": "乐浪、玄菟（今朝鲜平壤与辽宁新宾一带）", "state": "西汉", "sources": ["《汉书·地理志》", "《汉书·昭帝纪》", "《三国志·东夷传》"], "tags": ["汉四郡", "郡县收缩", "羁縻"]}, "related": ["cn--b108--i01"]},
  {"id": "cn--b81--c01", "track": "cn", "year": -81, "yearApprox": false, "dim": "culture", "weight": 5, "title": "盐铁会议论禁榷利害", "summary": "诏郡国举贤良文学问民间疾苦，共执盐铁酒榷之便否。", "detail": {"background": "武帝末年均输、平准、盐铁、酒榷、算缗诸利尽归公上，民困于赋役而吏缘为奸；昭帝初年经费仍不足，郡国多废耕业。始元六年（前81）诏天下举贤良文学六十余人至京师，由御史大夫桑弘羊与丞相田千秋承问，就民间疾苦逐条发难。", "process": "贤良文学主张官府盐铁则器物苦恶、价格不平，吏催督使农民弃耒耜而就末作，均输平准名为均平实为与民争利，故请罢之，返利于民，以务农省用为本。桑弘羊反驳：盐铁之利以佐边境军费、赡给戍卒，一旦罢之则经费无所出、边备自虚；均输可以平万物、通委财，是制四夷而强国之势，不可废。双方往复诘难，兼及北边和战、币制、法令与德治之辨。", "impact": "朝廷最后罢酒榷而盐铁仍旧，政策并未全盘转向，但把武帝一朝的财政路线第一次公开置于批判之下。宣帝时桓宽据会议记录推衍为《盐铁论》六十篇，是研究汉代经济政策与士人政治观最完整的对话体文献；其中「县官与民争利」之论，成为此后两千年反对禁榷聚敛的标准论据。", "figures": ["桑弘羊", "田千秋", "桓宽"], "place": "长安", "state": "西汉", "sources": ["《盐铁论》", "《汉书·昭帝纪》", "《汉书·食货志》"], "tags": ["盐铁会议", "贤良文学", "禁榷之辩"]}, "related": ["cn--b119--e01", "cn--b110--e01", "cn--b85--s01"]},
  {"id": "cn--b81--x01", "track": "cn", "year": -81, "yearApprox": false, "dim": "explore", "weight": 4, "title": "苏武归汉拜典属国", "summary": "常惠教汉使以雁足帛书诘单于，匈奴诡言武死乃败；武与存者九人归，拜典属国。", "detail": {"background": "昭帝即位数年，匈奴与汉和亲。汉求武等，匈奴诡言武死。后汉使复至匈奴，常惠请其守者与俱，得夜见汉使。具自陈过。教使者谓单于，言天子射上林中，得雁，足有系帛书，言武等在荒泽中。使者大喜，如惠语以让单于。单于视左右而惊，谢汉使曰：「武等实在。」", "process": "单于召会武官属，前以降及物故，凡随武还者九人。武以始元六年春至京师。诏武奉一太牢谒武帝园庙，拜为典属国，秩中二千石，赐钱二百万，公田二顷，宅一区。常惠、徐圣、赵终根皆拜为中郎，赐帛各二百匹。其余六人老归家，赐钱人十万，复终身。常惠后至右将军，封列侯，自有传。武留匈奴凡十九岁，始以强壮出，及还，须发尽白。于是李陵置酒贺武曰：「今足下还归，扬名于匈奴，功显于汉室，虽古竹帛所载，丹青所画，何以过子卿！陵虽驽怯，令汉且贳陵罪，全其老母，使得奋大辱之积志，庶几乎曹柯之盟，此陵宿昔之所不忘也。收族陵家，为世大戮，陵尚复何顾乎？已矣！令子卿知吾心耳。异域之人，壹别长绝！」陵起舞，歌曰：「径万里兮度沙幕，为君将兮奋匈奴。路穷绝兮矢刃摧，士众灭兮名已聩。老母已死，虽欲报恩将安归！」陵泣下数行，因与武决。", "impact": "出使时「武与副中郎将张胜及假吏常惠等募士斥候百余人俱。」，归时「前以降及物故，凡随武还者九人。」——百余人出、九人还，本传给的唯一一组前后对照数。李陵置酒所贺：「今足下还归，扬名于匈奴，功显于汉室，虽古竹帛所载，丹青所画，何以过子卿！」；别歌：「径万里兮度沙幕，为君将兮奋匈奴。路穷绝兮矢刃摧，士众灭兮名已聩。老母已死，虽欲报恩将安归！」 ◆ 系年：本传此处书年号「始元六年」；其后公元换算为维基文库编者所加，非正文。本条 year 取该年号，为前81年。◆ 雁足帛书是常惠教汉使的设辞，本传明书「教使者谓单于，言……」，非天子实有帛书；引此段不得当作史实中的占验。", "figures": ["苏武", "常惠", "李陵", "且鞮侯单于", "徐圣", "赵终根"], "place": "长安及匈奴单于庭", "state": "西汉", "sources": ["《汉书·卷五十四·李广苏建传》"], "tags": ["苏武", "雁足书", "典属国"]}, "related": ["cn--b100--x03", "cn--b99--m01", "cn--b80--p02"]},
  {"id": "cn--b80--p01", "track": "cn", "year": -80, "yearApprox": false, "dim": "politics", "weight": 4, "title": "上官桀桑弘羊之变与燕王旦案", "summary": "谋除霍光、废帝立旦，事觉，一党尽族。", "detail": {"background": "昭帝年十四，燕王刘旦以武帝长子自居不服辅政；上官桀因子安世谋夺霍光之权，与桑弘羊、盖长公主结为党，使人伪为燕王上书，历数霍光「专权自恣」，请得入宿卫。", "process": "元凤元年（前80）其谋发露：霍光称病以观其变，郎署上书者言变书不敬当诛，帝遂命收捕；桀、安世、弘羊及其与党尽族诛，坐死者数千人。同年燕王旦与宗正刘泽谋反事觉，旦置酒与夫人作歌「归空城兮狗不吠，鸡不鸣」而自杀，刘泽伏诛，燕国除为郡。", "impact": "此役之后霍光威震海内，公卿以下不敢异言；宣帝初即位，朝谒大将军，「若有芒刺在背」。它确立了一条规则：政本在禁中与领尚书事者，丞相、御史不能与之争，此制贯穿整个西汉后期。", "figures": ["霍光", "上官桀", "桑弘羊", "刘旦", "刘泽"], "place": "长安及燕国（今北京一带）", "state": "西汉", "sources": ["《汉书·霍光金日磾传》", "《汉书·武五子传》"], "tags": ["元凤政变", "霍光专权", "宗室削国"]}, "related": ["cn--b86--p01", "cn--b74--p01"]},
  {"id": "cn--b80--i01", "track": "cn", "year": -80, "yearApprox": false, "dim": "institution", "weight": 2, "title": "省禁苑假民公田", "summary": "减乘舆苑囿，以公田假贫民而薄其租。", "detail": {"background": "武帝以来上林、水衡所属苑囿占田辽阔，贫民无地而流冗；昭帝时以「与民休息」为国是，欲省宫廷之费而业农。", "process": "元凤年间前后诏省减乘舆马苑、水衡苑囿，「假与城郭、乡邑贫民」耕之，租税从轻；并省小黄门、乐府与太官侈费，令民得入谷于边郡以除罪、以受爵。", "impact": "假民公田自此成为汉代安置无地与流亡农民的常法：田仍是官有，农民只取得租佃之「假」，此制为后世官田、职田、屯佃之制提供雏形，也是国家在土地问题上「不均田而给佃」的典型选择。", "figures": ["弗陵", "霍光"], "place": "三辅上林苑及郡国", "state": "西汉", "sources": ["《汉书·昭帝纪》", "《汉书·食货志》"], "tags": ["假民公田", "省禁苑", "流亡安置"]}, "related": ["cn--b89--p01", "cn--b85--s01"]},
  {"id": "cn--b80--p02", "track": "cn", "year": -80, "yearApprox": false, "dim": "politics", "weight": 3, "title": "苏武以子元坐谋反死，霍光寝奏免武官", "summary": "归汉明年，子元坐燕王谋反死；廷尉奏请逮捕武，霍光寝其奏，免武官。", "detail": {"background": "武来归明年，上官桀、子安与桑弘羊及燕王、盖主谋反。武子男元与安有谋，坐死。初，桀、安与大将军霍光争权，数疏光过失予燕王，令上书告之。又言苏武使匈奴二十年不降，还乃为典属国，大将军长史无功劳，为搜粟都尉，光颛权自恣。", "process": "及燕王等反诛，穷治党与，武素与桀、弘羊有旧，数为燕王所讼，子又在谋中，廷尉奏请逮捕武。霍光寝其奏，免武官。", "impact": "十九年不降之人，在汉朝的狱辞里几乎与自己的儿子同列：「廷尉奏请逮捕武。霍光寝其奏，免武官。」致罪之由不是功过，而是上官桀一方曾以「苏武使匈奴二十年不降，还乃为典属国」攻击霍光颛权，苏武由此被写进了政敌的奏章——本传把这句攻击一并留了下来。◆ year 据本传「武来归明年」自始元六年（前81）推一年为元凤元年（前80），系本传明文纪序而非臆测，故 yearApprox=false。", "figures": ["苏武", "上官桀", "上官安", "桑弘羊", "霍光", "燕王旦"], "place": "长安", "state": "西汉", "sources": ["《汉书·卷五十四·李广苏建传》"], "tags": ["苏武", "燕王之狱", "霍光"]}, "related": ["cn--b81--x01", "cn--b60--f01"]},
  {"id": "cn--b74--p01", "track": "cn", "year": -74, "yearApprox": false, "dim": "politics", "weight": 5, "title": "昌邑王贺在位二十七日见废", "summary": "受皇帝玺绶，行淫乱失节，为霍光所废。", "detail": {"background": "元平元年（前74）四月昭帝崩，年二十一，无嗣。霍光与张安世定议，以广陵王胥「好游猎、无威仪」不可立，乃迎武帝兄孙、昌邑王刘贺，使使者持节迎之。", "process": "刘贺六月至长安，即皇帝位，行故昌邑之国凡百二十日而实未改元？在位二十七日，征发故国吏民车载物一千五百余乘，「居丧无礼」，日夜饮宴，与女子杂居；霍光忧懑，与田延年、杨敞等定策，奏皇太后，诏废贺，令归故国，赐黄金千斤，食邑三千户，其群臣二百余人以「辅导不谨」被诛，临行贺叹「猫乃死耳」。", "impact": "这是权臣以皇太后诏废帝的第一次完整成功：它同时证明霍光可以立、可以废，也迫使后继者宣帝在朝谒时「若有芒刺在背」；昌邑一系的属吏集团被连根拔起，中央与侯国之间的人身依附关系由此整顿。", "figures": ["刘贺", "霍光", "杨敞", "田延年"], "place": "长安及昌邑（今山东巨野）", "state": "西汉", "sources": ["《汉书·霍光金日磾传》", "《汉书·武五子传》", "《资治通鉴·汉纪》"], "tags": ["废昏立明", "霍光定策", "昌邑王"]}, "related": ["cn--b80--p01", "cn--b74--p02"]},
  {"id": "cn--b74--p02", "track": "cn", "year": -74, "yearApprox": false, "dim": "politics", "weight": 5, "title": "立皇曾孙病是为宣帝", "summary": "取狱中婴儿于民间，汉统复归卫太子一系。", "detail": {"background": "刘据兵败而死，皇孙刘病已方在襁褓，系长安郡邸狱；廷尉监丙吉选宽厚者二人以乳养之，逢赦得免，属籍宗正，生长于民间，好游侠，往来长安、三辅之间。", "process": "昌邑王既废，御史大夫丙吉与大将军长史皆上书，言宗室贤者唯皇曾孙；遂以元平元年（前74）秋七月迎立之，是曰宣帝。宣帝即位之初，事事关白大将军，谨让而已，权一出霍氏。", "impact": "皇统回到卫太子一系，是西汉后期政治合法性的关键一环；宣帝因起于民间，深知吏治得失与百姓疾苦，故为政「自上总领名责实」，信用能吏而抑儒生之论，史称「孝宣之治，信赏必罚，综核名实」，与武帝末年的疲敝形成对照。", "figures": ["刘病已", "丙吉", "霍光"], "place": "长安", "state": "西汉", "sources": ["《汉书·宣帝纪》", "《汉书·丙吉传》", "《资治通鉴·汉纪》"], "tags": ["宣帝即位", "郡邸狱", "孝宣中兴"]}, "related": ["cn--b74--p01", "cn--b91--p01"]},
  {"id": "cn--b71--m01", "track": "cn", "year": -71, "yearApprox": false, "dim": "military", "weight": 4, "title": "十五万骑五道出塞合击匈奴", "summary": "本始三年汉军五道并出，乌孙兵自西相应。", "detail": {"background": "匈奴连年入边，又西击乌孙，取车师田卒；本始三年（前71）汉大举谋报，遣将军凡五道并出。", "process": "汉以步骑十五万分五道出塞：度辽将军出张掖、前将军出云中、虎牙将军出五原、祁连将军出酒泉、蒲类将军出西河，各率骑二万余，期会；乌孙昆弟翁归靡亦自发其众击右谷蠡王庭。汉军出塞各数百千里，所获少而罢费甚，多遇空庐；乌孙则「获单于叔父、诸王名号者，四万余级，牛马七十余万」。", "impact": "这是汉军规模最大的多路合围，虽未取得歼灭战果，却让匈奴同时受北、西、东三方压力；同年冬单于自乌孙引还，遇大雨雪，人马冻死者什六七，属国多叛，匈奴由此转弱，是双方力量关系的转折点之一。", "figures": ["范明友", "赵充国", "翁归靡", "壶衍鞮单于"], "place": "五原至天山一线", "state": "西汉", "sources": ["《汉书·匈奴传》", "《汉书·西域传》", "《汉书·昭帝纪》"], "tags": ["五道出塞", "乌孙夹击", "匈奴之衰"]}, "related": ["cn--b119--i01", "cn--b71--x01"]},
  {"id": "cn--b71--x01", "track": "cn", "year": -71, "yearApprox": false, "dim": "explore", "weight": 3, "title": "解忧公主与乌孙、龟兹", "summary": "汉宗女两世嫁乌孙，通使城郭国，兄弟为昆弟。", "detail": {"background": "细君公主卒后，汉复以楚王刘戊之孙为江都王女，号解忧公主，续嫁乌孙，居赤谷城，与匈奴、西域诸国处于夹缝之间。", "process": "乌孙昆弟翁归靡上书请「为解忧公主家室」与汉并力，许以共击匈奴；公主三子二女，元为乌孙嗣子，长子元以后为汉所立，其弟女适龟兹王，龟兹王来朝于汉；汉以长罗侯常惠持节护之。", "impact": "和亲在乌孙变成有军事实效的联盟：乌孙三万骑与汉军夹击匈奴，正出此盟；而公主之女为龟兹后，使汉的典章、乐舞与吏员西入塔里木盆地，龟兹乐与汉使节由此常通，成为都护府建立的政治前提。", "figures": ["解忧", "翁归靡", "常惠"], "place": "乌孙赤谷城（今伊塞克湖一带）", "state": "西汉", "sources": ["《汉书·西域传》", "《资治通鉴·汉纪》"], "tags": ["和亲", "乌孙", "龟兹"]}, "related": ["cn--b126--x01", "cn--b71--m01"]},
  {"id": "cn--b70--i01", "track": "cn", "year": -70, "yearApprox": false, "dim": "institution", "weight": 2, "title": "边郡属国处降者", "summary": "置属国都尉，因其故俗而籍其胜兵。", "detail": {"background": "自元狩以来匈奴、羌胡降者日众，散处边郡，既须养赡，又须防其翻覆；昭宣之间乌桓、羌人内属者复多。", "process": "本始、地节间于张掖、西河、酒泉、天水等郡置属国都尉，「主降者」，不改其部族、君长与畜牧之俗，唯以汉使领护，籍其胜兵之数，使分处要地、有事征发；属国置丞、置候，秩比二千石，独立于郡。", "impact": "属国制度以「不易其俗而收其兵用」为原则，成为汉唐处置内附游牧部族的模板，后世羁縻府州、内附部落皆由此演化；它既给边郡提供了骑兵与劳力，也造成东汉以后并居边郡的部族坐大这一长期隐患。", "figures": ["刘病已"], "place": "张掖、西河、酒泉等边郡", "state": "西汉", "sources": ["《汉书·百官公卿表》", "《后汉书·郡国志》刘昭注", "居延汉简"], "tags": ["属国都尉", "降者安置", "因俗而治"]}, "related": ["cn--b127--i01", "cn--b60--i01"]},
  {"id": "cn--b68--f01", "track": "cn", "year": -68, "yearApprox": false, "dim": "figure", "weight": 3, "title": "霍光薨与宣帝亲政之渐", "summary": "大司马大将军光病免，谥宣成侯，封邑如故。", "detail": {"background": "地节二年（前68）春霍光病，三月薨；宣帝与皇太后亲临其丧，赐梓宫、便房、黄肠题凑，东园温明之器，葬礼之盛，汉世功臣无与为比。", "process": "光病笃，宣帝自临问之，为之涕泣；光上书「愿分国邑三千户，以封兄孙奉车都尉山为列侯，奉兄票骑将军去病祀」——去病死后四十九年，他那个同父异母、被他从平阳传舍带回长安的弟弟，最后一道奏疏要办的事仍是给兄长立后。霍光既葬，宣帝始亲郊庙、自总万机；以张安世为卫尉，典二宫卫率，徙霍禹为大司马而夺其印绶，收其禁兵，诸霍皆为卿相而失实；光诸婿诸驸马仍并领禁省，家属治第宅、僭拟乘舆。", "impact": "这是皇权自下而上回收权臣遗产的过程：不惊动其人而先换其兵，两年之后族灭霍氏，成为后世处置外戚权门的样本；它也说明领尚书事体制的存亡，全系于皇帝能否取得禁中与北军。", "figures": ["霍光", "刘病已", "张安世"], "place": "长安及平陵（今陕西咸阳西北）", "state": "西汉", "sources": ["《汉书·霍光金日磾传》", "《汉书·宣帝纪》"], "tags": ["霍光之死", "皇权回收", "黄肠题凑"]}, "related": ["cn--b80--p01", "cn--b64--p01"]},
  {"id": "cn--b66--c01", "track": "cn", "year": -66, "yearApprox": true, "dim": "culture", "weight": 3, "title": "桓宽推衍盐铁论成书", "summary": "宣帝时汝南桓宽推衍盐铁会议之议，为六十篇。", "detail": {"background": "始元六年的盐铁会议虽罢酒榷而盐铁如故，然当时公卿与贤良文学答问之辞未有定本，其议往往散在士人传述之间。", "process": "宣帝时，汝南人桓宽以曾从与会者闻其说，乃「推衍盐铁之议，增广条目，极其论难」，著为《盐铁论》凡六十篇，以文学、贤良与御史大夫、丞相史往复诘难为体，兼及力役、币制、边备、法制与礼义之本。", "impact": "这是中国最早以政策辩论为主体的政论文献，也是汉代经济思想唯一成系统的对话文本；其崇本抑末、与民休息之论经此书定型，成为此后两千年批评禁榷聚敛者的武器库。", "figures": ["桓宽", "桑弘羊"], "place": "汝南至长安一带", "state": "西汉", "sources": ["《盐铁论》", "《汉书·食货志》"], "tags": ["盐铁论", "经济思想", "政策辩论"]}, "related": ["cn--b81--c01", "cn--b119--e01"]},
  {"id": "cn--b65--i01", "track": "cn", "year": -65, "yearApprox": false, "dim": "institution", "weight": 2, "title": "置孝弟力田与三老劝率", "summary": "诏郡国务农桑，以乡官三老、力田课最。", "detail": {"background": "宣帝数诏郡国务在农桑，而郡国之吏多以狱讼、赋敛为课，劝率无人；武帝末以来流民未尽还，编户多困。", "process": "元康（前65—前62）之前，诏郡国置孝弟、力田，与乡三老、啬夫、游徼同为乡官，专掌劝课农桑、表率风俗；又于三辅及边郡置农官、都水、均输，数诏无出今年算赋、减天下口钱。", "impact": "把「劝农」写成有编制的职责，是中国基层治理史上少见的制度尝试：它使中央的农桑考课落到乡里，形成此后两千余年「三老、力田」的乡官谱系，也透露了帝国无法直接干预土地分配时的替代办法。", "figures": ["刘病已"], "place": "郡国乡里及三辅", "state": "西汉", "sources": ["《汉书·宣帝纪》", "《汉书·百官公卿表》", "尹湾汉简《集簿》"], "tags": ["三老力田", "乡官制度", "劝农"]}, "related": ["cn--b134--i01", "cn--b80--i01"]},
  {"id": "cn--b65--p01", "track": "cn", "year": -65, "yearApprox": true, "dim": "politics", "weight": 3, "title": "苏武复为右曹典属国，命朝朔望，号称祭酒", "summary": "宣帝以武故二千石预谋立己，赐爵关内侯；复为右曹典属国，命朝朔望，号祭酒。", "detail": {"background": "数年，昭帝崩，武以故二千石与计谋立宣帝，赐爵关内侯，食邑三百户。久之，卫将军张安世荐武明习故事，奉使不辱命，先帝以为遗言。", "process": "宣帝即时召武待诏宦者署，数进见，复为右曹典属国。以武著节老臣，命朝朔望，号称祭酒，甚优宠之。武所得赏赐，尽以施予昆弟故人，家不余财。皇后父平恩侯、帝舅平昌侯、乐昌侯、车骑将军韩增、丞相魏相、御史大夫丙吉皆敬重武。", "impact": "本传的收官不是封赏而是清贫：「武所得赏赐，尽以施予昆弟故人，家不余财。」◆ 系年：本传不书此事年号，只云「宣帝即时召武」「以武著节老臣」，属即位（前74）后累年之事；本条 year 为推系以就编年位次，yearApprox=true。◆ 旧版本条题作「苏武与霍光日磾并侍中曹」，summary 引「诏举故旧尝侍中曹者，独以义节称」——本次直查《汉书·卷五十四》全传未得此九字，属不可定位之引，题与引一并改从本传明文。", "figures": ["苏武", "宣帝刘询", "张安世", "霍光"], "place": "长安", "state": "西汉", "sources": ["《汉书·卷五十四·李广苏建传》"], "tags": ["苏武", "祭酒", "中兴叙事"]}, "related": ["cn--b51--a01", "cn--b80--p02"]},
  {"id": "cn--b64--p01", "track": "cn", "year": -64, "yearApprox": false, "dim": "politics", "weight": 4, "title": "霍氏满门以谋反族诛", "summary": "霍禹谋为乱，事觉，云、山自杀，显弃市。", "detail": {"background": "霍光死后，其子禹、孙云、山袭封，诸婿驸马皆掌宿卫；宣帝初政，渐夺其兵，转任诸刘为卿；霍显骄奢，此前曾使女医淳于衍进毒药杀许皇后，至此事亦渐露。", "process": "地节四年（前64）夏，霍禹与其兄弟子婿谋以午日劫丞相、御史，因欲废帝；事泄，禹被腰斩，霍显及诸昆弟、党与皆弃市，一家族灭，霍云、霍山自杀，皇后霍氏废处昭台宫。宣帝于是躬亲万机，以丙吉为丞相、魏相为御史大夫，机要始还台阁。", "impact": "霍氏之灭结束了武帝末以来大司马大将军专政的第一轮，也为外戚划定一条警戒线：可以贵宠，不可以典禁兵；宣帝以后许、史、王三家相继而起，这条教训终究没能拦住西汉的衰亡。", "figures": ["刘病已", "霍禹", "霍显", "丙吉", "魏相"], "place": "长安", "state": "西汉", "sources": ["《汉书·霍光金日磾传》", "《汉书·外戚传》", "《汉书·丙吉传》"], "tags": ["霍氏覆灭", "外戚警戒", "宣帝亲政"]}, "related": ["cn--b68--f01", "cn--b74--p02"]},
  {"id": "cn--b61--m01", "track": "cn", "year": -61, "yearApprox": false, "dim": "military", "weight": 4, "title": "赵充国屯田奏记平先零羌", "summary": "以七十余岁将兵，罢骑兵而留田，羌遂瓦解。", "detail": {"background": "神爵元年（前61）先零羌与诸羌解仇结盟，通使匈奴，欲遮隔玉门；汉遣御史大夫丙吉问可使者，赵充国时年七十余，自请驰至金城，图上方略。", "process": "赵充国至金城，先以兵威招降罕、幵等羌，禁军士不得攻击已降者；又奏罢骑兵万人的转输之费，留步卒万人因田于湟水、临羌以西，治乡亭、缮邮亭、积谷物，且耕且守，谓羌本可坐致。其议与公卿相难，宣帝数使使者问之，后卒用其策。", "impact": "先零羌不待大兵而自溃，斩首与降者各以万数，金城属国遂置；屯田奏记记省戍卒、罢转输之利，成为后世「以屯代兵」的经典，也是羌患长期化的开始。", "figures": ["赵充国", "刘病已"], "place": "金城、湟水一带（今甘肃兰州至青海湟中）", "state": "西汉", "sources": ["《汉书·赵充国传》", "《资治通鉴·汉纪》"], "tags": ["赵充国", "屯田", "先零羌"]}, "related": ["cn--b70--i01", "cn--b101--e01"]},
  {"id": "cn--b60--p01", "track": "cn", "year": -60, "yearApprox": false, "dim": "politics", "weight": 4, "title": "日逐王降汉，僮仆都尉由此罢", "summary": "匈奴日逐王畔单于将众来降，郑吉迎之，僮仆都尉由此罢。", "detail": {"background": "匈奴虚闾权渠单于立后国内不安，日逐王与单于有隙；《汉书·西域传》序：「匈奴西边日逐王置僮仆都尉，使领西域，常居焉耆、危须、尉黎间，赋税诸国，取富给焉。」役使城郭之国，汉使往来皆苦之。", "process": "神爵二年（前60）「日逐王畔单于，将众来降，护鄯善以西使者郑吉迎之。既至汉，封日逐王为归德侯，吉为安远侯」（《汉书·西域传》序）；《郑吉传》记其规模：「匈奴乖乱，日逐王先贤掸欲降汉，使人与吉相闻。吉发渠犁、龟兹诸国五万人迎日逐王，口万二千人、小王将十二人随吉至河曲」。汉「因使吉并护北道，故号曰都护。都护之起，自吉置矣。僮仆都尉由此罢，匈奴益弱，不得近西域」。北道诸国并归于汉。", "impact": "匈奴在西域的统治机构自此终结，西域第一次同时由一国都护统领；两年后匈奴内部五单于并立、呼韩邪南附，西域都护府的成立成为瓜分草原政治遗产的关键一着。", "figures": ["郑吉", "日逐王先贤掸"], "place": "乌垒、渠犁（今新疆轮台、库尔勒一带）", "state": "西汉", "sources": ["《汉书·西域传》序", "《汉书·傅常郑甘陈段传》", "《资治通鉴·汉纪》"], "tags": ["日逐王降", "僮仆都尉", "北道归汉"]}, "related": ["cn--b60--i01", "cn--b71--m01"]},
  {"id": "cn--b60--i01", "track": "cn", "year": -60, "yearApprox": false, "dim": "institution", "weight": 5, "title": "西域都护府初置", "summary": "号曰都护，治乌垒城，并护南北两道诸国。", "detail": {"background": "自张骞凿空、贰师伐宛之后，汉使遍往来城郭诸国；轮台、渠犁「皆有田卒数百人，置使者校尉领护」，车师屯田继之；至日逐王降，「僮仆都尉由此罢」，西域南北道皆向汉，非置官统督不能制。", "process": "神爵二年（前60）汉以郑吉并护北道，「故号曰都护。都护之起，自吉置矣」；都护「治乌垒城，去阳关二千七百三十八里，与渠犁田官相近，土地肥饶，于西域为中，故都护治焉」，督察乌孙、康居诸外国动静，「安辑」与「击」两法并行，诸国所受汉官印绶、屯田、客使与城郭之守皆属焉；西域「本三十六国，其后稍分至五十余」，皆在其监护之内。", "impact": "这是中原王朝第一次把西域纳入常设军政管辖，其办法是册封当地君长、驻校尉与田卒、控驿道而非编户征赋，是一种成本极低的间接统治；「都护」自此成为历朝控御边疆的通名。《西域传》赞归其源于河西格局：「以断匈奴右臂，隔绝南羌、月氏。单于失援，由是远遁，而幕南无王庭。」", "figures": ["郑吉", "刘病已"], "place": "乌垒城（今新疆轮台东）", "state": "西汉", "sources": ["《汉书·西域传》序", "《汉书·西域传》赞", "《汉书·傅常郑甘陈段传》"], "tags": ["西域都护", "乌垒城", "边疆治理"]}, "related": ["cn--b126--x01", "cn--b101--e01", "cn--b60--p01"]},
  {"id": "cn--b60--f01", "track": "cn", "year": -60, "yearApprox": false, "dim": "figure", "weight": 3, "title": "典属国苏武卒，赎胡妇之子通国", "summary": "上闵苏武子死，诏赎其胡妇之子通国以为郎；武年八十余，神爵二年病卒。", "detail": {"background": "武年老，子前坐事死，上闵之。「武在匈奴久，岂有子乎？」", "process": "武年老，子前坐事死，上闵之，问左右：「武在匈奴久，岂有子乎？」武因平恩侯自白：「前发匈奴时，胡妇适产一子通国，有声问来，愿因使者致金帛赎之。」上许焉。后通国随使者至，上以为郎。又以武弟子为右曹。武年八十余，神爵二年病卒。", "impact": "「前发匈奴时，胡妇适产一子通国，有声问来，愿因使者致金帛赎之。」——十九年之外，本传另留一笔：使臣在匈奴有妻有子，归汉后要靠朝廷出钱把儿子赎回来。◆ 九年后（甘露三年，前51）苏武以典属国列麒麟阁十一人之末，见 cn--b51--a01。 ◆ 系年：本传此处书年号「神爵二年」；其后公元换算为维基文库编者所加，非正文。本条 year 取该年号，为前60年。", "figures": ["苏武", "通国", "宣帝刘询", "平恩侯许广汉"], "place": "长安", "state": "西汉", "sources": ["《汉书·卷五十四·李广苏建传》"], "tags": ["苏武", "通国", "典属国"]}, "related": ["cn--b51--a01", "cn--b80--p02"], "checks": [{"by": "本站·维基文库比对（《汉书》卷五十四李广苏建传）", "at": "2026-11-07", "note": "◆ 本次回改：impact 旧作「十一年后（甘露三年，前51）苏武以典属国列麒麟阁十一人之末，见 cn--b51--a01」，检本条神爵二年为前60、cn--b51--a01 甘露三年为前51，相去九年（两事年号皆出《李广苏建传》，本传「武年八十余，神爵二年病卒」与「甘露三年，单于始入朝。上思股肱之美，乃图画其人于麒麟阁」），故改「十一年后」为「九年后」。"}]},
  {"id": "cn--b58--i01", "track": "cn", "year": -58, "yearApprox": false, "dim": "institution", "weight": 2, "title": "颍川太守黄霸以治行尤异，赐爵关内侯", "summary": "神爵四年夏四月，以郡守治行最异增秩、赐爵、黄金百斤；《传》谓治为天下第一。", "detail": {"background": "宣帝自霍光薨后始躬万机，以为太守吏民之本，「二千石有治理效，辄以玺书勉厉，增秩赐金，或爵至关内侯，公卿缺则选诸所表以次用之」，又尝称「与我共此者，其唯良二千石乎」。黄霸守颍川前后八年，力行教化而后诛罚。", "process": "前58年（神爵四年）。《汉书·宣帝纪》：「夏四月，颍川太守黄霸以治行尤异秩中二千石，赐爵关内侯，黄金百斤。及颍川吏民有行义者爵，人二级，力田一级，贞妇顺女帛。」◆《循吏传》载其本末：霸以「力行教化而后诛罚」，「以外宽内明得吏民心，户口岁增，治为天下第一」，又「前后八年，郡中愈治。是时凤皇神爵数集郡国，颍川尤多」。天子下诏称扬，数其效曰「宣布诏令，百姓乡化，孝子弟弟贞妇顺孙日以众多，田者让畔，道不拾遗，养视鳏寡，赡助贫穷，狱或八年亡重罪囚，吏民乡于教化，兴于行谊，可谓贤人君子矣」，「其赐爵关内侯，黄金百斤，秩中二千石」。后数月征为太子太傅，迁御史大夫；「五凤三年，代丙吉为丞相，封建成侯」，「为丞相五岁，甘露三年薨，谥曰定侯」。", "impact": "以郡守而赐关内侯之爵，是汉代以效验课吏这条原则的最高一次兑现，此后教化居课首遂成循吏政治的正面典型；然同一传又记其为相之后「风采不及丙、魏、于定国，功名损于治郡」，张敞且就「神雀」之误上奏劾之——赏一人而两说并存，正是名实之辨的老题。本条旧系前29年，与霸卒之年（甘露三年，前51）相抵，本次一并回改。", "figures": ["黄霸", "刘奭"], "place": "颍川（今河南禹州一带）", "state": "西汉", "sources": ["《汉书·循吏传》", "《汉书·宣帝纪》"], "tags": ["循吏", "教化考课", "条课"]}, "related": ["cn--b65--i01", "cn--b64--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪、卷八十九循吏传）", "at": "2026-11-07", "note": "本次为系年回改：本站旧条作 cn--b29--i01、系前29年，题为「黄霸式化尤异为天下最」，并称「前29年前后…征为丞相」。检《宣帝纪》神爵四年夏四月明书「颍川太守黄霸以治行尤异秩中二千石，赐爵关内侯，黄金百斤」，《循吏传》亦以「五凤三年，代丙吉为丞相」「为丞相五岁，甘露三年薨」系其后，则前29年霸已卒二十七年，旧系年与旧「征为丞相」之叙俱不可从，故改id为 cn--b58--i01、系前58年，条目入神爵四年。引用之文两书并存：诏称扬之辞出《传》，「治行尤异」之目与「黄金百斤」之数《纪》《传》同有，本条从《纪》取日月。《传》引诏「颖川太守霸」本页作「颖」，同卷他处作「颍」，属本页字形，照录不改；「弟弟」本页如此（通「悌」），本条不转。「狱或八年亡重罪囚」之「或」为「有」义，本条照录不训。卷八十九页首标 Textquality 25%。"}]},
  {"id": "cn--b55--i01", "track": "cn", "year": -55, "yearApprox": true, "dim": "institution", "weight": 4, "title": "耿寿昌奏立常平仓", "summary": "边郡谷贱则增价而籴，名曰常平。", "detail": {"background": "宣帝以京师用度不足，漕关东四百万石乃给；大司农中丞耿寿昌治度支，请先籴三辅、弘农、河东、上党、太原之谷以实京师，省关东漕事过半。", "process": "五凤中（约前55年）寿昌奏：边郡岁丰则谷价甚贱，农夫反伤，请谷贱之时增其价而籴以利民，贵则减价而粜，名曰常平仓；又请以水运、漕渠相续，省关东漕事之半。", "impact": "常平仓制度以官方籴粜来平抑谷价、保护小农与军粮供应，自是历代王朝备荒与稳价的标配，一直沿用到清末；它同时也是古代中国「以财政手段调节市场」最早的成熟设计，其得失之争贯穿此后两千年。", "figures": ["耿寿昌", "刘病已"], "place": "三辅及边郡诸仓", "state": "西汉", "sources": ["《汉书·食货志》", "《汉书·沟洫志》"], "tags": ["常平仓", "平抑谷价", "耿寿昌"]}, "related": ["cn--b110--e01", "cn--b65--i01"]},
  {"id": "cn--b55--m01", "track": "cn", "year": -55, "yearApprox": false, "dim": "military", "weight": 3, "title": "匈奴五单于并立自相攻击", "summary": "神爵以来匈奴内乱，五六单于更相诛灭。", "detail": {"background": "虚闾权渠单于死后，匈奴贵人与诸部相继自立，单于之号日多；日逐王先贤掸东降之后，西部远有郅支、近有呼韩邪，各据一方。", "process": "约前55年，匈奴诸部并自立为单于，凡五六号，更相攻击，国中大乱，饥饿相食，畜产耗减；诸王、将帅多将其众降汉。汉公卿或议乘其乱而取之，或以为当存其国、示以恩信。", "impact": "匈奴的统一体在此十余年间彻底解体，草原的分裂与饥荒成为汉不战而胜的原因，也把南匈奴的内附与北匈奴的西迁一并推到前台；汉廷由此开始以册封、粮赈与质子操纵草原政治。", "figures": ["呼韩邪单于", "郅支单于"], "place": "蒙古高原", "state": "西汉", "sources": ["《汉书·匈奴传》", "《资治通鉴·汉纪》", "《汉书·宣帝纪》"], "tags": ["五单于并立", "匈奴内乱", "草原解体"]}, "related": ["cn--b60--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪、卷九十四下匈奴传下）", "at": "2026-11-07", "note": "「诸王并自立，分为五单于，更相攻击，死者以万数，畜产大耗什八九，人民饥饿，相燔烧以求食」为《宣帝纪》五凤三年诏之自述文，是本条所据；《匈奴传下》叙五单于名号更详，本页页首标 Textquality 25%，本条只取与《纪》相合之语，不取其名号次第。「汉公卿或议乘其乱而取之」一节《宣帝纪》无文，仍据《匈奴传》与《通鉴》，本条不复标其年。是岁又书「匈奴单于称臣，遣弟谷蠡王入侍」，《纪》不名其单于，故本条不订。"}]},
  {"id": "cn--b55--e02", "track": "cn", "year": -55, "yearApprox": false, "dim": "economy", "weight": 3, "title": "减天下口钱", "summary": "五凤三年因祠后土下诏，举甘露降、神爵集之瑞，减天下口钱而赦殊死以下。", "detail": {"background": "匈奴五单于并立、更相攻击，呼韩邪称臣、使弟奉珍朝贺，北边亡寇（见 cn--b55--m01）；宣帝于是岁东上河东祠后土，诏以祥瑞与边事相因告其民。", "process": "前55年（五凤三年）。《汉书·宣帝纪》：「三月，行幸河东，祠后土。诏曰：『往者匈奴数为边寇，百姓被其害。……右贤王屠耆堂代立。骨肉大臣立虚闾权渠单于子为呼韩邪单于，击杀屠耆堂。诸王并自立，分为五单于，更相攻击，死者以万数，畜产大耗什八九，人民饥饿，相燔烧以求食，因大乖乱。……单于称臣，使弟奉珍朝贺正月，北边晏然，靡有兵革之事。……甘露降，神爵集。……减天下口钱。赦殊死以下。赐民爵一级，女子百户牛酒，大酺五日。』」◆ 一诏之中自「往者匈奴数为边寇」至「大酺五日」首尾相贯：以匈奴乖乱为言，而以减口钱为报；本站不割为二事，亦不增其次序。", "impact": "减口钱与甘露二年之减民算三十（见 cn--b52--e01）同为中兴晚岁以瑞应、边宁为名的宽赋之举；减在一时，而边用钱谷之费自在，故北边之安终须屯兵与转输为之，此事至甘露三年留卫单于之诏而益明（见 cn--b51--p02）。", "figures": ["刘病已"], "place": "河东（今山西运城一带）、长安", "state": "西汉", "sources": ["《汉书·宣帝纪》"], "tags": ["口钱", "宽赋", "祠后土"]}, "related": ["cn--b55--m01", "cn--b52--e01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪）", "at": "2026-11-07", "note": "诏文逐字照录《汉书》卷八本页，省略号处为本诏别段之文，本条不补；「减天下口钱」一句《纪》在甘露、黄龙两岁无重出，检本卷唯五凤三年诏有此文，故系年定在此岁，本站旧目之混数诏于前53年者已改（见 cn--b52--e01）。口钱之额与始出口钱之年，《宣帝纪》《食货志》两卷皆无明文，本条不复述旧说，亦不采他说数字。「甘露降，神爵集」为此诏自言瑞应，与后三年改元甘露之关系《纪》不申明，本条不推。◆ 本次回改：impact 旧作「明年后之减民算三十」，检 cn--b52--e01 在甘露二年（前52），自本条前55相去三年，故径书「甘露二年」。"}]},
  {"id": "cn--b53--i01", "track": "cn", "year": -53, "yearApprox": false, "dim": "institution", "weight": 3, "title": "两单于各遣子入侍，呼韩邪引众南近塞", "summary": "呼韩邪从左伊秩訾之计，遣子入侍而引众南近塞；同年郅支亦遣子入侍。", "detail": {"background": "前55年匈奴诸王并自立、分为五单于，更相攻击（见 cn--b55--m01），呼韩邪为郅支所败；《匈奴传下》记其廷议，诸大臣以「臣事于汉，卑辱先单于，为诸国所笑」为不可，左伊秩訾王以为「今事汉则安存，不事则危亡」。", "process": "前53年（甘露元年）。《汉书·匈奴传下》：「呼韩邪从其计，引众南近塞，遣子右贤王铢娄渠堂入侍。郅支单于亦遣子右大将驹于利受入侍。是岁，甘露元年也。」◆ 《汉书·宣帝纪》其岁但书一句：「匈奴呼韩邪单于遣子右贤王铢娄渠堂入侍」，不书郅支之子；其冬又书「冬，匈奴单于遣弟左贤王来朝贺」，本页此条不系何单于，本条不据以定来朝贺者之为谁。", "impact": "单于以国嗣质汉，自是岁始见于本书；南北两单于各为之，是草原分裂之后并力求援于汉。汉自此以质子、粟米与屯兵介入匈奴立嗣之争：明年呼韩邪款五原塞愿朝（见 cn--b52--p01），三年遂亲朝于甘泉宫（见 cn--b51--p02）。传末论宣代之效曰「单于稽首臣服，遣子入侍，二世称藩，宾于汉庭」，其所起即在此岁。", "figures": ["呼韩邪单于", "左伊秩訾王", "郅支单于", "刘病已"], "place": "汉北边塞下（五原、朔方一带）", "state": "西汉", "sources": ["《汉书·宣帝纪》", "《汉书·匈奴传下》"], "tags": ["质子", "入侍", "呼韩邪内附"]}, "related": ["cn--b55--m01", "cn--b52--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪、卷九十四下匈奴传下）", "at": "2026-11-07", "note": "「呼韩邪从其计」一段引文逐字照录卷九十四下本页；本页页首标 Textquality 25%，故引文不与它本互改，其中「引众南近塞」之「众」本页作「眾」、「驹于利受」本页作「駒于利受」，属繁简转写而非异文。系年从本页「是岁，甘露元年也」；《宣帝纪》甘露元年只书呼韩邪遣子一事，不载郅支之子，两书详略并存不合并。「冬，匈奴单于遣弟左贤王来朝贺」一句《纪》不名其单于，前54年《纪》又书「匈奴单于称臣，遣弟谷蠡王入侍」，两条之「单于」为谁，诸说分歧，本条照录其文而不论其所朝为谁。"}]},
  {"id": "cn--b52--e01", "track": "cn", "year": -52, "yearApprox": false, "dim": "economy", "weight": 3, "title": "减民算三十", "summary": "诏因凤皇、甘露、黄龙诸瑞赦天下，减民算三十，赐民爵一级。", "detail": {"background": "宣帝晚岁数因祥瑞下诏赦天下而减民赋，是岁之诏所谓「乃者凤皇甘露降集，黄龙登兴」者也。", "process": "前52年（甘露二年）。《汉书·宣帝纪》：「诏曰：『乃者凤皇甘露降集，黄龙登兴，醴泉滂流，枯槁荣茂，神光并见，咸受祯祥。其赦天下。减民算三十。赐诸侯王、丞相、将军、列侯、中二千石金钱各有差。赐民爵一级，女子百户牛酒，鳏寡孤独高年帛。』」◆ 减算之外，本卷所书减赋之诏尚有二事：五凤三年（前55）诏「减天下口钱」（见 cn--b55--e02），地节三年（前57）诏「且勿算事」；三诏各因其年，本条不合并。", "impact": "一算所减三十钱，为一时之惠而非经制之改：诏下而赋额仍循其旧，唯因祥瑞、灾异而数有减免，遂成中兴之世财政行事的样式——以赦与减并施、以瑞为其名。本条只据诏书所列减目，不计所及民数与其实惠。", "figures": ["刘病已"], "place": "长安及郡国", "state": "西汉", "sources": ["《汉书·宣帝纪》"], "tags": ["减赋", "算赋", "祥瑞之诏"]}, "related": ["cn--b55--e02", "cn--b65--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪）", "at": "2026-11-07", "note": "本条旧目题「减天下口钱与算赋之议」、id 作 cn--b53--e01、系于前53年；检《宣帝纪》甘露元年无减赋之诏，「减民算三十」在甘露二年诏、「减天下口钱」在五凤三年诏，两诏不相合为一事，故本条改题从诏语、改系前52年，口钱一事别立 cn--b55--e02，本站他条引用旧 id 处已随本次同步。旧 background 所引「民年生子三岁出口钱」「算赋人百二十钱」诸数，检《汉书》卷二十四食货志无其文，本站无从定其所出，本次删去不复述；汉制口钱、算赋之额另待有征之文，本条不论。《宣帝纪》卷八本页无 Textquality 标记，引文逐字照录。"}]},
  {"id": "cn--b52--p01", "track": "cn", "year": -52, "yearApprox": false, "dim": "politics", "weight": 3, "title": "呼韩邪款五原塞愿朝，有司议礼，诏以客礼待之", "summary": "单于愿奉国珍朝明年正月；公卿请位次诸侯王下，诏改以客礼待之、位在诸侯王上。", "detail": {"background": "前53年呼韩邪遣子入侍、引众南近塞（见 cn--b53--i01）；自前133年马邑为绝和亲而设伏（见 cn--b133--m01），汉与匈奴相攻八十余年，单于亲朝无其事。", "process": "前52年（甘露二年）。《汉书·宣帝纪》：「匈奴呼韩邪单于款五原塞，愿奉国珍朝三年正月。诏有司议。」公卿议曰：「……匈奴单于乡风慕义，举国同心，奉珍朝贺，自古未之有也。单于非正朔所加，王者所客也，礼仪宜如诸侯王，称臣昧死再拜，位次诸侯王下。」诏曰：「盖闻五帝三王，礼所不施，不及以政。今匈奴单于称北藩臣，朝正月，朕之不逮，德不能弘覆。其以客礼待之，位在诸侯王上。」◆ 《匈奴传下》叙其迎仪之制：「汉遣车骑都尉韩昌迎，发过所七郡郡二千骑，为陈道上。」本页紧承「愿朝三年正月」之下，不别著月。", "impact": "「位在诸侯王上」一语为汉匈关系定一新格：单于称臣而班在诸侯王上，汉以客礼待之，实以名分换北边之安。议礼之际公卿犹欲抑之在下，诏旨反之，此中出入本条只照录两说，不判其得失。明年单于果以正月来朝（见 cn--b51--p02），其后前49年「礼赐如初」、前33年赐待诏掖庭王墙为阏氏，皆循此格而行。", "figures": ["呼韩邪单于", "刘病已", "韩昌"], "place": "五原塞、长安（今内蒙古包头以西、陕西西安西北）", "state": "西汉", "sources": ["《汉书·宣帝纪》", "《汉书·匈奴传下》"], "tags": ["议礼", "客礼", "位在诸侯王上"]}, "related": ["cn--b53--i01", "cn--b51--p02"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪、卷九十四下匈奴传下）", "at": "2026-11-07", "note": "议礼之诏与公卿之议逐字照录卷八本页（无 Textquality 标记之页）；「愿奉国珍朝三年正月」《纪》有「奉国珍」三字，《传》作「愿朝三年正月」，两书详略并存不合并。所谓「三年正月」谓甘露三年正月，故本条系年在甘露二年、朝事别立于前51年条。「乡风慕义」之「乡」本页作「鄉」，今从读本转写；「发过所七郡郡二千骑」《传》本页作「發過所七郡郡二千騎」，叠书两「郡」字为本页旧形，未改从说者「郡各」之文。卷九十四下页首标 Textquality 25%，迎陈一节只照录本页，其年月不订。"}]},
  {"id": "cn--b51--a01", "track": "cn", "year": -51, "yearApprox": false, "dim": "art", "weight": 2, "title": "麒麟阁十一功臣图形", "summary": "甘露三年单于始入朝，上图霍光等十一人于麒麟阁，苏武以典属国与列末位。", "detail": {"background": "甘露三年，单于始入朝。上思股肱之美，乃图画其人于麒麟阁，法其形貌，署其官爵、姓名。", "process": "唯霍光不名，曰大司马大将军博陆侯姓霍氏，次曰卫将军富平侯张安世，次曰车骑将军龙额侯韩增，次曰后将军营平侯赵充国，次曰丞相高平侯魏相，次曰丞相博阳侯丙吉，次曰御史大夫建平侯杜延年，次曰宗正阳城侯刘德，次曰少府梁丘贺，次曰太子太傅萧望之，次曰典属国苏武。皆有功德，知名当世，是以表而扬之，明著中兴辅佐，列于方叔、召虎、仲山甫焉。凡十一人，皆有传。自丞相黄霸、廷尉于定国、大司农朱邑、京兆尹张敞、右扶风尹翁归及儒者夏侯胜等，皆以善终，著名宣帝之世，然不得列于名臣之图，以此知其选矣。", "impact": "十一人次序为霍光、张安世、韩增、赵充国、魏相、丙吉、杜延年、刘德、梁丘贺、萧望之、苏武——苏武居末，唯霍光不名，其余皆书名。本传另记落选名单：「自丞相黄霸、廷尉于定国、大司农朱邑、京兆尹张敞、右扶风尹翁归及儒者夏侯胜等，皆以善终，著名宣帝之世，然不得列于名臣之图，以此知其选矣。」——榜单是宣传，落选才是历史。传末「赞曰」一段在本传篇终，与李广同卷，故两层所指不可混：「李将军恂恂如鄙人，口不能出辞，及死之日，天下知与不知皆为流涕」与谚「桃李不言，下自成蹊」皆指李广，后世常把此谚系于苏武，非是。「然三代之将，道家所忌，自广至陵，遂亡其宗，哀哉！」是班固替李广至李陵三代下的结语。给苏武的判语是引孔子两语：「志士仁人，有杀身以成仁，无求生以害仁」，「使于四方，不辱君命」，苏武有之矣。 ◆ 「单于始入朝」之单于为呼韩邪单于，事见《汉书·匈奴传》；本条只取本传之文，不并它书之辞。 ◆ 系年：本传此处书年号「甘露三年」；其后公元换算为维基文库编者所加，非正文。本条 year 取该年号，为前51年。", "figures": ["宣帝刘询", "霍光", "苏武", "赵充国", "呼韩邪单于"], "place": "长安未央宫麒麟阁", "state": "西汉", "sources": ["《汉书·卷五十四·李广苏建传》"], "tags": ["麒麟阁", "功臣图像", "中兴叙事"]}, "related": ["cn--b81--x01", "cn--b65--p01"]},
  {"id": "cn--b51--c01", "track": "cn", "year": -51, "yearApprox": false, "dim": "culture", "weight": 4, "title": "石渠阁讲论五经异同", "summary": "诏诸儒讲五经同异，天子亲称制临决。", "detail": {"background": "武帝立五经博士后，今文各家以「师法」「家法」相非，同经异说，章句滋多；宣帝闻《穀梁春秋》与《公羊》义理有异，欲正其得失。", "process": "甘露三年（前51）冬，诏诸儒于未央殿中石渠阁讲论《诗》《书》《礼》《乐》《春秋》《易》诸经异同，太子太傅萧望之等平奏其议，「天子亲称制临决焉」；议定后增立《梁丘易》、大小《夏侯尚书》、《穀梁春秋》博士。", "impact": "经学论议自此以皇帝裁决收束，家法之争由师门之异变成朝廷礼制的一部分；穀梁、欧阳等家既得立，学官渐多、章句益繁，也为成哀以后古文经学兴起与今古文之争埋下题目。", "figures": ["刘病已", "萧望之", "梁丘贺", "韦贤"], "place": "长安未央宫石渠阁", "state": "西汉", "sources": ["《汉书·宣帝纪》", "《汉书·艺文志》", "《汉书·儒林传》"], "tags": ["石渠阁", "五经异同", "家法"]}, "related": ["cn--b136--i01", "cn--b130--c01"]},
  {"id": "cn--b51--p02", "track": "cn", "year": -51, "yearApprox": false, "dim": "politics", "weight": 4, "title": "呼韩邪单于首朝甘泉宫，赞谒称藩臣而不名", "summary": "单于正月朝天子于甘泉宫，汉宠以殊礼，位在诸侯王上，赞谒称藩臣而不名；上登渭桥，咸称万岁。", "detail": {"background": "前53年遣子入侍、前52年款塞议礼（见 cn--b53--i01、cn--b52--p01）之后，单于果以甘露三年正月来朝；前一年公卿议其礼，已言「奉珍朝贺，自古未之有也」。", "process": "前51年（甘露三年）。《汉书·宣帝纪》：「匈奴呼韩邪单于稽侯蛳来朝，赞谒称藩臣而不名。赐以玺绶、冠带、衣裳、安车、驷马、黄金、锦绣、缯絮。使有司道单于先行就邸长安，宿长平。上自甘泉宿池阳宫。上登长平阪，诏单于毋谒。其左右当户之群皆列观，蛮夷君长王侯迎者数万人，夹道陈。上登渭桥，咸称万岁。单于就邸。置酒建章宫，飨赐单于，观以珍宝。二月，单于罢归。」◆ 《匈奴传下》：「单于正月朝天子于甘泉宫，汉宠以殊礼，位在诸侯王上，赞谒称臣而不名」，载赐物作黄金二十斤、钱二十万、锦绣绮縠杂帛八千匹、絮六千斤之属；又书单于「自请愿留居光禄塞下，有急保汉受降城」，汉「遣长乐卫尉高昌侯董忠、车骑都尉韩昌将骑万六千，又发边郡士马以千数，送单于出朔方鸡鹿塞。诏忠等留卫单于，助诛不服，又转边谷米糒，前后三万四千斛，给赡其食」。", "impact": "亲朝之始：前133年马邑为绝和亲而设伏（见 cn--b133--m01），八十余年后单于反自称藩臣于汉廷。汉所得者，《传》末赞所谓「边城晏闭，牛马布野，三世无犬吠之警」；所出者，留卫之骑、转输之谷与光禄塞下之屯，自此汉为南单于之存立负责，郅支遂远遁西徙（见 cn--b47--x01）。◆ 同年汉廷又图形功臣十一人于麒麟阁（见 cn--b51--a01）、诏诸儒讲五经异同（见 cn--b51--c01），《传》赞并归之于「至孝宣之世，承武帝奋击之威，直匈奴百年之运，因其坏乱几亡之阨，权时施宜，覆以威德」。", "figures": ["呼韩邪单于", "刘病已", "韩昌", "董忠"], "place": "甘泉宫、长安渭桥（今陕西淳化西北、西安西北）", "state": "西汉", "sources": ["《汉书·宣帝纪》", "《汉书·匈奴传下》"], "tags": ["首朝", "称藩臣", "客礼既成"]}, "related": ["cn--b52--p01", "cn--b49--p01", "cn--b51--c01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪、卷九十四下匈奴传下）", "at": "2026-11-07", "note": "首朝之年明据《宣帝纪》甘露三年。本站旧有 cn--b49--p01 一条题「呼韩邪单于入朝甘泉」、系于黄龙元年，并称此为「第一次以臣属身份入朝」；检黄龙元年《纪》但书「匈奴呼韩邪单于来朝，礼赐如初」，为复朝而非首朝，「礼赐如初」四字亦自言其与首朝相同，故本条另立，旧条已随本次回改。四处异文并存不合并：①《纪》作「赞谒称藩臣而不名」，《传》作「赞谒称臣而不名」；②所赐《纪》但举名目，《传》列斤两匹数；③送骑《纪》作「将万六千骑」，《传》作「将骑万六千，又发边郡士马以千数」；④所保之地《纪》作「单于居幕南，保光禄城」，《传》作「愿留居光禄塞下，有急保汉受降城」。单于之名《纪》作「稽侯蛳」，本页字形如此，未取别本互校；送将《纪》书高昌侯忠、车骑都尉昌、骑都尉虎三人，《传》但言董忠、韩昌，本条两存其目。卷九十四下页首标 Textquality 25%，其赐物之目只照录本页。鸡鹿塞、光禄塞、受降城之地望诸家分歧，本条不订；长平阪在池阳宫侧，亦只从本页之序。"}]},
  {"id": "cn--b49--p01", "track": "cn", "year": -49, "yearApprox": false, "dim": "politics", "weight": 2, "title": "呼韩邪单于复入朝，礼赐如初", "summary": "单于再以正月来朝，汉赐衣帛絮较首朝有加，礼数一如前岁；以已有屯兵，不复发车骑送之。", "detail": {"background": "甘露三年呼韩邪单于亲朝甘泉宫、赞谒称藩臣而不名（见 cn--b51--p02）；其明年两单于俱遣使朝献，汉待呼韩邪使有加，于是黄龙元年复有亲朝之行。", "process": "前49年（黄龙元年）。《汉书·宣帝纪》：「春正月，行幸甘泉，郊泰畤。匈奴呼韩邪单于来朝，礼赐如初。二月，单于归国。」◆ 《匈奴传下》记其所加与所省：「明年，呼韩邪单于复入朝，礼赐如初，加衣百一十袭，锦帛九千匹，絮八千斤。以有屯兵，故不复发骑为送。」本条系年从《纪》；《传》自甘露三年叙下两「明年」，推之适与《纪》合，故其「复入朝」即黄龙元年事。", "impact": "首朝之后复朝，仪物有加而仪卫反简：不发骑送，因汉已留兵卫单于——单于之安其庭，至此全仰汉之谷与兵。「礼赐如初」所维持者，为前52年议定「位在诸侯王上」之客格（见 cn--b52--p01），非敌国对等之旧约；本条只书复朝一节，其首朝之仪不重出。", "figures": ["呼韩邪单于", "刘病已"], "place": "长安（今陕西西安西北）", "state": "西汉", "sources": ["《汉书·宣帝纪》", "《汉书·匈奴传下》", "《资治通鉴·汉纪》"], "tags": ["复朝", "礼赐如初", "汉匈关系"]}, "related": ["cn--b51--p02", "cn--b52--p01", "cn--b55--m01", "cn--b60--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷八宣帝纪、卷九十四下匈奴传下）", "at": "2026-11-07", "note": "本条旧题「呼韩邪单于入朝甘泉」、weight 4，其 background、process 以甘露三年首朝之仪（朝于甘泉宫、位在诸侯王上、赐印绶衣被）与黄龙元年复朝之文合为一条，且 impact 断为「匈奴最高首领第一次以臣属身份入朝」，与《宣帝纪》甘露三年「匈奴呼韩邪单于稽侯蛳来朝，赞谒称藩臣而不名」及黄龙元年「礼赐如初」之文不合，故本次改题、降 weight 为 2、首朝别立 cn--b51--p02。旧 background「仰见汉家仪卫而拜」一句，检卷八本页与卷九十四下本页皆无其文，本站无从定其所出，本次删去不复述；「汉赐黄金、衣被、锦帛、车马」之数本条亦不重出，其详在首朝条。卷九十四下页首标 Textquality 25%，「加衣百一十袭」诸数只照录本页；《通鉴》系此事于黄龙元年，与本条同，惟「明年」推校之据在《传》，非《通鉴》。"}]},
  {"id": "cn--b48--i01", "track": "cn", "year": -48, "yearApprox": false, "dim": "institution", "weight": 4, "title": "元帝初政罢奢靡之费", "summary": "省乐府员、罢角抵诸戏，假苑囿田地与贫民。", "detail": {"background": "武帝末至昭宣，宫廷苑囿、乐府、角抵诸费甚巨，斗鸡走马、希微珍巧之物并积于黄门；元帝以儒素即位，欲以节俭收民心。", "process": "初元元年（前48）诏省乐府员之半，罢角抵与希微珍玩，出后宫未尝见者，省乘舆狗马；又诏假水衡、少府苑囿田地与贫民，减诸侯王朝献之费。", "impact": "省费宽民自此成为元、成两朝的常调，与宣帝中兴的财政作风相续；但外戚与近习的用度并未因此收束，宦寺用事之局反而在数年后打开。", "figures": ["刘奭", "贡禹"], "place": "长安", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·贡禹传》"], "tags": ["省费", "乐府", "假民苑囿"]}, "related": ["cn--b48--e01", "cn--b80--i01", "cn--b64--p01"]},
  {"id": "cn--b48--e01", "track": "cn", "year": -48, "yearApprox": false, "dim": "economy", "weight": 3, "title": "贡禹请罢采珠冶铸之议", "summary": "以民废于末作，请一切禁巧工而返之田。", "detail": {"background": "贡禹以贤良征为谏大夫，上疏历言民坐铸钱、采珠玉、治园冶而犯法者众，富人大贾被服文绣而农夫不足。", "process": "禹请以工巧无用之作为禁，罢尚方珍巧之物，禁采珠玉、治锦绣，壹力农桑，并请禁郡国私铸、专以五铢；章下公卿，议者以为不可卒行，元帝不能尽用。", "impact": "这是西汉后期以儒术为据的重农抑末纲领最完整的一次陈述，虽未成立法，却为此后的禁奢诏与限田议定下议题；盐铁之利则因财政不能绝源而长存。", "figures": ["贡禹", "刘奭"], "place": "长安", "state": "西汉", "sources": ["《汉书·贡禹传》", "《汉书·食货志》"], "tags": ["重农抑末", "禁奢", "贡禹"]}, "related": ["cn--b48--i01", "cn--b81--c01", "cn--b52--e01"]},
  {"id": "cn--b47--p01", "track": "cn", "year": -47, "yearApprox": false, "dim": "politics", "weight": 4, "title": "弘恭石显以中书用事", "summary": "萧望之下狱自杀，周堪免官，宦者典枢机自此始。", "detail": {"background": "元帝多疾、不亲万机，中书令弘恭、仆射石显久典枢机；帝重儒臣萧望之、周堪，欲以为辅，而忌外戚许、史。", "process": "初元二年（前47）望之、堪劝帝罢恭、显，上书言中书为政本、宜以儒士居之；恭、显遂与许史相表里，劾望之「怀执意见、要功罔上」，请下廷尉。帝素不知廷尉即狱，望之仰药自杀，堪免官。", "impact": "儒臣在禁中近习面前第一次公开的失败：自是公卿以下复畏恭、显，石显与五鹿充宗并用，士人清议与宦寺之争自此贯穿两汉，也促成后世以士人取代中书之制。", "figures": ["刘奭", "萧望之", "弘恭", "石显"], "place": "长安", "state": "西汉", "sources": ["《汉书·萧望之传》", "《汉书·佞幸传》", "《资治通鉴·汉纪》"], "tags": ["中书宦官", "萧望之死", "士人与近习"]}, "related": ["cn--b51--c01", "cn--b24--p02", "cn--b45--p01"]},
  {"id": "cn--b47--x01", "track": "cn", "year": -47, "yearApprox": false, "dim": "explore", "weight": 2, "title": "郅支单于西徙坚昆", "summary": "杀汉使江宰等，北走坚昆，与乌孙康居相攻。", "detail": {"background": "匈奴内乱既久，呼韩邪南附称臣，郅支骨都侯单于自立于北庭，遣子入侍于汉，又杀汉使者江宰等四人以绝和。", "process": "前47年前后，郅支引兵北走坚昆（今叶尼塞河上游一带），北击乌揭，西取大宛之地，与康居相结，数求汉归其侍子而汉不能制。", "impact": "郅支西迁把汉匈冲突从中部草原移到中亚七河一带，也把一个匈奴单于送到康居、大宛之间；丝路北道因此生出新问题，为陈汤后来矫制发兵提供了理由。", "figures": ["郅支单于", "江宰"], "place": "坚昆、康居（今叶尼塞河上游至哈萨克七河地区）", "state": "西汉", "sources": ["《汉书·匈奴传》", "《汉书·陈汤传》"], "tags": ["郅支", "坚昆", "中亚交通"]}, "related": []},
  {"id": "cn--b46--a01", "track": "cn", "year": -46, "yearApprox": false, "dim": "art", "weight": 3, "title": "海昏侯墓出土金器简牍", "summary": "南昌得列侯之制，黄金饼蹄与竹简书籍并出。", "detail": {"background": "昌邑王刘贺以行淫废归故国，数年后徙封豫章海昏侯，就国而卒；其墓在鄱阳湖西岸、赣江之滨。", "process": "2011至2015年考古发掘南昌海昏侯墓（大型带墓道、藏椁、便房之制），得金饼数百、马蹄金与麟趾金数十、五铢钱二十余万枚，又出竹简《论语》、《诗》类书、医书与日报、漆器、青铜灯、衣镜及真车马陪葬坑。", "impact": "这是现存汉代列侯墓中保存最完整、随葬最丰的一座，实证了列侯葬制、酎金与黄金衡制的规模；简牍与衣镜画像则为经学扩散与早期人物画提供了新材料。", "figures": ["刘贺"], "place": "豫章海昏（今江西南昌新建区）", "state": "西汉", "sources": ["海昏侯墓考古报告", "《汉书·武五子传》"], "tags": ["海昏侯墓", "金饼", "列侯葬制"]}, "related": ["cn--b74--p01", "cn--b51--a01"]},
  {"id": "cn--b46--f01", "track": "cn", "year": -46, "yearApprox": false, "dim": "figure", "weight": 1, "title": "海昏侯刘贺卒于国", "summary": "就国豫章，削户三千，卒谥海昏侯。", "detail": {"background": "刘贺废归昌邑，朝廷以其行淫乱削户三千；神爵三年（前59）徙封豫章为海昏侯，邑千户，不得朝聘，与故国吏民隔离。", "process": "前46年前后贺卒于侯国，有司奏其罪当绝国，元帝以其先尝即位、旋复悔过，为定谥曰海昏侯；子代立，食邑如故，其国至东汉尚存。", "impact": "一位在位二十七日的皇帝变成江南侯国的初封者，这一处置既见宣帝之后的政治宽简，也把昌邑一系的故吏彻底边缘化；海昏侯国成为汉制在豫章的支点之一。", "figures": ["刘贺"], "place": "海昏（今江西永修、新建一带）", "state": "西汉", "sources": ["《汉书·武五子传》", "《资治通鉴·汉纪》"], "tags": ["刘贺", "海昏侯", "废王结局"]}, "related": ["cn--b74--p01", "cn--b46--a01"]},
  {"id": "cn--b46--i01", "track": "cn", "year": -46, "yearApprox": false, "dim": "institution", "weight": 3, "title": "罢珠崖郡：从「议大发军」到「专用恤关东」", "summary": "珠崖山南县反，捐之议不当击，帝使王商诘之，丞相于定国是捐之，诏遂罢其郡。", "detail": {"background": "元帝初即位，关东连年灾害，民困于役；珠崖自武帝置郡以来数反，发兵击之连年不定。初元三年春又书「令诸侯相位在郡守下」，同年六月之诏已先「罢甘泉、建章宫卫，令就农。百官各省费」，朝廷之议本已转向省费恤民。", "process": "前46年（初元三年）。《汉书·元帝纪》：「珠崖郡山南县反，博谋群臣。待诏贾捐之以为宜弃珠崖，救民饥馑。乃罢珠崖。」◆《贾捐之传》叙本末最详：「元帝初元元年，珠崖又反，发兵击之。诸县更叛，连年不定。上与有司议大发军，捐之建议，以为不当击。」传叙置郡之本末：武帝征南越，元封元年立儋耳、珠崖郡，「合十六县，户二万三千余」；又书其反叛之频，「自初为郡至昭帝始元元年，二十余年间，凡六反叛。至其五年，罢儋耳郡并属珠崖。至宣帝神爵三年，珠崖三县复反。反后七年，甘露元年，九县反，辄发兵击定之。」至「上与有司议大发军，捐之建议，以为不当击」，帝乃「使侍中驸马都尉乐昌侯王商诘问捐之曰：『珠崖内属为郡久矣，今背畔逆节，而云不当击，长蛮夷之乱，亏先帝功德，经义何以处之？』」捐之对，先极言征伐不休之敝：「今天下独有关东，关东大者独有齐楚，民众久困，连年流离，离其城郭，相枕席于道路」；又算以往羌军之费，「费四十余万万，大司农钱尽，乃以少府禁钱续之」；其究归一请：「臣愚以为非冠带之国，禹贡所及，春秋所治，皆可且无以为。愿遂弃珠崖，专用恤关东为忧。」对奏，上以问丞相御史，「御史大夫陈万年以为当击；丞相于定国以为『前日兴兵击之连年，护军都尉、校尉及丞凡十一人，还者二人，卒士及转输死者万人以上，费用三万万余，尚未能尽降。今关东困乏，民难摇动，捐之议是。』」上乃从之，遂下诏曰：「今廷议者或言可击，或言可守，或欲弃之，其指各殊。朕日夜惟思议者之言，羞威不行，则欲诛之；狐疑辟难，则守屯田；通于时变，则忧万民。夫万民之饥饿，与远蛮之不讨，危孰大焉？……其罢珠崖郡。民有慕义欲内属，便处之；不欲，勿彊。」传结曰「珠崖由是罢」。", "impact": "这是西汉自武帝开边以来第一次以诏书撤所置郡、明认其地不可守，「弃地」自此成为朝议中可用的选项；而诏自陈其所易之秤——「通于时变，则忧万民」，故以万民之饥饿较远蛮之不讨——与同年六月诏「佐阴阳之道」同一思路，亦即此后初元五年星孛之诏所本。其后捐之本人以「捐之竟坐弃市」收场，议可得用而议者不免于死，此中关连本站不武断。", "figures": ["贾捐之", "于定国", "陈万年", "刘奭"], "place": "珠崖郡（今海南岛一带）及长安", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·贾捐之传》"], "tags": ["罢郡", "珠崖", "恤关东"]}, "related": ["cn--b48--i01", "cn--b44--e01", "cn--b41--e01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪、卷六十四下贾捐之传）", "at": "2026-11-07", "note": "罢郡之年从《元帝纪》初元三年；《传》但云「元帝初元元年珠崖又反…连年不定」，其议与诏在数年之后，本条不据传文改系年。「其罢甘泉、建章宫卫」一诏在本页依年初标记读为初元三年六月，卷中「三年」二字由位置推得，非本页另有明文。「不欲，勿彊」本页作「彊」不作「强」，照录不改。「舍十六县，户二万三千余」之「舍」本页作「合」。卷六十四下页首标 Textquality 25%，引文只照录本页，未取别本互校；「捐之竟坐弃市」在本传叙于罢珠崖之后，其坐罪之由与本案是否相及，传文自为一段，本条不牵合，仅志其先后。本次回改三处归因：①「珠崖内属为郡久矣…经义何以处之」非「有司」之辞，传明书「上使侍中驸马都尉乐昌侯王商诘问捐之曰」，本站旧稿作「有司难之」系误；②「合十六县，户二万三千余」与「自初为郡至昭帝始元元年…凡六反叛…」二段皆传家叙事（叙武帝立郡以来之籍数与反叛之频），非捐之疏中之言，本条已归位于传；③「夫万民之饥饿，与远蛮之不讨，危孰大焉」在诏文之内（「遂下诏曰」之下），非捐之对语，本条亦改归诏。「珠崖虏杀吏民，背畔为逆」亦诏文首句，本条不引。「捐之数短显」一节在下文别为一段，与本诏不相连，本条不牵合。"}]},
  {"id": "cn--b45--p01", "track": "cn", "year": -45, "yearApprox": false, "dim": "politics", "weight": 3, "title": "外戚许史盛而京房讥灾异", "summary": "帝舅史高为大司马，京房以异灾推原近习。", "detail": {"background": "元帝以师傅外戚自辅，舅乐平侯史高以大司马车骑将军领尚书事，许伯、许嘉子弟并在侍中；同时日蚀、地震数至。", "process": "初元、建昭之间（前48—前34），京房以焦延寿易说推灾异，数上书言乱之本在近习，请考功课吏以应天变；石显、五鹿充宗疾之，建言试房为郡守，遂出守魏郡，到任月余征下狱，建昭二年（前37）坐「窥道诸侯王以邪意、漏泄省中语」要斩、弃市，妻子徙边（死事与三处异文见 cn--b37--p01）。", "impact": "外戚与中书宦官同时得势，使儒臣两头受压；以灾异指斥近习自此成为士人唯一的进言通道，京房之死则是这条通道上的第一个著名牺牲。", "figures": ["京房", "史高", "石显"], "place": "长安", "state": "西汉", "sources": ["《汉书·京房传》", "《汉书·元帝纪》"], "tags": ["外戚", "灾异", "京房"]}, "related": ["cn--b37--p01", "cn--b40--s01", "cn--b47--p01", "cn--b24--p02"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪、卷七十五京房传、卷八十淮阳宪王传）", "at": "2026-11-07", "note": "本次回改系年：本站旧文作「永光二年（约前42）坐讥切为石显所构，弃市，妻徙边」，检《元帝纪》京房之死在建昭二年（卷内「二年春正月」之下书「淮阳王舅张博、魏郡太守京房…博要斩，房弃市」），《京房传》又有「房以建昭二年二月朔拜」「房去月余，竟征下狱」为内证，永光二年《纪》但书西羌反，无京房事，故旧系年作废，改从建昭二年，死事另立 cn--b37--p01。「妻徙边」旧无出处，检唯《淮阳宪王传》作「妻子徙边」，《京房传》与《纪》皆不言徙，今补其出处并注明系彼传之文，不与《纪》《传》并计。又旧题「初元、永光之间」改「初元、建昭之间」，因《传》自云「永光、建昭间…房数以灾异进」，非止永光。"}]},
  {"id": "cn--b44--e01", "track": "cn", "year": -44, "yearApprox": false, "dim": "economy", "weight": 3, "title": "星孛于参，诏罢盐铁官、齐三服官、常平仓", "summary": "以灾异下诏，省宫卫、工官、榷利与平准，又罢博士弟子之员以广学者。", "detail": {"background": "自初元以来连年灾害，关东困乏；捐之议罢珠崖后二年，朝廷又以省费为务。贡禹请罢采珠冶铸之议（见 cn--b48--e01）已先发其端。", "process": "前44年（初元五年）。《汉书·元帝纪》：「夏四月，有星孛于参。」诏曰：「朕之不逮，序位不明，众僚久崃，未得其人。元元失望，上感皇天，阴阳为变，咎流万民，朕甚惧之。乃者关东连遭灾害，饥寒疾疫，夭不终命。诗不云乎？『凡民有丧，匍匐救之。』其令太官毋日杀，所具各减半。乘舆秣马，无乏正事而已。罢角抵、上林宫馆希御幸者、齐三服官、北假田官、盐铁官、常平仓。博士弟子毋置员，以广学者。」诏外又纪其事：「省刑罚七十余事。除光禄大夫以下至郎中保父母同产之令。」", "impact": "一次灾异之诏把武帝以来的三项利官（盐铁、均输平准之常平仓、齐三服官之工）与角抵、宫馆同时罢去，是元帝朝儒臣省费论的最大宗落实；但三年之内即有「复盐铁官、博士弟子员」之诏，其文自书「以用度不足，民多复除，无以给中外繇役」（见 cn--b41--e01）——省费之政败于费之不可省，此后可见的禁奢与榷利之争皆循此局。", "figures": ["刘奭", "贡禹", "于定国"], "place": "长安及盐铁郡国", "state": "西汉", "sources": ["《汉书·元帝纪》"], "tags": ["灾异诏", "罢盐铁", "省费"]}, "related": ["cn--b41--e01", "cn--b48--e01", "cn--b46--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪）", "at": "2026-11-07", "note": "本条诏文与罢郡国之庙不同年，前此条目旧说曾混及，本次按卷内年标记逐条核位：星孛在初元五年夏四月，「罢祖宗庙在郡国者」在永光四年，两事相隔四年，本条不并。本页「众僚久崃」之「崃」照录，旧注或读为「乣」或改作「劣」，本站不取，已志为字形；「无乏正事」本页作「乏」，「阴阳为变」本页连写无空格，维基文本他处有「陰陽 為變」之类排版空格，比对时按去空白处理。「省刑罚七十余事」下之「除光禄大夫以下至郎中保父母同产之令」在本页属诏文续句，本条从连写。「省刑罚七十余事」二句在本页作诏文引号之外之纪事，非诏语，本站旧稿误作诏文续句，本次改正并移入纪事。◆ 本次回改：background 旧作「捐之议罢珠崖之次年」，检罢珠崖在初元三年（前46，见 cn--b46--i01），本诏在初元五年（前44），相去二年，故改「次年」为「后二年」。"}]},
  {"id": "cn--b44--f01", "track": "cn", "year": -44, "yearApprox": false, "dim": "figure", "weight": 2, "title": "御史大夫贡禹卒，迭毁之议未及施行", "summary": "贡禹奏七庙亲尽宜毁及郡国庙不应古礼，帝是其议而未行，其年冬禹卒。", "detail": {"background": "贡禹以贤良征，历谏大夫、御史大夫，在位以节俭振淹滞为事；其议省苑马、罢珠冶、汰冗员，多与初元五年星孛之诏相合（见 cn--b44--e01）。宗庙之制，自高后定「敢有擅议者弃市」之令，百余年无人敢言。", "process": "前44年（初元五年）冬。《汉书·元帝纪》：「冬十二月丁未，御史大夫贡禹卒。」◆《韦贤传》载其议之始末：「至元帝时，贡禹奏言：『古者天子七庙，今孝惠、孝景庙皆亲尽，宜毁。及郡国庙不应古礼，宜正定。』天子是其议，未及施行而禹卒。」《京房传》追叙亦云：「其后，贡禹亦言当定迭毁礼，上遂从之。」", "impact": "「未及施行而禹卒」一句，是元帝朝礼制改革的一个转折点：一人之死使宗庙之议延了四年，直到韦玄成等乃果行罢郡国庙之事（见 cn--b40--i01）；赞所论「贡、薛、韦、匡迭为宰相」而「上牵制文义，优游不断，孝宣之业衰焉」，其「不断”正见于此类议行相迟之隙。", "figures": ["贡禹", "刘奭", "韦玄成"], "place": "长安", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·韦贤传》", "《汉书·京房传》"], "tags": ["迭毁", "宗庙", "贡禹"]}, "related": ["cn--b40--i01", "cn--b48--e01", "cn--b34--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪、卷七十三韦贤传、卷七十五京房传）", "at": "2026-11-07", "note": "禹卒之日《纪》明书「冬十二月丁未」，本条系年与卒日皆从《纪》；其议则《纪》不系年，《传》但云「至元帝时」，《京房传》以「其后」追叙，故本条把议与卒同系于卒年，checks 里明记此为依「未及施行而禹卒」之序而推，非本书另有所系。「古者天子七庙」一节《传》文以引号行款连书，本站按一页之本照录；卷七十三页首标 Textquality 25%。「贡、薛、韦、匡迭为宰相」与「优游不断」出《元帝纪》赞，属史家评骘，本条只在 impact 中引其语，不据以断贡禹之功罪。"}]},
  {"id": "cn--b43--c01", "track": "cn", "year": -43, "yearApprox": false, "dim": "culture", "weight": 2, "title": "丞相匡衡说齐诗", "summary": "无说诗匡鼎来，解人颐之语行于朝廷。", "detail": {"background": "匡衡世习《齐诗》，家贫而力学，说诗冠一时；以经术自累迁至丞相，封乐乡侯，朝廷大议多引经义为断。", "process": "建昭、竟宁之间（约前43—前34）衡为御史大夫、丞相，数引《诗》义傅经决事，说诗为世所称，时人为之语曰「无说诗，匡鼎来；匡说诗，解人颐」。", "impact": "经学由家法变成士人升进的正途，解经者的名望可与官爵并称；以《诗》为决事之据，也确立了此后以经术缘饰吏事的样板，其弊则在章句破碎与经义附会。", "figures": ["匡衡"], "place": "长安", "state": "西汉", "sources": ["《汉书·匡衡传》", "《西京杂记》"], "tags": ["齐诗", "家法", "以经饰吏"]}, "related": ["cn--b51--c01", "cn--b124--i01"]},
  {"id": "cn--b42--m01", "track": "cn", "year": -42, "yearApprox": false, "dim": "military", "weight": 3, "title": "陇西羌反：冯奉世请发四万，诏止二万", "summary": "以「少发师而旷日，与一举而疾决，利害相万」力争，卒益兵至六万余乃平。", "detail": {"background": "永光二年秋，岁比不登，京师谷石二百余，边郡四百，关东五百，四方饥馑而羌变起。朝廷方以用度不足为忧（其前一年始罢盐铁、常平仓诸利官，见 cn--b44--e01），故于发兵之数尤吝。", "process": "前42年（永光二年）。《汉书·元帝纪》：「秋七月，西羌反，遣右将军冯奉世击之。八月，以太常任千秋为奋威将军，别将五校并进。」◆《冯奉世传》：「秋，陇西羌彡姐旁种反，诏召丞相韦玄成、御史大夫郑弘、大司马车骑将军王接、左将军许嘉、右将军奉世入议。」时议廷中，「玄成等漠然莫有对者」，奉世独曰「羌虏近在境内背畔，不以时诛，亡以威制远蛮。臣愿帅师讨之」，且计其数：「今反虏无虑三万人，法当倍用六万人。然羌戎弓矛之兵耳，器不犀利，可用四万人，一月足以决。」丞相、御史、两将军皆以为民方收敛时，未可多发，万人屯守之且足。奉世难之：「今以万人分屯数外，虏见兵少，必不畏惧，战则挫兵病师，守则百姓不救」「故少发师而旷日，与一举而疾决，利害相万也。」争之不得，「有诏益二千人」「于是遣奉世将万二千人骑，以将屯为名」。前军进，「羌虏盛多，皆为所破，杀两校尉」。奉世乃尽上地形部众之计，请益三万六千人，「书奏，天子大为发兵六万余人」，更拜任千秋为将军以助；奉世上言「愿得其众，不须烦大将」。至「十月，兵毕至陇西。十一月，并进。羌虏大破，斩首数千级，余皆走出塞」。《纪》于永光三年书「春，西羌平，军罢」。明年二月奉世还京师，更为左将军光禄勋如故；「其后录功拜爵，下诏曰」，数其功作「斩捕首虏八千余级，卤马、牛、羊以万数」，「赐奉世爵关内侯，良邑五百户，黄金六十斤」，「裨将、校尉三十余人，皆拜」。传又别称其「居爪牙官前后十年，为折冲宿将，功名次赵充国」——此九字出传家之论，非诏文。", "impact": "一场胜负无悬念的羌役，把元帝朝的财政约束照得清楚：四万之请只给一万二，直到前军折两校尉乃发六万余人；「利害相万」之算与「民方收敛时，未可多发」之吝，是此后百年边役反复出现的两造。同时它也是贡禹—京房一系言灾异的实事背景，《京房传》即并举「永光、建昭间，西羌反，日蚀，又久青亡光，阴雾不精」。", "figures": ["冯奉世", "韦玄成", "任千秋", "郑弘", "刘奭"], "place": "陇西（今甘肃临洮一带）", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·冯奉世传》", "《汉书·京房传》"], "tags": ["羌役", "发兵之数", "以将屯为名"]}, "related": ["cn--b44--e01", "cn--b37--p01", "cn--b41--e01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪、卷七十九冯奉世传、卷七十五京房传）", "at": "2026-11-07", "note": "四处异文并存不合并：①同一任千秋，《纪》永光二年作「奋威将军」，《传》作「奋武将军」，本条两存其目，不订其孰是；②斩虏之数，《传》叙事作「斩首数千级」，《传》所载诏书作「斩捕首虏八千余级」，本条分系于叙与诏，不取中数；③《纪》但书遣将与年月，《传》具载廷议之争与益兵之节；④羌名《传》作「陇西羌彡姐旁种」，本页字形如此，未取别本校改。「可用四万人，一月足以决」与「有诏益二千人」之间，《传》序明为争而不从，本条不从《纪》之「八月别将五校并进」推其因。卷七十九页首标 Textquality 25%，引文只照录本页；「法当倍用六万人」之「法」指汉发兵法数，本站不释为定制已行。\"居爪牙官前后十年，为折冲宿将，功名次赵充国\"在《冯奉世传》叙于「后岁余，奉世病卒」之下，属传家评骘，本站旧稿误作诏之所称，本次改正归位；诏文止于「赐奉世爵关内侯，良邑五百户，黄金六十斤」，其下别有「裨将、校尉三十余人，皆拜」一句，本条补其目。"}]},
  {"id": "cn--b41--e01", "track": "cn", "year": -41, "yearApprox": false, "dim": "economy", "weight": 2, "title": "复盐铁官、博士弟子员：罢三年而还", "summary": "诏自书其所以然——用度不足，民多复除，无以给中外繇役。", "detail": {"background": "初元五年星孛之诏罢盐铁官、常平仓与齐三服官，又令博士弟子毋置员；至是三年，陇西羌反方发六万余人（见 cn--b42--m01），边用与役事俱急。", "process": "前41年（永光三年）。《汉书·元帝纪》：「冬，复盐铁官、博士弟子员。以用度不足，民多复除，无以给中外繇役。」", "impact": "诏文把复设的理由自己说了出来：省费之政一旦行过，免除之户日多而课役之源日缩，朝廷非回头不可；由此可知元帝朝儒臣所争「罢榷利」并非败于议论，而败于无可代之入。此后终西汉之世盐铁之官不复罢，本条是这一局面的第一个自认。", "figures": ["刘奭"], "place": "长安及盐铁郡国", "state": "西汉", "sources": ["《汉书·元帝纪》"], "tags": ["复盐铁", "用度不足", "复除"]}, "related": ["cn--b44--e01", "cn--b42--m01", "cn--b55--e02"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪）", "at": "2026-11-07", "note": "「罢三年而还」依卷内年标记推得：罢在初元五年，复在永光三年，首尾跨三个年头，举成数而言三载，本条不更定为整三年。「无以给中外繇役」本页作「繇」不作「徭」，照录。《纪》于是年但书此二事之复，不载盐铁官复设之员额与郡数，本条不补；罢、复之间是否有司存之名，本书无明文，本站不推。"}]},
  {"id": "cn--b40--s01", "track": "cn", "year": -40, "yearApprox": true, "dim": "science", "weight": 2, "title": "京房奏考功课吏法，温室之议不可许", "summary": "请以课第能否为黜陟，公卿朝臣会议以为烦碎，刺史复以为不可行。", "detail": {"background": "京房治《易》于焦延寿，好钟律、知音声，以六十四卦候气、分配昼夜寒温，以灾异验政事之得失。", "process": "《京房传》不别系其年，但云「永光、建昭间，西羌反，日蚀，又久青亡光，阴雾不精」之后，房数以灾异进；其法之议在出守魏郡（建昭二年二月）之先，故本站仍以前40年为约值，且已标为约年，不假定为本书所定之实年。传叙始末：「诏使房作其事，房奏考功课吏法。上令公卿朝臣与房会议温室，皆以房言烦碎，令上下相司，不可许。上意乡之。」又「时部刺史奏事京师，上召见诸刺史，令房晓以课事，刺史复以为不可行」「唯御史大夫郑弘、光禄大夫周堪初言不可，后善之」。其后石显、五鹿充宗「建言宜试以房为郡守」，元帝以房为魏郡太守，「得以考功法治郡」——其法唯一得行于一郡，期月而败（见 cn--b37--p01）。", "impact": "以量化课第取代资历与举主之荐，是汉代吏治思想中罕见的制度设想；然本书所记只有奏其法、会议不许、试之一郡三层，未尝立为科目——奏其法、议于公卿、试之一郡是三事，立为一科则本书无文，故题但言奏法与会议不许。其法虽废，考功课吏与综核名实之论自此成为批判吏治因循的常用命题。", "figures": ["京房", "焦延寿"], "place": "长安及魏郡（今河北大名一带）", "state": "西汉", "sources": ["《汉书·京房传》", "《汉书·元帝纪》"], "tags": ["考功课吏", "易学", "焦京之学"]}, "related": ["cn--b45--p01", "cn--b37--p01", "cn--b65--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷七十五京房传）", "at": "2026-11-07", "note": "本次回改两处口径：①旧题「京房立考功课吏之科」，检《传》但云「房奏考功课吏法。上令公卿朝臣与房会议温室，皆以房言烦碎，令上下相司，不可许」，又「刺史复以为不可行」，终未立为科目，故改题「奏考功课吏法，温室之议不可许」；②旧系前40年而标 yearApprox 为否，检《传》不别系其年，但于「永光、建昭间，西羌反，日蚀，又久青亡光，阴雾不精」之下叙其进言，本书无年可据，故 yearApprox 改判为是，年值仍以前40年为约——取其在出守魏郡（建昭二年二月朔拜）之先，非本书所定。「上意乡之」四字本页作「乡」，照录；「唯御史大夫郑弘、光禄大夫周堪初言不可，后善之」为本条所据唯一朝臣转意之文，卷七十五页首标 Textquality 25%，引文只照录本页。"}]},
  {"id": "cn--b40--i01", "track": "cn", "year": -40, "yearApprox": false, "dim": "institution", "weight": 4, "title": "罢祖宗庙在郡国者，园不奉祠：高后擅议之令自此除", "summary": "玄成等七十人奏「宗庙在郡国，宜无修」，罢郡国庙；月余复议，四十四人以「亲尽宜毁」定京师制。", "detail": {"background": "汉高祖以来因「所亲」于郡国立祖宗庙，至元帝时凡祖宗庙在郡国者六十八，合百六十七所；京师自高祖下至宣帝与太上皇、悼皇考各自居陵旁立庙，并为百七十六。旧制日祭于寝、月祭于庙、时祭于便殿，一岁祠上食二万四千四百五十五，用卫士四万五千一百二十九人、祝宰乐人万二千一百四十七人。高后时以臣下妄非议宗庙寝园官，定著令「敢有擅议者弃市」，百余年莫敢正言；贡禹之议发其端而不行（见 cn--b44--f01）。", "process": "前40年（永光四年）。《汉书·元帝纪》：「九月戊子，罢卫思后园及戾园。冬十月乙丑，罢祖宗庙在郡国者。诸陵分属三辅。」◆《韦贤传》：永光四年「乃下诏先议罢郡国庙」，诏自言「久遵而不定，令疏远卑贱共承尊祀，殆非皇天祖宗之意，朕甚惧焉」，其与将军、列侯、中二千石、诸大夫、博士、议郎议。丞相玄成、御史大夫郑弘、太子太傅严彭祖、少府欧阳地余、谏大夫尹更始等七十人皆曰「臣等愚以为宗庙在郡国，宜无修，臣请勿复修」，「奏可。因罢昭灵后、武哀王、昭哀后、卫思后、戾太子、戾后园，皆不奉祠，裁置吏卒守焉。」罢郡国庙后月余，复下诏议迭毁，「玄成等四十四人奏议」引《礼》与《祭义》明五庙迭毁、祫祭合食之义，其文甚长，断于其末曰「太上皇、孝惠、孝文、孝景庙皆亲尽宜毁，皇考庙亲未尽，如故」。传又志其制令之变：「初，高后时患臣下妄非议先帝宗庙寝园官，故定著令，敢有擅议者弃市。至元帝改制，蠲除此令。」", "impact": "这是汉家宗庙之制自大祖以下最大的一次收缩：百六十七所郡国庙尽废，京师陵旁之庙议毁其亲尽者，所省不止祠费，更是缘亲立庙这一把刘氏血缘分播天下的制度。同时被蠲除的「敢有擅议者弃市」之令，使议宗庙自此成为儒臣可言的公务——四年内朝廷因上寝疾而尽复所罢寝庙园（见 cn--b34--i01），然「唯郡国庙遂废云」，收缩之中复有一条不可回之线。", "figures": ["韦玄成", "郑弘", "严彭祖", "欧阳地余", "尹更始", "刘奭"], "place": "长安及各郡国", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·韦贤传》"], "tags": ["迭毁", "郡国庙", "蠲擅议之令"]}, "related": ["cn--b44--f01", "cn--b34--i01", "cn--b47--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪、卷七十三韦贤传）", "at": "2026-11-07", "note": "年月日《纪》三明而《传》但云「永光四年，乃下诏先议罢郡国庙」，本条从《纪》取「九月戊子」「冬十月乙丑」之日，议事节次从《传》。两处人数异文并存：《传》先载「丞相玄成、御史大夫郑弘、太子太傅严彭祖、少府欧阳地余、谏大夫尹更始等七十人皆曰」，后载「玄成等四十四人奏议」，本站不订其为一为再署、亦不以四十四改七十。所罢园号《纪》作「卫思后园及戾园」，《传》作「昭灵后、武哀王、昭哀后、卫思后、戾太子、戾后园」，《纪》略其目，《传》备其名，两存不合并。「毁太上皇、孝惠皇帝寝庙园」《纪》在永光五年十二月乙酉，与本条不同年，故不写入本条正文，只在此志其序。「岁祠上食二万四千四百五十五」之数出《传》，其下「养牺牲卒不在数中」亦同，本条照录，不与它计。卷七十三页首标 Textquality 25%，引文只照录本页。七十人之对与四十四人之奏在传为两诏两议，前主郡国庙无修、后主京师亲尽迭毁，本站旧稿混为一次，本次依传文分系；旧稿「京师百七十六所之半」系本站推算，本书无此文，已删。「百六十七所」「百七十六」「三十所」「二万四千四百五十五」皆传家所记之数，其孰为罢、孰为存，本书不各各对应，本条只据罢郡国之明文立说。四十四人之奏后，本页别有异词三起：大司马车骑将军许嘉等二十九人以孝文宜为帝者太宗之庙、廷尉忠以孝武宜为世宗之庙、谏大夫尹更始等十八人以为皇考庙上序于昭穆非正礼宜毁，与四十四人「皇考庙亲未尽，如故」之断相反，本条不备引，只志其朝议未为一尊。四十四人奏议《传》所引是一大段经义之文（自「礼，王者始受命」至「皇考庙亲未尽，如故」），本条只截其末断一句，不作跨段连续拼合。"}]},
  {"id": "cn--b37--p01", "track": "cn", "year": -37, "yearApprox": false, "dim": "politics", "weight": 4, "title": "京房弃市：魏郡太守到任月余，征下狱", "summary": "房以考功课吏出守魏郡，未期月以「窥道诸侯王以邪意、漏泄省中语」与张博并坐，博要斩、房弃市。", "detail": {"background": "京房以焦延寿易说推灾异，永光、建昭间屡言乱本在近习，请考功课吏以应天变（见 cn--b45--p01、cn--b40--s01）。「石显、五鹿充宗皆疾房，欲远之，建言宜试以房为郡守」，元帝遂以为魏郡太守，「得以考功法治郡」。", "process": "前37年（建昭二年）。《汉书·元帝纪》：「淮阳王舅张博、魏郡太守京房坐窥道诸侯王以邪意，漏泄省中语，博要斩，房弃市。」◆《京房传》：「房以建昭二年二月朔拜」，行前上书，「房去月余，竟征下狱」；显「告房与张博通谋，非谤政治，归恶天子，诖误诸侯王」，传文「房、博皆弃巿，弘坐免为庶人」，「房本姓李，推律自定为京氏，死时年四十一」。传又存其临事数语：房指石显而「上亦知之，谓房曰：『已谕』」；其奏课吏法，「上令公卿朝臣与房会议温室，皆以房言烦碎，令上下相司，不可许。上意乡之」；传又载其尝宴见，自幽厉之「君不明，而所任者巧佞」一路逼问，帝自答「以其时乱而君危知之」，至是乃曰「亦极乱耳。尚何道！」房因言「臣恐后之视今，犹今之视前也」；帝良久乃曰「今为乱者谁哉」，房曰「明主宜自知之」，帝云「不知也；如知之，何故用之」，房以「上最所信任，与图事帷幄之中进退天下之士者是矣」为对。传末赞：「京房区区，不量浅深，危言刺讥，构怨彊臣，罪辜不旋踵，亦不密以失身，悲夫！」◆《淮阳宪王传》则作「京房及博兄弟三人皆弃市，妻子徙边」，载其罪目为「房漏泄省中语，博兄弟诖误诸侯王，诽谤政治，狡猾不道，皆下狱」，又断其源曰「推原厥本，不祥自博」；后「上加恩，许王还徙者」。", "impact": "《元帝纪》一书「要斩」、一书「弃市」，两人之刑与妻子徙边之条并见，考功课吏之法自此不复试于郡。京房之死是元帝朝以灾异进言这条通道上第一个著名牺牲（其议起于前45年，见 cn--b45--p01）；而温室之议「上意乡之」而公卿不许、魏郡之除「得以考功法治郡」而期月见收，可见其法之败不在理之不通，而在行法之人即在其所劾之列。", "figures": ["京房", "张博", "石显", "五鹿充宗", "刘奭", "刘钦"], "place": "长安及魏郡（今河北大名一带）", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·京房传》", "《汉书·淮阳宪王传》"], "tags": ["考功课吏", "漏泄省中语", "弃市"]}, "related": ["cn--b45--p01", "cn--b40--s01", "cn--b42--m01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪、卷七十五京房传、卷八十淮阳宪王传）", "at": "2026-11-07", "note": "三处异文并存不合并：①《纪》作「博要斩，房弃市」，《京房传》作「房、博皆弃巿」（本页「巿」字如此，非「市」），《淮阳宪王传》作「京房及博兄弟三人皆弃市，妻子徙边」——刑名、人数、家属之徙三处不同，本条三存其目；②《纪》罪目但云「窥道诸侯王以邪意，漏泄省中语」，《传》益以「非谤政治，归恶天子，诖误诸侯王」；③徙边之「还徙」唯《宪王传》有之，「上加恩，许王还徙者」不言在何年，本条不系。系年从《纪》建昭二年，得《传》「房以建昭二年二月朔拜」「房去月余」为内证；「死时年四十一」亦出《传》。「已谕」二字《传》作帝语，其指何事历来异解，本条只照录其言，不取其解。卷七十五、卷八十页首均标 Textquality 25%，引文只照录本页。「亦极乱耳。尚何道」在传叙次序先于「臣恐后之视今，犹今之视前也」，本站旧稿把两句倒置，本次改正。宴见一问之节次依本页原文照录，其中帝问「视今为治邪，乱邪」本页作「陆下」，属本页字形，未取别本改作「陛下」；「幽厉之君何以危」一问答凡七反，本条不备引。"}]},
  {"id": "cn--b36--p01", "track": "cn", "year": -36, "yearApprox": false, "dim": "politics", "weight": 2, "title": "元帝劳军渭桥议省戍卒", "summary": "北边无事，天子自劳士众，议罢边备吏卒。", "detail": {"background": "呼韩邪内附以后，北边自朔方至敦煌数世不见烟火之警，吏民逸于田作；单于复上书愿朝，朝臣议其费。", "process": "建昭三年（前36）前后，元帝幸上林、临渭桥，亲劳将帅士众，车骑填咽；诏郡国举茂才，选博士弟子，议省边郡戍卒与吏员，以宽转输之费。", "impact": "劳军、省戍、举贤三事并下，把北边无事经营为太平的表征；这类符号性政治活动的增多，正是元成之际朝政由实务转向典礼与符命的写照。", "figures": ["刘奭"], "place": "长安及北边郡", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·匈奴传》"], "tags": ["劳军", "省戍", "太平叙事"]}, "related": ["cn--b49--p01", "cn--b33--p02"]},
  {"id": "cn--b36--m01", "track": "cn", "year": -36, "yearApprox": false, "dim": "military", "weight": 3, "title": "陈汤矫制诛郅支单于", "summary": "假节发戊己校尉屯田兵入康居，斩郅支。", "detail": {"background": "郅支单于西徙坚昆后与康居为婚，屡攻乌孙、大宛，又杀辱汉使；西域都护不能制，朝廷以道远不肯出。", "process": "建昭三年（前36）西域都护甘延寿、副校尉陈汤矫发戊己校尉屯田吏卒与车师等六国兵，分两道逾葱岭，围郅之于都赖水上，斩阏氏、太子、名王以下千五百余级；传首长安，悬槁街十日。", "impact": "明犯强汉者虽远必诛一语自此而定型，汉军威第一次深入中亚七河；然矫制之功与赏罚之议相难数十年，暴露出都护体制下中央对边将既用又防的两难。", "figures": ["陈汤", "甘延寿", "郅支单于"], "place": "康居都赖水（今哈萨克塔拉兹一带）", "state": "西汉", "sources": ["《汉书·陈汤传》", "《资治通鉴·汉纪》"], "tags": ["郅支", "矫制", "都赖水"]}, "related": ["cn--b47--x01", "cn--b60--i01"]},
  {"id": "cn--b34--i01", "track": "cn", "year": -34, "yearApprox": false, "dim": "institution", "weight": 2, "title": "上疾连年，尽复诸所罢寝庙园；唯郡国庙遂废", "summary": "以寝疾梦祖宗之谴复元年前所罢诸园，六年前所毁之寝庙一时皆还，独郡国庙不复立。", "detail": {"background": "永光四年韦玄成奏罢郡国庙并毁亲尽之寝庙（见 cn--b40--i01），五年又毁太上皇、孝惠皇帝寝庙园；建昭三年玄成薨，匡衡为丞相。《韦贤传》：「上寝疾，梦祖宗谴罢郡国庙，上少弟楚孝王亦梦焉。上诏问衡，议欲复之，衡深言不可。」", "process": "前34年（建昭五年）。《汉书·元帝纪》：「夏六月庚申，复戾园。」「秋七月庚子，复太上皇寝庙园、原庙、昭灵后、武哀王、昭哀后、卫思后园。」◆《韦贤传》综其后：「久之，上疾连年，遂尽复诸所罢寝庙园，皆修祀如故。」又断之一句：「唯郡国庙遂废云。」", "impact": "一场疾病把六年内所废的京师寝庙园尽数收回，匡衡「深言不可」终不能止——汉家礼制之议在元帝朝屡胜而复败，本条最见其败法：不是议者理亏，而是帝以身验之。然郡国庙独不复，缘亲立庙之制自此遂绝，收缩之中留下了不可回的一条线（前事见 cn--b40--i01）。明年五月元帝崩，竟宁、建始之间再无复议。", "figures": ["刘奭", "匡衡", "刘宇"], "place": "长安及各陵寝", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·韦贤传》"], "tags": ["复寝庙园", "梦谴", "郡国庙遂废"]}, "related": ["cn--b40--i01", "cn--b44--f01", "cn--b33--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷九元帝纪、卷七十三韦贤传）", "at": "2026-11-07", "note": "复园之日《纪》二条明书「夏六月庚申」「秋七月庚子」，本条从之；《纪》所列园号止于六名，「尽复诸所罢」之「尽」从《传》，两文数目不等处并存不订。「上疾连年」与「梦谴」皆《传》之叙事，属史家所记之因，本条只据此定复园之举，不据以断元帝寝疾之病证；「楚孝王亦梦焉」孤见于《传》，本条存其说而不加发挥。《传》以「后岁余，玄成薨，匡衡为丞相」叙于前，与《纪》建昭三年六月甲辰「丞相玄成薨」合，本条取以定匡衡主议之人。卷七十三页首标 Textquality 25%，引文只照录本页。"}]},
  {"id": "cn--b33--p01", "track": "cn", "year": -33, "yearApprox": false, "dim": "politics", "weight": 3, "title": "元帝崩成帝立王氏始贵", "summary": "竟宁元年元帝崩，太子骜立，舅王凤秉政。", "detail": {"background": "竟宁元年（前33）五月元帝崩于未央宫，在位十六年，年四十二；皇太子刘骜即位，是曰成帝；帝舅史高与许、史、王氏俱以外家进。", "process": "六月成帝以舅王凤为卫尉侍中，阳朔中迁大司马大将军领尚书事，王谭、王商、王立、王根、王逢时同日封侯，号五侯；刘向以宗室老儒召，典校禁中秘书。", "impact": "元帝一朝外戚与宦寺相参的格局被单方面打破，外戚王氏自此独大，历元、成、哀、平四世不衰；后来的限田之议与禅代之言，都从这一权力结构里长出。", "figures": ["刘骜", "王凤", "刘向"], "place": "长安", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·成帝纪》", "《汉书·外戚传》"], "tags": ["成帝即位", "五侯", "校书"]}, "related": ["cn--b47--p01", "cn--b27--p01", "cn--b26--i01"]},
  {"id": "cn--b33--p02", "track": "cn", "year": -33, "yearApprox": false, "dim": "politics", "weight": 4, "title": "王嫱配呼韩邪号宁胡阏氏", "summary": "以良家子妻单于，边城不闭，改元竟宁。", "detail": {"background": "呼韩邪单于既朝甘泉，复请和亲，愿保塞上谷以西至敦煌，请汉罢边备塞吏卒；汉公卿以为不可卒许。", "process": "竟宁元年（前33），后宫良家子王嫱字昭君，入宫数岁不得见，乃自请掖庭令求行；帝以赐单于，单于号曰宁胡阏氏，上书愿世世保塞；汉因改元曰竟宁，以志边塞之安。", "impact": "和亲自此由对等国家之礼转为册封君臣之仪：汉得竟宁之名，匈奴得公主与缯絮之利，北边得息肩；而画工弃市一类传说，使王嫱成为后世文学中宫怨与和戎最持久的形象。", "figures": ["王嫱", "呼韩邪单于", "刘奭"], "place": "长安及匈奴单于庭", "state": "西汉", "sources": ["《汉书·元帝纪》", "《汉书·匈奴传》", "《西京杂记》"], "tags": ["昭君出塞", "和亲", "竟宁"]}, "related": ["cn--b49--p01", "cn--b55--m01"]},
  {"id": "cn--b32--p01", "track": "cn", "year": -32, "yearApprox": true, "dim": "politics", "weight": 3, "title": "石显徙归故郡，道病死：长安谣记得四个姓", "summary": "丞相御史条奏其旧恶，显与妻子徙归故郡，忧满不食，道病死；长安中为之作谣。", "detail": {"background": "石显字君房，济南人，少坐法腐刑为中黄门，元帝即位数年代弘恭为中书令，「事无小大，因显白决」；其先与恭共倾萧望之、京房，语在卷九十三（见 cn--b47--p01、cn--b37--p01）。竟宁、建始之间元帝崩、成帝立，显失所倚。", "process": "前32年前后（《佞幸传》不书年月，但云「元帝崩，成帝初即位」，又云「显失倚，离权数月」，本条据成帝改元建始一年系之）。《汉书·佞幸传》：迁显为长信中太仆，秩中二千石；「显失倚，离权数月，丞相御史条奏显旧恶，及其党牢梁、陈顺皆免官。」「显与妻子徙归故郡，忧满不食，道病死。」诸所交结以显为官者皆废罢，少府五鹿充宗左迁玄菟太守，御史中丞伊嘉为雁门都尉。「长安谣曰：『伊徙雁，鹿徙菟，去牢与陈实无贾。』」", "impact": "中书宦官之败不自诛戮始，自一人徙归故郡、忧满不食始；长安一谣把四个姓氏的迁徙一次说尽，是京师民口对建始初政最直接的记录。其党与案吏同免，建始四年遂有「罢中书宦官，初置尚书员五人」之文（见 cn--b29--i01），元帝初年萧望之所欲而不得者，至此乃行。", "figures": ["石显", "牢梁", "陈顺", "五鹿充宗", "伊嘉", "成帝刘骜"], "place": "长安、故郡（今陕西西安、山东济南）", "state": "西汉", "sources": ["《汉书·佞幸传》", "《汉书·成帝纪》"], "tags": ["石显", "长安谣", "中书宦官"]}, "related": ["cn--b47--p01", "cn--b33--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷九十三佞幸传）", "at": "2026-11-07", "note": "本条《传》文不系年月，唯叙「元帝崩，成帝初即位」与「离权数月」，故系年取成帝改元建始一年（前32）而标为推定；《元帝纪》《成帝纪》皆无罢免石显之文，其先后一据《佞幸传》。谣三句，上两句各三言、末句七言，《传》不为之训；「无贾」之义与末句句读本站不作定说。「徙归故郡」之故郡据《传》首「济南人」推得，非《传》于此句明文。卷九十三页首标 Textquality 25%，引文只照录本页。◆ 本次回改：impact 旧作「明年遂有罢中书宦官之文」，检 cn--b29--i01 在建始四年（前29），自本条前32相去三年，故以年号「建始四年」代「明年」。"}]},
  {"id": "cn--b32--i01", "track": "cn", "year": -32, "yearApprox": false, "dim": "institution", "weight": 4, "title": "十二月作长安南北郊，罢甘泉、汾阴祠", "summary": "天地之祠合于长安城南北二郊，罢甘泉泰畤、汾阴后土；是日大风，拔甘泉畤中大木十韦以上。", "detail": {"background": "武帝以来祠泰畤于云阳甘泉、祠后土于河东汾阴，天子时行幸之，所过县邑供费；昭帝、元帝以来屡议其劳费。元帝竟宁以前，郊祀犹分三处。", "process": "前32年（建始元年）。《汉书·成帝纪》：「十二月，作长安南北郊，罢甘泉、汾阴祠。」又书是日之异：「是日大风，拔甘泉畤中大木十韦以上。」其春正月已书「有星孛于营室」，其诏则曰「乃者火灾降于祖庙，有星孛于东方」；夏四月「黄雾四塞」，秋「罢上林宫馆希御幸者二十五所」，九月「流星光烛地，长四五丈，委曲蛇形，贯紫宫」，一岁之内异与政并书。", "impact": "郊社自郡国徙于京畿，是汉家祭祀地理的一次改行：此后泰畤、后土皆在长安见郊，明年遂有「辛巳，上始郊祀长安南郊」之文。然罢者非永罢——成帝末年复行幸甘泉、河东，至帝崩而「皇太后诏有司复长安南北郊」，三十年之间三其指；大风拔木见于新祀初定之日，《纪》但书事不系占，本站亦不代为之说。", "figures": ["成帝刘骜", "王凤"], "place": "长安南北郊、甘泉、汾阴（今陕西西安、淳化、山西万荣）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·郊祀志下》"], "tags": ["南北郊", "罢甘泉", "汾阴后土"]}, "related": ["cn--b31--i01", "cn--b48--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪）", "at": "2026-11-07", "note": "「作长安南北郊」，《纪》但书于十二月之下，不载议者之名与制度之详；其详在《郊祀志下》，本条于 sources 列出该志而未录其文，故凡《纪》无而《志》有者（平当以下之驳议、甘泉泰畤复行之岁月）本条皆不道。「孛于营室」与诏「孛于东方」两文并存，《纪》自为记星、诏自为引异，本站不订其一，亦不删其一。「十韦」之义《纪》无注，「韦」读为围与否未敢定，故照录其字。"}]},
  {"id": "cn--b31--p01", "track": "cn", "year": -31, "yearApprox": false, "dim": "politics", "weight": 2, "title": "成帝微行而委政王凤", "summary": "数微行过市里，军国一事决于大司马。", "detail": {"background": "成帝善修容仪而不好史，多畜燕乐；建始、河平之间，外家王氏与赵飞燕、李氏之宠渐盛。", "process": "前31年前后，帝数微出私谒长者，过市里、斗鸡走马，张放、淳于长等以幸臣侍中用事；王凤领尚书事，奏免御史大夫、大臣多其所斥，公卿守文奉法而已。", "impact": "皇权的私人化与政务的代理化同时发生，外戚专政、幸臣乱政与士人上书三条线并行；薛宣、翟方进一辈名臣只能以循职自守，汉制的弹性由此渐失。", "figures": ["刘骜", "王凤", "张放"], "place": "长安", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·叙传》", "《资治通鉴·汉纪》"], "tags": ["微行", "外戚专政", "幸臣"]}, "related": ["cn--b33--p01", "cn--b24--p02"]},
  {"id": "cn--b31--i01", "track": "cn", "year": -31, "yearApprox": false, "dim": "institution", "weight": 3, "title": "辛巳始郊祀长安南郊，减天下赋钱算四十", "summary": "一年之内南北郊皆亲祠，罢雍五畤、六厩技巧官，减赋钱算四十，以闰月作初陵。", "detail": {"background": "建始元年十二月既作长安南北郊、罢甘泉汾阴之祠（见 cn--b32--i01），有司因及雍五畤；郊祀之礼既定于近郊，则三辅繇役、乘舆厩苑皆可省，故是岁之诏以「宽」为文。", "process": "前31年（建始二年）。《汉书·成帝纪》：春正月「罢雍五畤」；「辛巳，上始郊祀长安南郊。」其诏曰「乃者徙泰畤、后土于南郊、北郊，朕亲饬躬，郊祀上帝。皇天报应，神光并见。三辅长无共张繇役之劳」，又「减天下赋钱，算四十」。闰月「以渭城延陵亭部为初陵」。二月「诏三辅内郡举贤良方正各一人」。三月「辛丑，上始祠后土于北郊」「丙午，立皇后许氏」「罢六厩、技巧官」。秋「罢太子博望苑，以赐宗室朝请者。减乘舆厩马」。", "impact": "减赋钱算四十是成帝一朝唯一以诏书定额的田赋减项，与元帝前44年一并罢盐铁、三服官、常平仓之诏同一口径而不同一手法：元帝所罢在官营，成帝所减在民算。又技巧官之罢、博望苑之赐、厩马之减，皆乘舆自损之文，是礼制改行与用度收缩同年并行之证。初陵起于闰月，则郊祀之俭与身后之制已同日而议。", "figures": ["成帝刘骜", "许皇后", "匡衡"], "place": "长安南北郊、渭城（今陕西西安、咸阳）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·食货志上》"], "tags": ["郊祀", "减赋钱算", "延陵"]}, "related": ["cn--b32--i01", "cn--b44--e01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪）", "at": "2026-11-07", "note": "「减天下赋钱，算四十」，《纪》明书算数而不言其所减之率，《食货志》亦不载此事，故本条只照录诏数，不作钱谷之算。「上始郊祀长安南郊」与「始祠后土于北郊」《纪》各系日（辛巳、辛丑），本条从之；立皇后许氏日在丙午，与郊祀同月，《纪》序如此，本站不议其相干。「罢六厩、技巧官」为两官还是一官，《纪》作「六厩、技巧官」，中间一读顿，本条照录其文，不加合并。"}]},
  {"id": "cn--b30--d01", "track": "cn", "year": -30, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "关内大水，讹言水至，长安中大乱", "summary": "关内大水方秋，京师讹言大水至，吏民惊上城；左将军商独以为讹言，不宜令上城重惊百姓。", "detail": {"background": "建始二年夏已大旱，三年秋关内复大水。时大司马大将军凤辅政，左将军乐昌侯商以帝舅居位。", "process": "前30年（建始三年）。《汉书·成帝纪》：「秋，关内大水。」「七月，虒上小女陈持弓闻大水至，走入横城门，阑入尚方掖门，至未央宫钩盾中。吏民惊上城。」九月诏曰：「乃者郡国被水灾，流杀人民，多至千数。京师无故讹言大水至，吏民惊恐，奔走乘城。」《王商传》叙其事最备：「天子亲御前殿，召公卿议。大将军凤以为太后与上及后宫可御船，令吏民上长安城以避水。群臣皆从凤议。左将军商独曰：『自古无道之国，水犹不冒城郭。今政治和平，世无兵革，上下相安，何因当有大水一日暴至？此必讹言也，不宜令上城，重惊百姓。』上乃止。有顷，长安中稍定，问之，果讹言。上于是美壮商之固守，数称其议。而凤大惭，自恨失言。」", "impact": "一事两命：诏以「苛暴深刻之吏未息，元元冤失职者众」自克，《传》以一人之断止群臣之议。是年商未为丞相，明年乃代匡衡（语在《王商传》），故「固守」之议实为其未相时最著一事；而凤「自恨失言」，至阳朔之世构商以闺门之事（见 cn--b24--p01），其隙即起于此日之惭。", "figures": ["王商", "王凤", "陈持弓", "成帝刘骜"], "place": "长安（今陕西西安）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·王商传》"], "tags": ["讹言", "关内大水", "固守"]}, "related": ["cn--b31--p01", "cn--b30--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷八十王商传）", "at": "2026-11-07", "note": "「虒上」，《纪》无注，本站不取其说，故不注今地；「小女陈持弓」但记其事，不揣其后来。《纪》书「秋，关内大水」与「讹言大水至」为一时之两事（讹言因大水而作），《传》则但言「无故相惊」，两文详略不同而事不异，本条从《纪》定水、从《传》定议，不以《传》之「无故」改《纪》之有由。诏文在《纪》九月，而《传》叙商议于召公卿之下，《纪》《传》不相见，故本条只据其年次相连，不据以定同月先后。"}]},
  {"id": "cn--b30--p01", "track": "cn", "year": -30, "yearApprox": false, "dim": "politics", "weight": 3, "title": "戊申朔日有蚀之，夜地震未央宫殿中", "summary": "日蚀与地震同夕，诏公卿各思朕过失明白陈之，又举贤良方正能直言极谏之士。", "detail": {"background": "自初元以来，灾异之诏以日蚀、地震为最重；元帝之世京房以灾异言石显（语在《京房传》），故「举贤良方正」一科，元、成之间每因异而下，非创科。", "process": "前30年（建始三年）冬十二月戊申朔。《汉书·成帝纪》：「冬十二月戊申朔，日有蚀之。夜，地震未央宫殿中。」其诏曰：「盖闻天生众民，不能相治，为之立君以统理之。君道得，则草木昆虫咸得其所；人君不德，谪见天地，灾异娄发，以告不治。」又曰：「公卿其各思朕过失，明白陈之。『女无面从，退有后言。』丞相、御史与将军、列侯、中二千石及内郡国举贤良方正能直言极谏之士，诣公车，朕将览焉。」是岁又书「越嶲山崩」。", "impact": "日蚀在地震之夕，未央宫殿中为天子所居，此异之重不在郡国；诏引《书》「女无面从，退有后言」，责群臣以面从为罪，是成帝即位三年而言路之请已三至（元年博问公卿、二年举贤良方正、三年复举能直言极谏）。然三年之内所举者不见于《纪》，而四年遂有「罢中书宦官，初置尚书员五人」之文，其应在此诏之后。", "figures": ["成帝刘骜", "匡衡"], "place": "长安未央宫、越嶲（今陕西西安、四川西昌）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·五行志下之上》"], "tags": ["日蚀", "地震", "贤良方正"]}, "related": ["cn--b30--d01", "cn--b32--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪）", "at": "2026-11-07", "note": "本条之异以《纪》系日为据（十二月戊申朔）；「夜，地震未央宫殿中」，《纪》不书郡国之地名而书宫名，故从之。《五行志》所载同类之异与《纪》文详略多异（有诏应、有京房以下之占），本条于 sources 列出该志而未录其文，凡未引《志》之占，皆不以灾异说事。越嶲山崩《纪》但四字，郡名《纪》作「越嶲」，本条照录其字。"}]},
  {"id": "cn--b29--i01", "track": "cn", "year": -29, "yearApprox": false, "dim": "institution", "weight": 4, "title": "春罢中书宦官，初置尚书员五人", "summary": "建始四年春罢中书宦官，初置尚书员五人；石显徙归三年后，萧望之所请乃行。", "detail": {"background": "初元中前将军萧望之领尚书事，建白以为「尚书百官之本，国家枢机，宜以通明公正处之」，又曰「武帝游宴后庭，故用宦者，非古制也。宜罢中书宦官，应古不近刑人」，「元帝不听，由是大与显忤」（语在《佞幸传》）。石显既徙归故郡（见 cn--b32--p01），其党牢梁、陈顺、五鹿充宗以下皆免罢。", "process": "前29年（建始四年）。《汉书·成帝纪》：「四年春，罢中书宦官，初置尚书员五人。」《佞幸传》所记望之建白之辞与《纪》所书诏命，前后相去十六年而其事一。是岁又书：夏四月「雨雪」；五月「中谒者丞陈临杀司隶校尉辕丰于殿中」；「秋，桃李实。」冬十月以河决责御史大夫尹忠（见 cn--b29--d01）。", "impact": "中书在禁中，以宦者典奏事，元帝之世权遂出于外朝之上；至是罢之而尚书置员五人，是汉家机要自中书归尚书之一大转，其后尚书遂为百官之本，望之「国家枢机」一语至成帝之世验。殿中司隶校尉为谒者丞所杀，《纪》不言其故，禁省之不严与官制之改，同书于一岁之中。", "figures": ["萧望之", "石显", "成帝刘骜", "陈临", "辕丰"], "place": "长安（今陕西西安）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·佞幸传》"], "tags": ["罢中书宦官", "尚书五人", "枢机"]}, "related": ["cn--b47--p01", "cn--b32--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷九十三佞幸传）", "at": "2026-11-07", "note": "「初置尚书员五人」，《纪》但书员数，不书何官何职之目；其制度之详（为谁增置、中书旧员若干）《纪》《传》皆不足，故本条只据《纪》定罢置之年，不作尚书官属之表。望之建白在初元中，《纪》罢中书在建始四年，中间十六年《传》不记其议，「应古不近刑人」之请何以忽行于此岁，史无明文，本站不推。陈临、辕丰一事《纪》但书变不书狱，两人名位从《纪》，本条不及其罪之所坐。"}]},
  {"id": "cn--b29--d01", "track": "cn", "year": -29, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "河决东郡金堤，灌四郡三十二县", "summary": "河决馆陶及东郡金堤，凡灌四郡三十二县，水居地十五万余顷；御史大夫尹忠以不忧职自杀。", "detail": {"background": "自宣帝以来屯氏河不浚，博士许商行视以为「屯氏河盈溢所为，方用度不足，可且勿浚」；其议中又言「不豫修治，北决病四五郡，南决病十余郡，然后忧之，晚矣」（《沟洫志》）。", "process": "前29年（建始四年）。《汉书·成帝纪》：「大水，河决东郡金堤。」「冬十月，御史大夫尹忠以河决不忧职，自杀。」《沟洫志》载其详：「河果决于馆陶及东郡金堤，泛溢兖、豫，入平原、千乘、济南，凡灌四郡三十二县，水居地十五万余顷，深者三丈，坏败官亭室庐且四万所。」又「御史大夫尹忠对方略疏阔，上切责之，忠自杀」；遣大司农调钱谷、谒者发漕船，「徙民避水居丘陵，九万七千余口」。河堤使者王延世「以竹落长四丈，大九围，盛以小石，两船夹载而下之。三十六日，河堤成」。", "impact": "一次河决把四件事写在同一岁：御史大夫以不忧职死、对方以疏阔责、九万七千余口以徙居计、堤成以三十六日计；明年遂以「堤塞辄平」改元（见 cn--b28--p01）。许商「北决病四五郡」之言未逾三岁而验，是《沟洫志》所记最直的一次预言；其后河复决平原，「所坏败者半建始时」，建始之作于是为后之案。", "figures": ["尹忠", "王延世", "许商", "成帝刘骜"], "place": "东郡金堤、馆陶（今河南濮阳、河北馆陶）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·沟洫志》"], "tags": ["河决", "金堤", "竹落"]}, "related": ["cn--b28--p01", "cn--b29--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷二十九沟洫志）", "at": "2026-11-07", "note": "《纪》书决在秋、责在冬十月，《志》叙许商行视与「后三岁，河果决」于其上，两文所由不同：《纪》以事目系月，《志》以议状相连，本条从《纪》定年、从《志》取数，凡水顷、县数、徙口、堤成之日皆出《志》。《志》「泛溢兖、豫，入平原、千乘、济南」与「凡灌四郡三十二县」，《志》自为计，四郡之名不悉列，本条不为之补目。「竹落」以盛石，其形制后世有异说，《志》但言长短围度，本站照录其文，不作图状之说。"}]},
  {"id": "cn--b28--s01", "track": "cn", "year": -28, "yearApprox": false, "dim": "science", "weight": 2, "title": "浑仪与历数之器渐备", "summary": "治历者并校疏密，浑象之制始具规模。", "detail": {"background": "太初历行用既久，朔晦弦望与天象多不合，宣元以来诏治历者并校诸家疏密，历数须与仪器相辅。", "process": "河平（前28—前25）之间，待诏治历者以浑仪校日月行度、课蚀分数，历数与仪器始相须为用；其后耿寿昌、刘歆相继推校，至东汉遂有三统、四分诸历。", "impact": "浑天仪器由粗具规模到可复验的量化，是历法改革的物质条件；张衡的浑天仪与漏刻、东汉四分历的更造，都承接这一系器物与算法而下。", "figures": ["耿寿昌", "刘歆"], "place": "长安", "state": "西汉", "sources": ["《汉书·律历志》", "《晋书·天文志》"], "tags": ["浑仪", "治历", "课蚀"]}, "related": ["cn--b104--s01", "cn--b104--s02"]},
  {"id": "cn--b28--p01", "track": "cn", "year": -28, "yearApprox": false, "dim": "politics", "weight": 3, "title": "以堤塞改元河平，四月己亥晦日蚀既", "summary": "河平元年以河堤塞辄平改元，夏四月晦日有蚀之既，六月罢典属国并大鸿胪。", "detail": {"background": "建始四年河决东郡金堤，王延世以三十六日塞之（见 cn--b29--d01）；汉家改元有以灾异者、有以功成者，成帝一朝两例皆备，本条为其以功成者。", "process": "前28年（河平元年）。《汉书·成帝纪》：「春三月，诏曰：『河决东郡，流漂二州，校尉王延世堤塞辄平，其改元为河平。赐天下吏民爵，各有差。』」《沟洫志》载其诏曰「东郡河决，流漂二州，校尉延世堤防三旬立塞。其以五年为河平元年」，又「以延世为光禄大夫，秩中二千石，赐爵关内侯，黄金百斤」。夏四月「己亥晦，日有蚀之，既」。诏曰：「朕获保宗庙，战战栗栗，未能奉称。传曰：『男教不修，阳事不得，则日为之蚀。』天著厥异，辜在朕躬。」又「大赦天下」。六月「罢典属国并大鸿胪」。", "impact": "以一年之功改一代之号，又于改元之岁遇日蚀既——《纪》以两文相连，是成帝政事最可读者一节：功成之喜与灾异之惧不相待。罢典属国并入大鸿胪，则属国之官自元鼎置以来九十余岁而省；是岁单于且遣使奉献（见 cn--b28--x01），官省与藩礼同年并见，《纪》各书其事而不道其相及。", "figures": ["王延世", "成帝刘骜"], "place": "长安（今陕西西安）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·沟洫志》"], "tags": ["改元河平", "日蚀既", "罢典属国"]}, "related": ["cn--b29--d01", "cn--b28--x01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷二十九沟洫志）", "at": "2026-11-07", "note": "改元之诏两文不同：《纪》作「其改元为河平」，《志》作「其以五年为河平元年」；「五年」指建始五年，则《志》以是岁为改元之始，《纪》系河平元年于次年正月之下，两文纪年之例各异，本站不订，亦不据《志》改《纪》之年号。《纪》书「校尉王延世」，《志》书「校尉延世」；延世官号前后有河堤使者、校尉、光禄大夫之别，《纪》《志》所书不一，本条照录各文所用之号。「男教不修，阳事不得，则日为之蚀」，《纪》托为传语，不著其所出。"}]},
  {"id": "cn--b28--i01", "track": "cn", "year": -28, "yearApprox": false, "dim": "institution", "weight": 2, "title": "秋九月，复太上皇寝庙园", "summary": "两《纪》七年间再书复太上皇寝庙园，其间不书罢，元、成庙议之未了者至此犹在。", "detail": {"background": "永光四年韦玄成奏罢郡国庙并毁亲尽之寝庙（见 cn--b40--i01），五年又毁太上皇、孝惠皇帝寝庙园；建昭五年元帝以寝疾尽复诸所罢寝庙园，独「唯郡国庙遂废」（见 cn--b34--i01）。", "process": "前28年（河平元年）秋九月。《汉书·成帝纪》：「秋九月，复太上皇寝庙园。」《元帝纪》建昭五年则曰「秋七月庚子，复太上皇寝庙园、原庙、昭灵后、武哀王、昭哀后、卫思后园」。", "impact": "同一园名，七岁之间两见复文而中间无罢文，是元、成之际庙议未尝了的最直证据：建昭之复出于帝之自验（寝疾梦谴），河平之复不知其由，《成帝纪》不书议者、不书诏。自永光至此二十二年，罢、毁、复、复四文俱在两《纪》，汉家宗庙之制终以「唯郡国庙遂废」一句为止，其余皆回环。", "figures": ["成帝刘骜", "韦玄成", "匡衡"], "place": "长安、太上皇陵（今陕西西安、富平一带）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·元帝纪》", "《汉书·韦贤传》"], "tags": ["寝庙园", "迭毁之议", "太上皇"]}, "related": ["cn--b34--i01", "cn--b40--i01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪）", "at": "2026-11-07", "note": "本条之最可议处即《纪》文自身：建昭五年已「复太上皇寝庙园」，河平元年再书「复」，其间七年两《纪》与《韦贤传》皆不书罢此文园，或前复之中又有废，或史家重出，《纪》无明文，本站两存其文而不强为之说，亦不以两「复」字为一次。太上皇陵所在，《纪》不言，今地依常识标举，非《汉书》此文所定；本条只核园名与月日。"}]},
  {"id": "cn--b28--x01", "track": "cn", "year": -28, "yearApprox": false, "dim": "explore", "weight": 2, "title": "伊邪莫演来降，谷永杜钦议勿受", "summary": "单于遣右皋林王奉献朝正月；既而汉议受降之不可，谷永、杜钦以为贪一夫之得而失一国之心。", "detail": {"background": "竟宁元年呼韩邪尚汉女（见 cn--b33--p02），复株絫若鞮单于立，遣子入侍，「复妻王昭君」；汉与呼韩邪一系自甘露、黄龙以来为北藩，故接遇之宜异于往时。", "process": "前28年（河平元年）。《汉书·匈奴传下》：「河平元年，单于遣右皋林王伊邪莫演等奉献朝正月。」其下有降人之议，光禄大夫谷永、议郎杜钦以为「今单于诎体称臣，列为北藩，遣使朝贺，无有二心，汉家接之，宜异于往时。今既享单于聘贡之质，而更受其逋逃之臣，是贪一夫之得而失一国之心，拥有罪之臣而绝慕义之君也」，又言「不如勿受，以昭日月之信」。天子从之，「遣中郎将王舜往问」降状；伊邪莫演曰：「我病狂妄言耳。」遣去，归到，官位如故，不肯令见汉使。", "impact": "汉家待降人旧设金爵之赏，至是以慕义之君重于有罪之臣，是藩臣礼成后边夷接遇的一次改口径；其人归而「官位如故，不肯令见汉使」，则汉之不受反成其在国中之累，此议之所及而不言者。其后单于上书愿朝，遂有河平四年之入朝（见 cn--b25--p01）。", "figures": ["谷永", "杜钦", "伊邪莫演", "复株絫若鞮单于", "王舜"], "place": "长安（今陕西西安）", "state": "西汉", "sources": ["《汉书·匈奴传下》", "《汉书·成帝纪》"], "tags": ["受降", "谷永", "北藩"]}, "related": ["cn--b33--p02", "cn--b25--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷九十四下匈奴传下）", "at": "2026-11-07", "note": "本页此段有脱讹：「奉献朝正月」而下作「既罢，遣使者送至蒱反。伊故事，受其降」，文不可读，故降人如何至、何人请受、章下何官，《传》之始末于本站不可得而述；本条只引其可读之辞（谷永、杜钦之议与其人之言），凡其间程序一概不书。「我病狂妄言耳」六字旧读或以病为狂、以妄言为辞，本页不作句读之定。单于庭地望《传》无明文，本条 place 但举长安（奉献之所至），不别标庭所。◆ 本次回改：impact 旧作「明年单于上书愿朝（见 cn--b25--p01）」，《传》于上书不别系年，而所引之入朝在河平四年（前25），自本条前28相去三年，非明年，故改「明年」为「其后」，引文标注移到入朝句上。"}]},
  {"id": "cn--b27--p01", "track": "cn", "year": -27, "yearApprox": false, "dim": "politics", "weight": 2, "title": "五人同日封，故世谓之五侯", "summary": "河平二年六月悉封舅谭、商、立、根、逢时为列侯；王氏子弟分据势官，满朝廷。", "detail": {"background": "建始元年已「封舅诸吏光禄大夫关内侯王崇为安成侯」，又「赐舅王谭、商、立、根、逢时爵关内侯」；《元后传》叙安成侯崇「后五年」薨，其明年即河平二年，故《传》于封五侯之上明书「明年，河平二年」。", "process": "前27年（河平二年）。《汉书·成帝纪》：「夏六月，封舅谭、商、立、根、逢时皆为列侯。」《元后传》：「明年，河平二年，上悉封舅谭为平阿侯，商成都侯，立红阳侯，根曲阳侯，逢时高平侯。五人同日封，故世谓之『五侯』。」又「王氏子弟皆卿、大夫、侍中、诸曹，分据势官满朝廷。大将军凤用事，上遂谦让无所颛」。其后百姓歌之曰：「五侯初起，曲阳最怒，坏决高都，连竟外杜，土山渐台西白虎。」", "impact": "大司马一人之权至是分于五宗，是外戚由辅政变为据势的转折点；「上遂谦让无所颛」一句为《传》自著其故，与《纪》之但书封爵相对。后二年有河平四年单于入朝（见 cn--b25--p01），后三年有乐昌侯商免相、京兆尹王章死狱（见 cn--b24--p01、cn--b24--p02），五侯并封是这一段外家之局的第一著。", "figures": ["王谭", "王商", "王立", "王根", "王逢时", "王凤", "王崇"], "place": "长安（今陕西西安）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·元后传》"], "tags": ["五侯", "外戚分封", "清议"]}, "related": ["cn--b33--p01", "cn--b24--p02"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷九十八元后传）", "at": "2026-11-07", "note": "本条系年之据最坚：《纪》书「河平二年」夏六月，《传》明言「明年，河平二年」，两文相合；封爵之月《纪》在夏六月，《传》但言「明年，河平二年」不系月，本条从《纪》。《传》「商成都侯」与丞相乐昌侯王商同名，二人事迹分在《元后传》《王商传》，本条之商定指成都侯；王章事别在阳朔元年条。歌辞「土山渐台西白虎」之「西」，《传》无训，本站不改为「似」。◆ 本次回改：impact 旧作「明年有河平四年单于入朝」「又明年有乐昌侯商罢相」，检所引 cn--b25--p01 在河平四年（前25）、cn--b24--p01/cn--b24--p02 在阳朔元年（前24），自本条前27推之各为后二年、后三年，故改「明年／又明年」为「后二年／后三年」；「罢相」从《表》作「免相」。"}]},
  {"id": "cn--b26--c01", "track": "cn", "year": -26, "yearApprox": false, "dim": "culture", "weight": 3, "title": "刘向撰新序说苑", "summary": "采传记行事，以类相从，成劝诫之书。", "detail": {"background": "成帝时外戚盛、宴乐多，刘向以宗室老儒典校秘书，屡上书言灾异与王氏之渐，言不见用。", "process": "约前26年前后，向辑先秦以来传记行事，删取指意，成《新序》《说苑》数十篇，又奏《列女传》八篇以戒后庭与近习；其书以类相从，篇终系以君子曰。", "impact": "这是中国最早的劝诫类书编纂：把儒术从章句转成可征引的政治伦理语汇，其体例直接影响《白虎通》与后世类书；文风由铺陈之赋转为议论之文，也是汉散文过渡的一环。", "figures": ["刘向"], "place": "长安", "state": "西汉", "sources": ["《汉书·楚元王传》", "《说苑》", "《七略》辑校"], "tags": ["新序说苑", "劝诫之文", "类书"]}, "related": ["cn--b26--i01", "cn--b24--p02"]},
  {"id": "cn--b26--i01", "track": "cn", "year": -26, "yearApprox": false, "dim": "institution", "weight": 4, "title": "诏诸儒校禁中秘书", "summary": "河平三年刘向等分门校书，条其篇目而奏之。", "detail": {"background": "河平三年（前26）以禁中秘书多残亡散逸、简编脱乱，诏光禄大夫刘向与谒者、乘舆书吏共校之。", "process": "刘向校经传诸子诗赋，步兵校尉任宏校兵书，太史令尹咸校数术，侍医李柱国校方技；每一书已，向辄条其篇目、撮其指意，录而奏之；向卒，哀帝复令其子刘歆卒父业，遂据以成《七略》。", "impact": "中国的目录学与校勘学由此诞生：一人成书则一篇叙录的体例为后世四库提要所承，所校之本与部次即成《汉书·艺文志》的骨架；先秦典籍之多得传于今，全赖此役。", "figures": ["刘向", "刘歆", "任宏"], "place": "长安未央宫禁中", "state": "西汉", "sources": ["《汉书·艺文志》", "《汉书·楚元王传》"], "tags": ["校书", "目录学", "七略"]}, "related": ["cn--b26--c01", "cn--b51--c01", "cn--b6--c01"]},
  {"id": "cn--b25--p01", "track": "cn", "year": -25, "yearApprox": false, "dim": "politics", "weight": 3, "title": "河平四年单于入朝，叹此真汉相矣", "summary": "正月匈奴单于来朝，二月罢归国，赐它如竟宁时；单于仰视丞相商貌，大畏之，迁延却退。", "detail": {"background": "呼韩邪三朝于甘泉、长安（见 cn--b51--p02、cn--b49--p01），复株絫若鞮立后遣子入侍、河平元年奉献，其明年单于上书愿朝。时乐昌侯王商为丞相（见 cn--b24--p01）。", "process": "前25年（河平四年）。《汉书·成帝纪》：「四年春正月，匈奴单于来朝。」「二月，单于罢归国。」《匈奴传下》：「单于上书愿朝」「遂入朝，加赐锦绣缯帛二万匹，絮二万斤，它如竟宁时」。《王商传》：「河平四年，单于来朝，引见白虎殿。丞相商坐未央廷中，单于前，拜谒商。商起，离席与言，单于仰视商貌，大畏之，迁延却退。天子闻而叹曰：『此真汉相矣！』」", "impact": "竟宁之礼以客处单于，至是「它如竟宁时」一句定为成例，自甘露至河平三十年之藩礼不烦更议而可复。丞相与单于相见于廷，拜谒与离席之节《传》各书其一端，此汉家以貌为相之说所由起；而商之见美壮由固守之议（见 cn--b30--d01），其罢相以闺门之事（见 cn--b24--p01），前后相望，外戚与丞相之分最明。", "figures": ["复株絫若鞮单于", "王商", "成帝刘骜"], "place": "长安白虎殿、未央廷（今陕西西安）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·王商传》", "《汉书·匈奴传下》"], "tags": ["单于入朝", "它如竟宁时", "此真汉相矣"]}, "related": ["cn--b51--p02", "cn--b28--x01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷九十四下匈奴传下）", "at": "2026-11-07", "note": "三处所书详略不同：《纪》书正月来朝、二月罢归，《王商传》但云「河平四年，单于来朝」，《匈奴传》则叙「单于上书愿朝」于河平元年奉献之下；上书之岁与入朝之岁相隔，《纪》《传》不相犯，本条定入朝于本年。引见白虎殿与「丞相商坐未央廷中」两殿名，《传》自为文，《纪》不书殿；本条并著两所而不言其为同处。加赐之物《传》书锦绣缯帛二万匹、絮二万斤，《纪》不书赐数，故本条于赐物只取《传》。"}]},
  {"id": "cn--b25--d01", "track": "cn", "year": -25, "yearApprox": false, "dim": "disaster", "weight": 2, "title": "长陵临泾岸崩，山阳火生石中", "summary": "三月朔日蚀，遣博士嘉等十一人循行濒河之郡振贷；壬申长陵临泾岸崩雍泾水，以山阳火改元阳朔。", "detail": {"background": "自建始四年河决，六岁之间振贷之使始及濒河之郡；长陵为高祖陵，临泾者陵旁之邑。", "process": "前25年（河平四年）。《汉书·成帝纪》：「三月癸丑朔，日有蚀之。遣光禄大夫博士嘉等十一人行举濒河之郡水所毁伤困乏不能自存者，财振贷。」又「其为水所流压死，不能自葬，令郡国给槥椟葬埋。已葬者与钱，人二千」。「壬申，长陵临泾岸崩，雍泾水。」夏六月庚戌「楚王嚣薨」。又书「山阳火生石中，改元为阳朔」。", "impact": "改元两例在五年之间并见：河平以堤塞之功，阳朔以火生石中之异，一喜一惧皆足以易号。振贷之使以十一人为一队，是《成帝纪》所见循行赈给之最大人数，而其目在水所毁伤，则前岁河决之余害至是未尽。岸崩而雍泾水，《纪》以系日（壬申），与改元之文不相及。", "figures": ["成帝刘骜", "嘉", "楚王嚣"], "place": "长安、长陵临泾（今陕西西安、咸阳）", "state": "西汉", "sources": ["《汉书·成帝纪》"], "tags": ["岸崩", "振贷", "改元阳朔"]}, "related": ["cn--b29--d01", "cn--b24--p02"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪）", "at": "2026-11-07", "note": "「博士嘉等十一人」，《纪》但书名「嘉」而不著其姓与它属，本站不为之补。「山阳火生石中」，《纪》不书月（在夏六月庚戌楚王嚣薨之下），山阳之地望（为郡为县、在兖在河内）《纪》无注，本条故不注今地；亦不以河平四年尽属阳朔——《纪》书改元于其岁之末，明年乃为阳朔元年，此《纪》例也。「雍泾水」之「雍」，《纪》作拥塞义，本条照录其字。"}]},
  {"id": "cn--b24--p01", "track": "cn", "year": -24, "yearApprox": false, "dim": "politics", "weight": 3, "title": "乐昌侯王商免相三日，发病呕血薨", "summary": "因日蚀张匡上书，左将军丹等奏之；诏赦其罪而使者收丞相印绶，免相三日呕血薨，谥曰戾侯。", "detail": {"background": "商以建始三年止讹言之议为帝所美壮（见 cn--b30--d01），明年代匡衡为丞相；大司马凤怨其不附己，「阴求其短」。", "process": "前24年（阳朔元年）。《汉书·王商传》：「凤重以是怨商，阴求其短，使人上书言商闺门内事。」「会日有蚀之」，太中大夫蜀郡张匡「上书愿对近臣陈日蚀咎」，其言曰「商视事五年，官职陵夷而大恶著于百姓」；于是左将军丹等奏「执左道以乱政，为臣不忠」。上素重商，「知匡言多险」，制曰「勿治」；凤固争之，于是制诏御史：「今乐昌侯商为丞相，出入五年，未闻忠言嘉谋，而有不忠执左道之辜，陷于大辟。」「其赦商罪。使者收丞相印绶。」「商免相三日，发病呕血薨，谥曰戾侯。」「有诏长子安嗣爵为乐昌侯。」又《传》：「商死后，连年日蚀、地震，直臣京兆尹王章上封事」「讼商忠直无罪，言凤颛权蔽主。凤竟以法诛章」。", "impact": "丞相以闺门之事罢、罢三日而死，而制诏仍曰「赦商罪」——罪不定罪而身已死，是外戚倾宰相的最省手之法；「谥曰戾侯」四字则其不受赦之名。《传》于此书长子安嗣爵，侯国不除，与后来乐昌侯安以罪自杀、国除为一条线。商死未几王章以讼商死（见 cn--b24--p02），则帝之感寤纳之在其身后。", "figures": ["王商", "王凤", "张匡", "王章"], "place": "长安（今陕西西安）", "state": "西汉", "sources": ["《汉书·王商传》", "《汉书·元后传》", "《汉书·成帝纪》"], "tags": ["外戚内争", "丞相", "谥戾侯"]}, "related": ["cn--b30--d01", "cn--b24--p02"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷八十王商传）", "at": "2026-11-07", "note": "本条之系年非《传》之明文：《王商传》不书免相之岁，《成帝纪》河平四年至阳朔二年亦不书丞相商罢，故但据「商视事五年」（《传》张匡语）、「出入五年」（制诏语）与其先「明年，商代匡衡为丞相」（在建始四年之后）推之；又《传》明言「商死后」「凤竟以法诛章」，《纪》书王章下狱死在阳朔元年冬，则商之死必不晚于阳朔元年，与「五年」合，故定为本年；《百官公卿表》之异文本站未及取校，故此系年存为可议。商之侯号两《传》同指：《王商传》制诏曰「今乐昌侯商为丞相」，故定其为乐昌，与五侯中之成都侯商自是二人。「左将军丹」，《传》不系其氏，本条照录官号不补姓名。"}]},
  {"id": "cn--b24--p02", "track": "cn", "year": -24, "yearApprox": false, "dim": "politics", "weight": 4, "title": "王章以日蚀封事言凤不可令久典事", "summary": "帝感寤纳之，使试为朕求可以自辅者；凤称病，上优诏起之，章遂死狱中，妻子徙合浦。", "detail": {"background": "自河平以来日蚀、地震数至（见 cn--b30--p01、cn--b25--d01）；乐昌侯商之死在其前（见 cn--b24--p01）。京兆尹王章素刚直敢言。", "process": "前24年（阳朔元年）。《汉书·成帝纪》：「冬，京兆尹王章有罪，下狱死。」《元后传》载其始末：章以凤建遣定陶共王之国为非是，「乃奏封事言日蚀之咎矣」，对帝言「天道聪明，佑善而灾恶，以瑞异为符效」，「灾异之发，为大臣颛政者也」「今政事大小皆自凤出，天子曾不一举手」，又引「其人守正，不肯诎节随凤委曲，卒用闺门之事为凤所罢，身以忧死，众庶愍之」，断之曰「凤不可令久典事，宜退使就第，选忠贤以代之」；帝谓章曰「微京兆尹直言，吾不闻社稷计！且唯贤知贤，君试为朕求可以自辅者」，章遂荐琅邪太守冯野王。其后凤称病笃，帝优诏留之，「上使尚书劾奏章」「遂下章吏」「廷尉致其大逆罪」，「章死狱中，妻子徙合浦。」「自是公卿见凤，侧目而视，郡国守相、刺吏皆出其门。」", "impact": "章之一言几代凤：所荐冯野王声誉出凤远甚，帝方倚之以代凤，而凤以张美人之事自解，终以「非所宜言」杀章。《纪》但书「有罪，下狱死」，《传》具见其所以死在一夕之语；后四年（阳朔三年秋）王凤薨（语在《元后传》），而「侧目而视」之局已成，外家自此无可触。", "figures": ["王章", "王凤", "冯野王", "成帝刘骜", "王商"], "place": "长安、合浦（今陕西西安、广西合浦）", "state": "西汉", "sources": ["《汉书·成帝纪》", "《汉书·元后传》"], "tags": ["王章之狱", "言路", "灾异"]}, "related": ["cn--b24--p01", "cn--b27--p01"], "checks": [{"by": "本站·维基文库比对（《汉书》卷十成帝纪、卷九十八元后传）", "at": "2026-11-07", "note": "《纪》书王章之死在阳朔元年冬，故本条定年为前24年；《传》之叙事系于商死、凤病、野王之荐之后，其本末与《纪》系年有未合者，《传》不以年月为次故也，本条一从《纪》。《传》叙事不以年月为次，其中定陶共王朝、留、遣之节各有岁月，《纪》《传》多不相值，本条但据《纪》定章死之年，其间问答先后一依《传》之叙次，不作日月之定。「羌胡尚杀首子以荡肠正世」出《传》所记章对，是章以边俗讥凤之内弟御至尊，本条存其辞而不及其事之信否。"}]},
  {"id": "cn--b18--p01", "track": "cn", "year": -18, "yearApprox": false, "dim": "politics", "weight": 2, "title": "谷永数上疏言外家之祸", "summary": "以灾异推外戚，辞切而身附王氏，言不见用。", "detail": {"background": "成帝无嗣而好燕乐，赵飞燕、李氏姊妹贵震后宫，外家王氏专政于朝，丁、傅继起于外，灾异连年不绝。", "process": "元延、绥和之间（约前12至前7年），谷永数上疏言帝王宜省声色、广继嗣、远外家，辞指甚切；然其所以屡得进言，实由王氏所引，故所言王章、许班之党，议者非之。", "impact": "以灾异说政已沦为外戚与幸臣互相攻讦的工具：谷永言外家之祸而身出外家之门，这种错位说明经学谏诤已失其独立位置，士人乃渐转趋图谶与禅让之说。", "figures": ["谷永", "刘骜"], "place": "长安及三辅", "state": "西汉", "sources": ["《汉书·薛宣传》", "《汉书·百官公卿表》"], "tags": ["循吏", "条教", "文牍治理"]}, "related": ["cn--b64--p01", "cn--b58--i01"]},
  {"id": "cn--b15--p01", "track": "cn", "year": -15, "yearApprox": false, "dim": "politics", "weight": 3, "title": "薛宣为丞相条奏吏治", "summary": "以能吏居相位，条郡国便宜，务在举贤省事。", "detail": {"background": "永始以来郡国以督责为治，民多轻犯法而吏缘为奸；薛宣以治行累迁左冯翊、御史大夫，遂代为丞相。", "process": "永始二年（前15）薛宣代翟方进为丞相，封高阳侯；条奏郡国吏治不便者数事，务在举贤、省事、薄刑、劝农，以二千石为纲纪，责属县以条教课最，而不得苛扰。", "impact": "循吏政治至此已成一种文牍化的技术治理：条教、课最、簿书相循，能息一时之狱讼而不能抑兼并；宣旋以广汉太守奏免，能吏之不相容于权门，亦可见汉制之穷。", "figures": ["薛宣", "刘骜"], "place": "长安及郡国", "state": "西汉", "sources": ["《汉书·薛宣传》", "《汉书·百官公卿表》"], "tags": ["灾异", "外戚", "谏诤之困"]}, "related": ["cn--b24--p02", "cn--b6--c01"]},
  {"id": "cn--b15--p02", "track": "cn", "year": -15, "yearApprox": false, "dim": "politics", "weight": 3, "title": "翟方进以灾异策免自杀", "summary": "荧惑守心，郎官言其咎在丞相，即日自杀。", "detail": {"background": "成帝以来灾异连属，日蚀、地震、荧惑守心之占相接，议者多以王氏应之；故事三公每以灾异策免，而荧惑之占尤为切至。", "process": "永始二年（前15）十二月荧惑守心，郎官行秘者言其变宜应在大臣，有司奏丞相翟方进奉职不谨、议明圣之术不实，策免相位，赐黄金百斤、酒脯；方进即日自杀。", "impact": "以经学吏业致位丞相而以灾异死其位，说明灾异课三公已成朝中无人敢否定的制度；此后师丹、孔光、王莽皆以灾异与符命进退，相位成了权门与天命之间的缓冲。", "figures": ["翟方进", "刘骜"], "place": "长安", "state": "西汉", "sources": ["《汉书·翟方进传》", "《汉书·天文志》"], "tags": ["灾异", "策免", "三公"]}, "related": ["cn--b15--p01", "cn--b6--c01"]},
  {"id": "cn--b7--i01", "track": "cn", "year": -7, "yearApprox": false, "dim": "institution", "weight": 3, "title": "师丹请限田限奴婢", "summary": "诏诸侯王列侯吏民名田各以顷亩为限，议竟寝。", "detail": {"background": "哀帝初即位，外家丁、傅新贵，关东流民与奴婢市贩之盛百倍于武帝之末；大司空师丹在位，以为非抑兼并无以安民。", "process": "绥和二年（前7）师丹与丞相孔光奏请：诸侯王、列侯、关内侯、吏民名田皆毋得过三十顷，诸侯王奴婢毋过二百人，列侯、公主百人，关内侯、吏民三十人，期尽三年，犯者没入官；诏书已下，而丁、傅、故贵之家不便，遂寝。", "impact": "这是中国古代第一次由中央明令限制土地与奴婢的占有量，也是王莽王田之令的直接前例；其失败表明在豪族与外戚并起的结构里，限田之法终无从执行。", "figures": ["师丹", "刘欣"], "place": "长安", "state": "西汉", "sources": ["《汉书·食货志》", "《汉书·师丹传》", "《资治通鉴·汉纪》"], "tags": ["限田议", "奴婢", "师丹"]}, "related": []},
  {"id": "cn--b6--c01", "track": "cn", "year": -6, "yearApprox": false, "dim": "culture", "weight": 3, "title": "刘歆请立古文经博士", "summary": "移让太常博士，争立毛诗逸礼古文。", "detail": {"background": "刘歆校秘书，见《左氏春秋》、《毛诗》、《逸礼》、《古文尚书》皆在秘府，以为此皆丘明、孔氏之旧文；时博士专守今文家法。", "process": "约前6年前后，歆移书让太常博士，请为《左氏春秋》、《毛诗》、《逸礼》、《古文尚书》更置博士；诸博士以为非先君所立，不可复加，朝臣多非歆者，歆惧出，为河内五官太守。", "impact": "今古文之争自此公开化，经学由家法之学转为文献与义理之争；古文经学所携的周官、明堂、井田之说随之入世，为王莽摄政提供了制度蓝本与经典依据。", "figures": ["刘歆"], "place": "长安", "state": "西汉", "sources": ["《汉书·楚元王传》", "《汉书·刘歆传》", "《汉书·艺文志》"], "tags": ["古文经", "今古文之争", "博士"]}, "related": ["cn--b26--i01"]},
  {"id": "cn--b6--e01", "track": "cn", "year": -6, "yearApprox": false, "dim": "economy", "weight": 3, "title": "五铢钱与市易之盛", "summary": "天下效五铢，郡国铸钱者多，谷贱钱重。", "detail": {"background": "自元鼎行上林三官五铢以来，钱之重重大小如一，私铸稍息；至成哀之间，谷贱钱少之议与珠金银玉之积并起。", "process": "约前6年前后，谷贱伤农、钱少不足用，议者或请更铸大钱以实边用；同时京师贵戚与贾竖以钱为市，长安、洛阳的市肆、赊贷之业并起，民赋与奴婢之价皆以钱计。", "impact": "货币化已把汉代社会推到以钱计物、以钱计税的地步：钱重则谷贱伤农，钱轻则奸铸复起，这一两难至王莽货币改革而彻底爆发，成为新室速亡的原因之一。", "figures": ["刘欣"], "place": "长安及郡国", "state": "西汉", "sources": ["《汉书·食货志》", "《盐铁论》", "西汉五铢钱范"], "tags": ["五铢钱", "钱谷轻重", "市易"]}, "related": ["cn--b113--e01"]},
  {"id": "cn--b2--p01", "track": "cn", "year": -2, "yearApprox": false, "dim": "politics", "weight": 3, "title": "董贤断袖与哀帝之宠", "summary": "宠臣董贤年二十二位至三公，帝欲禅之。", "detail": {"background": "哀帝倦怠政事，宠爱幸臣董贤，出则参乘、入则御坐，欲以顾命辅政；其时外家丁、傅已替，王氏退处里第。", "process": "约前2年至前1年，董贤年二十二由黄门郎迁至大司马，封高安侯，赏赐以亿计，为起第于长安，将作大匠亲治其居，武库禁兵、尚方珍器皆入董氏；帝且欲以玺绶属之。", "impact": "以幸臣取代外戚、以私宠压制公论，等于同时开罪所有既得集团；故哀帝崩之日王莽即日收捕丁、傅，并召还王氏，董贤与妻当日自杀，家财薄计四万余万入于县官。", "figures": ["董贤", "刘欣", "王莽"], "place": "长安", "state": "西汉", "sources": ["《汉书·佞幸传》", "《汉书·王莽传》", "《资治通鉴·汉纪》"], "tags": ["董贤", "幸臣", "外戚代兴"]}, "related": ["cn--b1--p01"]},
  {"id": "cn--b1--p01", "track": "cn", "year": -1, "yearApprox": false, "dim": "politics", "weight": 3, "title": "王莽就封新都安汉公", "summary": "退处数岁复起，以大司马领尚书事还朝。", "detail": {"background": "成帝崩，莽以王太后（政君）侄为大司马，旋为哀帝外家丁、傅所黜，就第于新都；一时朝臣多为言其冤。", "process": "前1年至前1年之间，莽就新都侯国，杜门自守；元寿元年（前2）日蚀，朝臣举莽与孔光，征还，拜为大司马，尊号曰安汉公（居摄以前）；太后临朝，政归禁中。", "impact": "一次退让反而成就了道德资本，这是西汉末政治的奇异逻辑；莽以礼法、节俭、让爵为具，得士人之望而居权位，外戚由专权转为篡代的准备已近完成。", "figures": ["王莽", "刘欣", "孔光"], "place": "长安及新都（今河南南阳一带）", "state": "西汉", "sources": ["《汉书·王莽传》", "《资治通鉴·汉纪》"], "tags": ["王莽", "安汉公", "外戚"]}, "related": ["cn--b2--p01"]},
  {"id": "cn--1--p02", "track": "cn", "year": 1, "yearApprox": false, "dim": "politics", "weight": 2, "title": "元始之际符命与四夷称臣", "summary": "以瑞命边功累加上尊号，改制之议渐成。", "detail": {"background": "自王莽领尚书事，黄支、苏来摩之类远物与瑞命日陈于廷，边遣使说乌孙、匈奴，使咸上寿称臣，以成中兴与受命之象。", "process": "元始初，益州塞外种人献犀象、大雀，匈奴单于上书言莽功德、愿无得报，西域诸国并侍子于长安；有司据瑞应、符命奏上安汉公之号，又请以元始纪年、定明堂、辟雍、经学之制。", "impact": "符命与瑞应以中央的名义被批量制造出来：纪年、尊号、边功与礼制合成一套合法性话语，此后的禅代与告命皆沿此程序，王莽是把它第一次做得完整的人。", "figures": ["王莽", "刘衎"], "place": "长安", "state": "西汉", "sources": ["《汉书·王莽传》", "《汉书·地理志》"], "tags": ["符命", "尊号", "瑞应"]}, "related": []},
  {"id": "cn--2--i01", "track": "cn", "year": 2, "yearApprox": false, "dim": "institution", "weight": 2, "title": "元始间起明堂辟雍", "summary": "于南郊立明堂、辟雍，三雍之制始备。", "detail": {"background": "自武帝以来议明堂不一，元帝、王莽之际儒者据《周官》《王制》之说，欲以三雍为受命改正之具。", "process": "元始二年前后，莽奏起明堂、辟雍、灵台于长安南郊，为学者筑舍万区，定昏礼、乡射之仪；太常、博士与诸生会课于辟雍之中，简阅大合于明堂之上。", "impact": "三雍自此成为帝国最高礼制与教育的空间型式，洛阳东汉承之，其影响直至魏晋南北朝；同时它把经学中的周制想象第一次变成实际的都城规划。", "figures": ["王莽", "刘衎"], "place": "长安南郊", "state": "西汉", "sources": ["《汉书·王莽传》", "《三辅黄图》", "汉长安城南郊遗址发掘"], "tags": ["明堂辟雍", "礼制建设", "周官之学"]}, "related": ["cn--5--c01", "cn--9--i01"]},
  {"id": "cn--5--p01", "track": "cn", "year": 5, "yearApprox": false, "dim": "politics", "weight": 3, "title": "元后崩与王莽加九锡", "summary": "王政君死，葬合渭陵；莽受九锡，位在三公上。", "detail": {"background": "元始五年莽妻以女为后，其姑王政君年八十九而崩；孝宣后与元后之间，王氏之权尽归莽。", "process": "5年二月王政君崩，与元帝合葬渭陵，莽亲执丧事，调发四辅、三公、郡国材料，起坟甚高；其年莽加九锡，衣服、车骑、宫卫拟于天子，与太皇太后共定策。", "impact": "葬礼之奢是政治信号的公开化：王氏与汉室在礼制上已无差等；一年之后代汉之局，正是在这种仪注与符命相累积的过程中被完成的。", "figures": ["王莽", "王政君"], "place": "长安及渭陵", "state": "西汉", "sources": ["《汉书·元后传》", "《汉书·王莽传》"], "tags": ["元后之葬", "九锡", "礼制逾等"]}, "related": ["cn--b1--p01", "cn--9--p01"]},
  {"id": "cn--5--c01", "track": "cn", "year": 5, "yearApprox": false, "dim": "culture", "weight": 4, "title": "元始五年诸生会集考论", "summary": "征天下通一经及逸礼古书者数千人，会集阙下。", "detail": {"background": "莽欲以周官、礼经为改制张本，征通逸礼、古书、毛诗、周官、尔雅、天文、律历、谶记、小学者至京师。", "process": "5年诏征天下学者凡数千人，各以同类集于阙下记说，刘歆主其事；以《周官》得见经传之助，卒立《周官》之经，莽据之以定井田、五均、爵制、封域之说。", "impact": "这是经学与政治合流的关键一步：出土文献与古文经被直接编成改制的法律，其后果不仅是经学之争，更使国家制度的蓝本第一次完整取自经典文本，而代价是失败的改革。", "figures": ["刘歆", "王莽"], "place": "长安", "state": "西汉", "sources": ["《汉书·刘歆传》", "《汉书·王莽传》", "《周礼》"], "tags": ["周官", "征集群儒", "以经改制"]}, "related": ["cn--b6--c01", "cn--9--i01", "cn--9--i02"]},
  {"id": "cn--6--p01", "track": "cn", "year": 6, "yearApprox": false, "dim": "politics", "weight": 3, "title": "居摄践祚与孺子之立", "summary": "莽摄皇帝位，改元居摄，欲代汉自明。", "detail": {"background": "帝崩无嗣，择宣帝玄孙婴年二岁立之，号孺子；莽以太后诏居摄，如周公故事，而自名其年曰居摄。", "process": "6年莽即天子位、南面朝诸侯，以子安汉公之礼自处，称摄皇帝；改居摄元年，建明堂、行宗祀，以《周书》王若曰之文为据；刘歆、王舜等共定其仪，有司奏言莽宜如周公。", "impact": "居摄是汉代政治语言中最露骨的一次周公模仿：它把摄政合法化到称帝的最后一步，但也激起翟义起兵与宗室之怨，使此后两年间朝野共识由赞成摄政变成反对代汉。", "figures": ["王莽", "刘婴"], "place": "长安", "state": "西汉", "sources": ["《汉书·王莽传》", "《资治通鉴·汉纪》"], "tags": ["居摄", "孺子", "周公之喻"]}, "related": ["cn--5--p01", "cn--7--m01"]},
  {"id": "cn--7--m01", "track": "cn", "year": 7, "yearApprox": false, "dim": "military", "weight": 4, "title": "翟义起兵与东方三郡响应", "summary": "东郡太守翟义举兵，众十余万，旋败死。", "detail": {"background": "莽居摄，宗室与郡县多不服；东郡太守翟义为故丞相翟方进少子，与严尤、霍宣等结谋，以讨莽为名。", "process": "7年九月翟义起于东郡，移檄东郡、淮阳、汝南之兵众十余万，三辅之民数千人响应；莽效《周书·大诰》作书自解，遣王邑等将兵东征，义败死，其党尽族，独刘歆、孔光不以为罪。", "impact": "这次兵变使王莽对郡县豪吏失去信任，转向以符命、酷吏与频繁改制来重建控制；同时它也是汉室最后的官方勤王尝试，此后讨莽的旗帜便从士大夫转移到饥民与铜马之众。", "figures": ["翟义", "王莽", "王邑"], "place": "东郡及三辅", "state": "西汉", "sources": ["《汉书·翟方进传》", "《汉书·王莽传》"], "tags": ["翟义起兵", "居摄危机", "郡县豪吏"]}, "related": ["cn--b15--p02", "cn--6--p01", "cn--9--p01"]},
  {"id": "cn--9--p01", "track": "cn", "year": 9, "yearApprox": false, "dim": "politics", "weight": 5, "title": "王莽即真定国号曰新", "summary": "受孺子之禅，定有天下之号曰新，改元始建国。", "detail": {"background": "居摄三年符命大起，白石丹书、金匮图谶出于延陵、扶风；莽以天命、人心与图纬之说即真。", "process": "9年正月莽拜祠高庙，授孺子玺绶，以戊子代甲子，定国号曰新，改元始建国，降汉帝为定安公，以女妻之；追谥黄帝、舜为始祖，以周、齐之后为二王后，尽易汉家制度、官名、服色。", "impact": "新室代汉是中国历史上第一次以符命、禅让与经典制度蓝本三结合的政权更替；它以和平方式取得正统，却因改制过密、名实交丧，十五年间便使天下瓦解，遂成此后禅代最被反复讨论的先例。", "figures": ["王莽", "刘婴"], "place": "长安", "state": "新", "sources": ["《汉书·王莽传》", "《资治通鉴·汉纪》"], "tags": ["新莽代汉", "符命", "始建国"]}, "related": ["cn--7--m01", "cn--9--i01", "cn--23--p01"]},
  {"id": "cn--9--i01", "track": "cn", "year": 9, "yearApprox": false, "dim": "institution", "weight": 5, "title": "王田令禁买卖奴婢", "summary": "更名天下田曰王田，奴婢曰私属，皆不得卖买。", "detail": {"background": "汉末豪强兼并不止，贫民卖子为奴婢，朝廷不能禁；莽据《周官》井田之说，欲以复古之法为天下齐民。", "process": "9年下诏：更名天下田曰王田，一家男丁不满八口而田过一井者，以余田授九族乡党；天下奴婢皆曰私属，不得卖买；犯者投诸四裔，以御魑魅；行之五年而民不便，至12年遂罢王田、奴婢之禁，得卖如故。", "impact": "这是中国历史上唯一一次以恢复井田为名的全国土地国有令；其法虽止行三年而废，却定下此后一千八百年关于土地与奴婢的根本争论，也使新室永远失去了地主与商人的支持。", "figures": ["王莽"], "place": "长安及天下郡县", "state": "新", "sources": ["《汉书·王莽传》", "《汉书·食货志》"], "tags": ["王田", "私属", "土地国有"]}, "related": ["cn--b7--i01", "cn--9--i02", "cn--17--p01"]},
  {"id": "cn--9--i02", "track": "cn", "year": 9, "yearApprox": false, "dim": "institution", "weight": 4, "title": "五均六筦官市赊贷", "summary": "于六郡立五均官，统酒、盐、铁、铸钱与名山大泽。", "detail": {"background": "汉世富商大贾以逐利相高，平准、均输之法自成帝、哀帝以后渐弛；王莽欲以官市齐物价、抑兼并，而府库之入仰于此。", "process": "9年诏长安及洛阳、邯郸、临淄、宛、成都立五均司市、钱府官：以每月物价上中下三等平之，民欲卖者官为收，欲买者贱则取之；又设赊贷，贫民欲得赊钱者以月息三十取一；兼行酒、盐、铁、铸钱、名山大泽之征，是谓六筦。", "impact": "王莽把财政从税赋改造为经营，这是古代中国最大胆的官营市场实验；其法以能吏与计簿为命脉，吏缘为奸，徒为烦扰，反使农商俱废，故史称农商失业、食货俱废。", "figures": ["王莽", "桑弘羊遗法"], "place": "长安及五都市", "state": "新", "sources": ["《汉书·食货志》", "《汉书·王莽传》"], "tags": ["五均六筦", "官市赊贷", "市场管制"]}, "related": ["cn--9--i01", "cn--9--e01", "cn--17--p01"]},
  {"id": "cn--9--e01", "track": "cn", "year": 9, "yearApprox": false, "dim": "economy", "weight": 4, "title": "宝货制与刀布之复", "summary": "更黄金曰黄石，作龟宝、布货十品之目。", "detail": {"background": "汉专用五铢钱，民间便之，七十一场不变；王莽以古者货贝、刀布之文为据，欲以繁复的货币等级收民之藏而别其轻重。", "process": "9年废五铢而行宝货：黄金重一斤直万钱，朱、白、苍黄、赤墀凡五物；银为二品；铜贝三十品，大、壮、中、小、幼凡五品；又作小直千、中直五百、幺中三百、壮百、小五十凡五十八品；民以为不便，私用五铢，遂禁天下不得挟钱，铸钱者罪至死。", "impact": "货币由繁而乱、由乱而废：一、二十余年间四次改币，币值与重量不符、名号繁不可晓，百姓两为奸巧，农商失业；新莽的货币试验成为中国货币史上最著名的失败案例。", "figures": ["王莽"], "place": "长安及郡国", "state": "新", "sources": ["《汉书·食货志》", "《汉书·王莽传》", "新莽货币实物"], "tags": ["宝货制", "刀布", "币制紊乱"]}, "related": ["cn--9--i02", "cn--b6--e01", "cn--14--e01"]},
  {"id": "cn--10--i01", "track": "cn", "year": 10, "yearApprox": false, "dim": "institution", "weight": 3, "title": "改官名与五等爵", "summary": "大司农羲和、水衡虞衡，尽易汉家百官之名。", "detail": {"background": "莽以《周官》《王制》之文为据，欲使官称与古制相合；于是府、寺、卿、大夫之名一变于天下。", "process": "10年置四辅、四将、九卿、二十七大夫、八十一元士，以大司农羲和、少府共己、水衡虞衡、太仆趣马名官；郡太守曰大尹、都尉曰太尉，县令长分五等，爵曰公侯伯子男；五等之封行于贵近，而吏民苦其簿书。", "impact": "名称与印绶的大改使郡县文书、仓卒驿传一时皆乱，官制在复古的名义下反而失去可执行性；此等制度虚转，是新室政令不行于天下的直接原因之一。", "figures": ["王莽"], "place": "长安及郡国", "state": "新", "sources": ["《汉书·百官公卿表》", "《汉书·王莽传》"], "tags": ["官名复古", "五等爵", "文书之乱"]}, "related": ["cn--9--p01", "cn--9--i01"]},
  {"id": "cn--11--x01", "track": "cn", "year": 11, "yearApprox": false, "dim": "explore", "weight": 3, "title": "易匈奴名与征高句丽", "summary": "分匈奴为十五单于，改高句丽为王下，边患遂起。", "detail": {"background": "莽以四夷称臣为义，不能容单于与汉敌体之旧；又以乌孙、匈奴和亲之号多易，欲以名分制之。", "process": "11年使五威将王骏等至匈奴，以新室印绶易汉故玺，改匈奴为降奴服于，又分其国地、立呼韩邪子孙十五人俱为单于；发高句丽兵击匈奴，候擅令改其王为下，其众遂亡塞外，与辽东兵相杀。", "impact": "名分之争在北方成了实际的挑衅：自是匈奴数入边，并护乌桓、羌胡，北边自云中至辽东数千里萧然，士民转徙；新室之亡，实自边祸启之。", "figures": ["王莽", "王骏"], "place": "长安及匈奴、高句丽", "state": "新", "sources": ["《汉书·匈奴传》", "《汉书·王莽传》", "《汉书·地理志》"], "tags": ["名分外交", "北边之患", "高句丽"]}, "related": ["cn--1--p02", "cn--b33--p02", "cn--b47--x01"]},
  {"id": "cn--12--i01", "track": "cn", "year": 12, "yearApprox": false, "dim": "institution", "weight": 2, "title": "禁挟五铢与废王田令", "summary": "民私用五铢钱，罪至徙；王田、奴婢之禁亦弛。", "detail": {"background": "宝货既行而民间不用，五铢久便而法令严禁；王田之令又使卖买相冒、吏不能禁，改制之政已自屈于俗。", "process": "12年以民不便，诏废王田、奴婢之禁，得卖买如故；惟下吏民不得私挟五铢、黄金，违者以罪罪之，公卿以下至吏民坐铸钱、挟钱抵罪者甚众。", "impact": "三年之内，井田之说废、挟钱之禁令行，改制由复古的理想退为财政的搜括；新室自此失去士人与富民的支持，而苛法与转输之役并至，天下遂乱。", "figures": ["王莽"], "place": "长安及郡国", "state": "新", "sources": ["《汉书·食货志》", "《汉书·王莽传》"], "tags": ["废王田", "挟钱之禁", "政策退却"]}, "related": ["cn--9--i01", "cn--9--e01", "cn--17--p01"]},
  {"id": "cn--13--d01", "track": "cn", "year": 13, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "河南魏郡大疫与蝗", "summary": "郡国大疫，飞蝗从东方来，民多饿死。", "detail": {"background": "新室改制既密，北边转输又急，加以河决郡国、师出无时；关东之民先困于役，复因于疫，户口耗减实始于此。", "process": "13年前后，河南、大司农部、魏郡、陈留大疫，又有飞蝗自东方起，蔽天而下，所集无处；吏民因疫死者众，郡国仓廪不能赈，流民入关者且万人。", "impact": "天灾与政弊相因为害：大疫使编户与田租之入骤减，边兵与转输反增，遂为天凤以后四方并起的局面定下了基调，也是绿林赤眉得以扩员的直接原因。", "figures": ["王莽"], "place": "河南、魏郡、陈留", "state": "新", "sources": ["《汉书·五行志》", "《汉书·王莽传》"], "tags": ["大疫", "飞蝗", "流民"]}, "related": ["cn--17--p01", "cn--18--m01"]},
  {"id": "cn--14--e01", "track": "cn", "year": 14, "yearApprox": false, "dim": "economy", "weight": 3, "title": "再改货布货币之制", "summary": "更作货布、货泉二品，废宝货繁目。", "detail": {"background": "宝货二十余品不可行，民间但以谷帛相市，农商失业，而官中铸造犹不止；每一改币则民一次失其业。", "process": "14年罢大小钱，更作货布（长二十五分，直五百）、货泉（重五铢，直一），以二品并行；禁民不得挟五铢、勿敢铸，犯者罪至徙，然私铸不可禁，市价日贵而民益贫。", "impact": "自始建国至天凤，货币四变而民益困：币制与财政既不能信于民，则一切政令随之失信，这是新朝经济崩坏的枢纽，也是光武中元以后专行五铢的教训所由。", "figures": ["王莽"], "place": "长安及郡国", "state": "新", "sources": ["《汉书·食货志》", "《汉书·王莽传》", "新莽货布货泉实物"], "tags": ["货布", "货泉", "币信之失"]}, "related": ["cn--9--e01", "cn--12--i01", "cn--40--e01"]},
  {"id": "cn--16--s01", "track": "cn", "year": 16, "yearApprox": false, "dim": "science", "weight": 3, "title": "路平造铜浑仪刻漏", "summary": "以漏刻度浑仪以候天，昼夜各有中。", "detail": {"background": "律历之家久以浑仪、候度校刻漏之节；莽欲定声律、度、量、衡以明天命，故钟律、权量与天文之器并治于灵台。", "process": "天凤间，命太史待诏典浑仪，考律历于钟律；路平作铜浑仪，令史张衡之属承其业，以漏刻候之，一日夜各有中，以推日月行度与节气之先后。", "impact": "律吕、度、量、衡与浑仪、刻漏在汉末被合成一整套可复验的天文计量体系：此为张衡浑象、候风地动仪之直接前提，也是中国仪器史上第一次以标准时长来校验天文观测。", "figures": ["路平", "王莽"], "place": "长安灵台", "state": "新", "sources": ["《汉书·律历志》", "《晋书·天文志》"], "tags": ["浑仪", "刻漏", "声律度量衡"]}, "related": ["cn--b104--s01", "cn--b28--s01"]},
  {"id": "cn--17--p01", "track": "cn", "year": 17, "yearApprox": false, "dim": "politics", "weight": 4, "title": "绿林起于新莽天凤四年", "summary": "荆州岁饥，流民散入绿林中，推王匡王凤。", "detail": {"background": "天凤三年荆州大水，饥民入野泽掘凫茨而食；地方吏职以苛法相追、以簿书相课，民穷无所诉，遂相率为群。", "process": "17年（天凤四年）新市人王匡、王凤为饥民所推，评其诤讼，藏于绿林山中，数月间至七八千人；又有南郡张霸、羊牧等并起，四方散归之，号新市兵。", "impact": "民之乱起于饥与法之并至：新莽对流民无赈而有督，绿林遂由小盗为大军，五年之间下数郡，十七年间与汉室相始终，是亡新的两股力量之首。", "figures": ["王匡", "王凤"], "place": "绿林山（今湖北大洪山一带）", "state": "新", "sources": ["《汉书·王莽传》", "《后汉书》", "《资治通鉴·汉纪》"], "tags": ["绿林", "流民", "饥民起义"]}, "related": ["cn--b89--p01", "cn--13--d01", "cn--18--m01"]},
  {"id": "cn--18--m01", "track": "cn", "year": 18, "yearApprox": false, "dim": "military", "weight": 3, "title": "樊崇起莒作赤眉军", "summary": "琅邪饥人樊崇起兵，以朱眉相别为号。", "detail": {"background": "关东连年不登，民弃田卖爵而相率为群；琅邪、东海之间饥人尤多，而郡太守不恤，反督以赋役。", "process": "18年（天凤五年）莒人樊崇起兵，先据武城、高鱼，转战入泰山，众至万余；以朱涂眉为号，故名赤眉。军中所约：杀人者死、伤人者偿创，无文书、旗帜、号令，口呼为营。", "impact": "赤眉起于饥民而无士人参与，故能因其粗朴而得众，也因其无政而终不能守；绿林、赤眉两路之合，使新莽在三年内土崩，而两汉之际的农民军从此成为易姓改代的决定力量。", "figures": ["樊崇"], "place": "琅邪、泰山（今山东莒县一带）", "state": "新", "sources": ["《汉书·王莽传》", "《后汉书·刘盆子传》"], "tags": ["赤眉", "流民", "饥民起义"]}, "related": ["cn--17--p01", "cn--23--p01", "cn--26--m01"]},
  {"id": "cn--21--m01", "track": "cn", "year": 21, "yearApprox": true, "dim": "military", "weight": 2, "title": "下江新市兵出荆州", "summary": "绿林分军为二，下江兵入南郡、江北。", "detail": {"background": "新莽发兵四万余人，分道向荆州击绿林，而军粮、簿书皆仰郡县；郡县承平久，吏士不相习，兵出而贼益多。", "process": "21年前后，绿林军以王匡、王凤为纽兵，分其别部入南郡蓝头，号下江兵；时王莽遣太师羲仲景尚等将兵东下，为乱兵所杀；新市兵与舂陵刘伯升起兵会合，共约立宗室。", "impact": "下江兵与舂陵宗室军的联合是起义从饥民之乱变为改朝换代的关键一步，从此有了士人、宗室与地方吏职，其组织水平与赤眉全然不同。", "figures": ["王匡", "刘伯升"], "place": "南郡、江夏", "state": "新", "sources": ["《汉书·王莽传》", "《后汉书·光武帝纪》"], "tags": ["下江兵", "舂陵", "联军"]}, "related": ["cn--17--p01", "cn--22--m01"]},
  {"id": "cn--22--m01", "track": "cn", "year": 22, "yearApprox": false, "dim": "military", "weight": 4, "title": "寻邑百万之围与昆阳之战", "summary": "莽使王邑将天下兵百万，围昆阳，汉军三千陷之。", "detail": {"background": "王莽以昆阳当南北之要，诏大司空王邑、司徒王寻征天下兵，自郡国选练武人，合六十三万人，号称百万。", "process": "23年二月王邑围昆阳，城中惟下江、新市八千人；刘秀以步骑三千为先锋，自城西出冲，斩王寻；会大风大雨、屋瓦皆飞，王莽军大乱溃走，士卒相腾藉，滍水为之不流；莽军辎重、财物、军书不可胜数。", "impact": "昆阳以少敌多，是古代中国最著名的战例之一；其破在于王邑不纳严尤舍南救北、专攻小城之计，也在于新室军众来自四方而不可信。此役后新室军主力不复能用。", "figures": ["刘秀", "王邑", "王寻", "严尤"], "place": "昆阳（今河南叶县）", "state": "新", "sources": ["《后汉书·光武帝纪》", "《汉书·王莽传》", "《资治通鉴·汉纪》"], "tags": ["昆阳之战", "以少击众", "新莽崩溃"]}, "related": ["cn--23--p01", "cn--21--m01", "cn--25--p01"]},
  {"id": "cn--23--p01", "track": "cn", "year": 23, "yearApprox": false, "dim": "politics", "weight": 5, "title": "更始入长安与王莽死", "summary": "三辅兵共起，商人杜吴斩莽于渐台之上。", "detail": {"background": "更始既立，诸将北渡河，关东诸城皆下；王邑败还，新室已不能调兵，惟以读书、铸威斗自慰。", "process": "23年十月申屠建等自武关入，析县人起兵应之；三辅豪桀复共攻长安，商人杜吴杀莽于桂宫，武士斩其头，军人共分肢体，有司烧其宫；汉宫人得莽首送宛，更始传首诣阙，悬于宛市，莽之头后送洛阳，汉之太官烹其肉。", "impact": "新莽亡于工商与乱兵之手：商人杜吴斩莽头一事本身即说明新室连最后的都市支持者亦不能维持。更始入关之始，人心归于刘氏，天下之乱却因更始之政而继续。", "figures": ["王莽", "刘玄", "申屠建"], "place": "长安", "state": "新", "sources": ["《汉书·王莽传》", "《后汉书·刘玄传》", "《资治通鉴·汉纪》"], "tags": ["更始入关", "王莽之死", "新室亡"]}, "related": ["cn--22--m01", "cn--24--p02", "cn--25--p01"]},
  {"id": "cn--24--p02", "track": "cn", "year": 24, "yearApprox": false, "dim": "politics", "weight": 3, "title": "更始都长安而失纪纲", "summary": "拜官千余人，长安为笑，诸将横恣不奉法。", "detail": {"background": "更始入长安，以宗室与诸将分任三公、列侯，而号令不出于一门；将军赵萌、李松各竞其势，日争于殿前。", "process": "24年更始居长安，封诸将数百人，或一日拜吏二千余员；长安语曰斗家炊事、灶家给使；诸将掠民，三辅吏民失望，而更始自乐宴饮，不复亲政。", "impact": "更始一败于无政：士人与地方望风思汉而不得其主，光武得河北、邓禹得关中，皆以更始之失为条件。赤眉、隗嚣随之俱起，天下复入割据之局。", "figures": ["刘玄", "赵萌"], "place": "长安", "state": "更始", "sources": ["《后汉书·刘玄传》", "《资治通鉴·汉纪》"], "tags": ["更始失政", "滥封", "割据再乱"]}, "related": ["cn--23--p01", "cn--25--p01", "cn--26--m01"]},
  {"id": "cn--25--p01", "track": "cn", "year": 25, "yearApprox": false, "dim": "politics", "weight": 4, "title": "光武即位于河北", "summary": "以符命即位于鄗南，改元建武，国号汉。", "detail": {"background": "24年刘秀持节河北，抚降、断狱、除王莽苛政；邓禹、冯异、寇恂相次归附，遂与更始分道，北破铜马、青犊之众于河北，号称铜马帝。", "process": "25年六月己未，即皇帝位于鄗南之阴，设坛场、燎，祭天地，改元曰建武，国号曰汉；以邓禹为大司徒、吴汉为大司马，定都洛阳，号曰东京。", "impact": "东汉自光武起于河北，其规模定于此日；其政治之重心亦由是转于尚书台与南阳、颍川、河北三方士人，而外戚、近习与功臣之制为两汉之异。", "figures": ["刘秀", "邓禹", "吴汉"], "place": "鄗（今河北柏乡）", "state": "东汉", "sources": ["《后汉书·光武帝纪》", "《东观汉记》", "《资治通鉴·汉纪》"], "tags": ["光武即位", "建武", "东汉开端"]}, "related": ["cn--24--p02", "cn--28--c01", "cn--31--i01"]},
  {"id": "cn--25--p02", "track": "cn", "year": 25, "yearApprox": false, "dim": "politics", "weight": 3, "title": "光武都洛阳", "summary": "以河北之地与关东之漕，定都于洛。", "detail": {"background": "长安残破，赤眉之众未平；洛邑当天下之中而有漕运，河北有根本，且关中豪强与更始之党犹在，都之不便。", "process": "25年十月车驾东巡，遂留洛阳，舍于南宫，定以为都；以河北、颍川、南阳三域为根本，罢长安宫庙之修，惟立宗庙、社稷于洛城之中。其后遣吴汉、冯异拒赤眉于崤底，27年正月降其众八万余口，樊崇面缚诣阙。", "impact": "东汉都洛，使国家的重心自西向东转移，河北、颍川、南阳三个士人集团随之得势；关中自此不复为都，中国古都史上一次长久的转移实成于此。", "figures": ["刘秀", "吴汉", "冯异"], "place": "洛阳", "state": "东汉", "sources": ["《后汉书·光武帝纪》", "《东观汉记》"], "tags": ["都洛阳", "地理重心", "崤底之降"]}, "related": ["cn--25--p01", "cn--26--m01"]},
  {"id": "cn--26--m01", "track": "cn", "year": 26, "yearApprox": false, "dim": "military", "weight": 3, "title": "赤眉入长安与宗庙之焚", "summary": "樊崇立刘盆子为帝，入长安，烧宫庙。", "detail": {"background": "赤眉无文书、旗帜，转掠二十余万人而西，与更始诸将相拒于弘农；食尽而遂入关，其势不可复止。", "process": "26年正月赤眉至长安，立刘盆子为帝，年十五；攻入城，更始肉袒降，寻为张卽所杀；赤眉纵兵大掠，发掘茂陵、长安诸陵，烧宫室、宗庙、府库，二岁之间，长安市肆中与人相食。", "impact": "赤眉之祸甚于兵：关中自是虚耗，光武所以能制天下，正在以郡国屯田、赈给流民而得人心，反证流民之乱根在失所而非乐乱。", "figures": ["樊崇", "刘盆子"], "place": "长安", "state": "更始", "sources": ["《后汉书·刘盆子传》", "《汉书·王莽传》", "《资治通鉴·汉纪》"], "tags": ["赤眉入关", "发掘陵寝", "关中残破"]}, "related": ["cn--18--m01", "cn--24--p02", "cn--25--p01"]},
  {"id": "cn--28--c01", "track": "cn", "year": 28, "yearApprox": false, "dim": "culture", "weight": 4, "title": "退功臣而进文吏", "summary": "邓禹、吴汉等以列侯奉朝请，不临职事。", "detail": {"background": "汉室中兴，功臣二十八人并据高爵，多至食邑数县；光武以天下初定，不欲使武人典兵而干吏事。", "process": "建武中，以功臣为列侯、奉朝请而不得为吏，大司马吴汉以下多以骑都尉、列侯奉请；同时征隐逸、用文吏：卓茂、伏湛、侯霸以经行进，以太常、大司徒居相位。", "impact": "以厚禄与高爵换去功臣的权力，是光武留给后世最出名的政治设计；与宋初杯酒释兵权相类而温和得多，代价是士风与吏事之分，文吏、武功两条轨道从此判然。", "figures": ["刘秀", "邓禹", "吴汉", "卓茂"], "place": "洛阳", "state": "东汉", "sources": ["《后汉书·光武帝纪》", "《后汉书·邓寇列传》", "《后汉书·卓茂传》"], "tags": ["退功臣", "文吏政治", "奉朝请"]}, "related": ["cn--25--p01", "cn--30--i01", "cn--b124--i01"]},
  {"id": "cn--30--i01", "track": "cn", "year": 30, "yearApprox": false, "dim": "institution", "weight": 4, "title": "并省四百余县", "summary": "并乐浪九真之远，省县四百，吏员十置其一。", "detail": {"background": "王莽以来户口耗减，郡县多置而吏员繁；光武以军兴之后财用不足，欲以简省官职宽民力而清簿书。", "process": "建武六年（30）前后诏，省吏职，十分置一，并省四百余县，凡乐浪、九真之远与内郡小县皆见省；边郡都尉、属国仍置，且以见官为定制。", "impact": "这是中国史上一次大规模的精兵简政：它使东汉的吏员、赋役规模较西汉缩小，代价是地方行政能力下降，边郡与县乡之政渐委于豪右，为东汉中叶以后的地方割据留了伏笔。", "figures": ["刘秀"], "place": "洛阳及郡国", "state": "东汉", "sources": ["《后汉书·光武帝纪》", "《续汉书·郡国志》"], "tags": ["并省郡县", "精简吏员", "东汉初政"]}, "related": ["cn--28--c01", "cn--40--e01", "cn--39--p01"]},
  {"id": "cn--31--i01", "track": "cn", "year": 31, "yearApprox": true, "dim": "institution", "weight": 3, "title": "六诏释放奴婢与省减刑罚", "summary": "自建武二年至十五年，前后六诏吏民被略为奴婢者免为庶人。", "detail": {"background": "王莽以来，兵连、饥疫相仍，吏民多被掠卖为奴婢；汉世田宅、奴婢本不禁卖，而乱离之民自鬻者不可胜数。", "process": "光武自即位至建武十五年前后，累诏：吏民被青、徐寇贼所略为奴婢者，皆勿听，得自出；遭饥乱而卖为奴婢者，一切免为庶人；又除王莽时苛法，省大辟之条，前后十省，死者岁以千数，谓有减于前。", "impact": "释放奴婢之诏是中国法律史上第一次以全国诏令承认被略者的自由身份，它把身部曲、客与奴婢的界线重画了一次；而十省刑法则定下东汉宽简之名。两者皆以皇权直接干预民间身份，为后来曹魏、西晋的奴婢与部曲立法开了先例。", "figures": ["刘秀"], "place": "洛阳及郡国", "state": "东汉", "sources": ["《后汉书·光武帝纪》", "《资治通鉴·汉纪》"], "tags": ["释放奴婢", "省刑", "身份制度"]}, "related": ["cn--30--i01", "cn--39--p01", "cn--b7--i01"]},
  {"id": "cn--31--s01", "track": "cn", "year": 31, "yearApprox": true, "dim": "science", "weight": 3, "title": "杜诗作水排，以水鼓冶", "summary": "引水流以运排囊鼓炭冶铁，铸农器，用力少见功多。", "detail": {"background": "王莽末兵连、饥疫相仍，南阳民乏农器；建武中杜诗以绩能再见任用，迁南阳太守。史称其性节俭、不劳视事而务在利民。", "process": "建武七年（31）前后于南阳郡「造作水排，铸为农器，用力少，见功多，百姓便之」。排即橐龠（皮橐鼓风之器），旧时以人蹋、以马驮，今引水激轮，循连杆使排囊一开一阖送风入冶，故曰水排；其要在于把回转之运动化为往复之运动。", "impact": "冶铁鼓风自此不必常役人畜，水力既至则排囊自阖，炉温与日冶之数因之可增；此后汉魏以降之铁官与民间铁业皆赖此道。同一机构原理见于水碓、水磨、连磨诸器，是中国水力机械共有的基础。", "figures": ["杜诗"], "place": "南阳郡（今河南南阳）", "state": "东汉", "sources": ["《后汉书·杜诗传》"], "tags": ["水排", "鼓风冶铁", "水力机械"]}, "related": ["cn--31--i01"]},
  {"id": "cn--39--p01", "track": "cn", "year": 39, "yearApprox": false, "dim": "politics", "weight": 3, "title": "度田之诏与青州之乱", "summary": "诏郡国度田比户口，十郡守坐贬死。", "detail": {"background": "天下初定，南阳帝里与诸豪右之家田宅过制，郡国户口不实，赋役由是不平；光武欲以核实为治。", "process": "建武十五年（39）诏州郡度民田、比核户口，务均赋役；郡守以下十数人坐度田不实下狱死，青、徐、幽、冀之豪叛，杀吏以应；光武以张湛等喻之，诛首恶而赦其余，事遂止。", "impact": "度田失败是中国帝国史上的一次决定性事件：皇权无法真正清点豪族的土地，东汉中叶以后田庄与部曲之盛、豪右之不治，其根在此；此后朝廷只能依靠口赋与计簿，而不再能按实田征赋。", "figures": ["刘秀", "张湛"], "place": "洛阳及青徐幽冀", "state": "东汉", "sources": ["《后汉书·光武帝纪》", "《后汉书·刘良传》", "《资治通鉴·汉纪》"], "tags": ["度田", "豪右", "赋役不均"]}, "related": ["cn--30--i01", "cn--b7--i01", "cn--31--i01"]},
  {"id": "cn--40--e01", "track": "cn", "year": 40, "yearApprox": false, "dim": "economy", "weight": 3, "title": "复行五铢钱", "summary": "马援请复五铢，光武许之，天下以为便。", "detail": {"background": "建武初年军兴，布帛、谷食皆当钱用；王莽之货布、货泉犹在民间，轻重无法，故货不得通、谷帛益贵。", "process": "建武十六年（40）伏波将军马援请复铸五铢钱，从之，于是王莽之货布、货泉皆废；民间复以钱为市，农商得通，谷价渐平。", "impact": "五铢之复定东汉一朝的币本，此后八十多年不改，至董卓铸小钱而坏；它同时说明王莽以名物乱币制的失败，光武以恢复旧物为务，正是新汉两朝政治作风之别。", "figures": ["马援", "刘秀"], "place": "洛阳及郡国", "state": "东汉", "sources": ["《后汉书·马援传》", "《后汉书·光武帝纪》", "东汉五铢钱范"], "tags": ["五铢钱", "马援", "币制回复"]}, "related": ["cn--9--e01", "cn--14--e01", "cn--b113--e01"]},
  {"id": "cn--43--x01", "track": "cn", "year": 43, "yearApprox": false, "dim": "explore", "weight": 3, "title": "马援平交趾置二征县", "summary": "楼船将军马援浮海南下，平交趾、九真。", "detail": {"background": "交趾女子征侧、征贰反，攻没郡县六十五城，自立为王；九真、日南与合浦的蛮里皆应之，海上之道不通。", "process": "42—43年马援为伏波将军，率楼船二千余艘，将士二万，浮海至交趾，与贼战于浪泊，斩征侧等，徙其渠帅三百余口于零陵；于其地置二征县，立铜柱为汉之极界。", "impact": "东汉第一次在岭南以海路运兵成功，交趾自此长属中国郡县，而铜柱之说成为后世南海边疆的象征；马援门人之众与军中的疫疾，也见出南方军役的艰难。", "figures": ["马援", "征侧"], "place": "交趾、九真（今越南北部红河三角洲）", "state": "东汉", "sources": ["《后汉书·马援传》", "《后汉书·南蛮传》", "《水经注·温水》"], "tags": ["马援", "交趾", "铜柱"]}, "related": ["cn--b111--i01", "cn--40--e01", "world--40--p01"]},
  {"id": "cn--48--p01", "track": "cn", "year": 48, "yearApprox": false, "dim": "politics", "weight": 4, "title": "南匈奴日逐王比称藩内附", "summary": "日逐王比自立为呼韩邪单于，款五原塞，愿保北边。", "detail": {"background": "王莽末，匈奴复胁乌桓、取西域，北边为寇；光武以天下新定，止于赂遗结好，不能复制单于之庭，而匈奴内部分裂之机已熟。", "process": "48年匈奴日逐王比自立为呼韩邪单于，遣使奉记，愿为藩蔽、求入朝；其众数万落，南边五原、云中、定襄塞下而居。49年汉遣中郎将段郴、副校尉王郁持节即单于庭，赐玺绶、衣冠，置使匈奴中郎将将兵卫护之，南庭自此世为汉保塞。", "impact": "匈奴自此南北分为二庭：南部民户渐入并、雍诸郡，与汉杂居，开了此后内迁胡口的先例；北部退保漠北，终为东汉边功与军费之所系。北匈奴之西迁与草原权力的再编，亦以48年之分为起点。", "figures": ["比", "刘秀", "段郴"], "place": "五原塞（今内蒙古包头一带）与洛阳", "state": "东汉", "sources": ["《后汉书·南匈奴传》", "《后汉书·光武帝纪》", "《资治通鉴·汉纪》"], "tags": ["南匈奴内附", "使匈奴中郎将", "南北分庭"]}, "related": ["cn--b33--p02", "cn--b60--i01", "cn--11--x01"]},
  {"id": "cn--50--s01", "track": "cn", "year": 50, "yearApprox": true, "dim": "science", "weight": 3, "title": "《九章算术》九卷备其目", "summary": "自方田至勾股凡九章二百四十六问，各系术文与答。", "detail": {"background": "先秦至汉，田丈、租赋、粟米交易、工程土方之算累代增益，非一人一时之作；世传张苍、耿寿昌于其所删补有所损益，而本文不著撰人。", "process": "其书九卷（章）：一曰方田、二曰粟米、三曰衰分、四曰少广、五曰商功、六曰均输、七曰盈不足、八方程、九曰勾股，凡二百四十六问，每问先立问、次系术、后出答；「方程」章以算筹直布解联立一次方程组，其正负术曰「同名相除，异名相益」，即正负加减之规；「勾股」章立测望诸法。", "impact": "以「术」为纲、以算为验，定下中国算经的体例；唐国子监算学以《九章》与《海岛》《孙子》《张丘建》诸经为课本，刘徽注本、宋刻本与高丽、日本传本同出一系。算筹十进位值制之布算，于本书诸术见其施用之完整。", "figures": ["张苍", "耿寿昌"], "place": "长安、洛阳", "state": "西汉至东汉", "sources": ["《九章算术·方程》", "《隋书·经籍志》"], "tags": ["九章算术", "算经", "方程"]}, "related": ["cn--263--s01"]},
  {"id": "cn--57--p01", "track": "cn", "year": 57, "yearApprox": false, "dim": "politics", "weight": 3, "title": "明帝即位与吏职修整", "summary": "帝善刑名，数文法，而上下相奉以谨。", "detail": {"background": "中元二年光武崩，太子庄立，是为明帝；帝少而好学，从桓荣受欧阳《尚书》，善刑名之学，能通《春秋》。", "process": "57年明帝即位；永平元年改元，令郎官、尚书各以条课其职，躬耕籍田，以经义自试；数遣使巡行郡国，问鳏寡、不能自存者，赐以谷帛，严斥郡县之欺簿者。", "impact": "明帝之政以综核名实为要，吏职修而刑罚中，与章帝之宽厚相补，史并称明章之治；同时帝好佛法、亲讲经于辟雍，为东汉的宗教与学术开了新局。", "figures": ["刘庄"], "place": "洛阳", "state": "东汉", "sources": ["《后汉书·明帝纪》", "《后汉书·循吏传》"], "tags": ["明帝即位", "综核名实", "籍田之礼"]}, "related": ["cn--28--c01", "cn--59--c01", "cn--57--f01"]},
  {"id": "cn--57--f01", "track": "cn", "year": 57, "yearApprox": false, "dim": "figure", "weight": 3, "title": "王充作论衡于会稽", "summary": "疾俗儒之守文，作《论衡》八十五篇以订虚妄。", "detail": {"background": "王充（27—约97）字仲任，会稽上虞人，师事班彪，家贫无书，常游洛阳市肆，阅所卖书，一见辄能记诵。", "process": "明帝永平之初，充仕郡功曹，以谏争去职，退而居会稽、钱塘之间，作《论衡》八十五篇，讥世俗之虚妄，言天地故、人无意，又疾俗儒信师而是古。", "impact": "《论衡》是汉代最彻底的自然主义与怀疑论之作，以物类相应之理说灾异，以效验征实之法断是非，冲破了谶纬与天人感应的一统；王充之名至魏晋始著，而其对后世反迷信之论影响深远。", "figures": ["王充", "班彪"], "place": "会稽上虞（今浙江上虞）", "state": "东汉", "sources": ["《论衡·自纪》", "《后汉书·王充传》"], "tags": ["论衡", "疾虚妄", "效验之论"]}, "related": ["cn--b98--c01", "cn--59--c01"]},
  {"id": "cn--59--c01", "track": "cn", "year": 59, "yearApprox": false, "dim": "culture", "weight": 3, "title": "明帝亲临辟雍讲论", "summary": "自为通德论，命桓荣讲《尚书》于辟雍。", "detail": {"background": "明帝以经学自修，尊桓荣为帝师；荣受欧阳《尚书》，以授太子，累迁太常、关内侯，赐以辎车乘马。", "process": "59年（永平二年）三雍初成，帝先宗祀光武于明堂，乃临辟雍，令桓荣执经讲《尚书》，自为《通德论》以难之；又行养老、乡射之礼，以弟子之礼见荣。诏天下通经者皆得举于太常，岁以课试为程。", "impact": "皇帝在辟雍以师礼事经师，为太学讲论之礼定了范式：东汉以经学起家之家与太常、博士的关系自此极深，门生、故吏遍天下，弘农杨氏、汝南袁氏四世三公的局面由此而成。", "figures": ["刘庄", "桓荣"], "place": "洛阳辟雍", "state": "东汉", "sources": ["《后汉书·桓荣传》", "《后汉书·明帝纪》"], "tags": ["皇帝讲学", "经学家族", "辟雍之礼"]}, "related": ["cn--b124--i01", "cn--2--i01", "cn--57--f01"]},
];
